const KEYWORD_OR_PRECEDENCE: u8 = 1;
const KEYWORD_XOR_PRECEDENCE: u8 = 2;
const KEYWORD_AND_PRECEDENCE: u8 = 3;
const SYMBOL_OR_PRECEDENCE: u8 = 4;
const COALESCE_PRECEDENCE: u8 = 4;
const PIPE_PRECEDENCE: u8 = 11;
const SYMBOL_AND_PRECEDENCE: u8 = 5;
const BITWISE_OR_PRECEDENCE: u8 = 6;
const BITWISE_XOR_PRECEDENCE: u8 = 7;
const BITWISE_AND_PRECEDENCE: u8 = 8;
const EQUALITY_PRECEDENCE: u8 = 9;
const COMPARISON_PRECEDENCE: u8 = 10;
const CONCAT_PRECEDENCE: u8 = 13;
const SHIFT_PRECEDENCE: u8 = 18;
const ADDITIVE_PRECEDENCE: u8 = 23;
const MULTIPLICATIVE_PRECEDENCE: u8 = 33;
const POWER_PRECEDENCE: u8 = 40;
const CLASS_CONSTANT_FETCH_UNSUPPORTED: &str =
    "class constant fetches are unsupported; class constants and enum cases require class metadata";
const NULLSAFE_WRITE_CONTEXT_MESSAGE: &str = "Can't use nullsafe operator in write context";
const TEMPORARY_WRITE_CONTEXT_MESSAGE: &str = "Cannot use temporary expression in write context";
const ISSET_RESULT_EXPRESSION_MESSAGE: &str =
    "Cannot use isset() on the result of an expression (you can use \"null !== expression\" instead)";
const NULLSAFE_REFERENCE_MESSAGE: &str = "Cannot take reference of a nullsafe chain";
const INVALID_FIRST_CLASS_CALLABLE_PLACEHOLDER_MESSAGE: &str =
    "Cannot create a Closure for call expression with more than one argument, or non-variadic placeholders";
const MAX_ARRAY_LITERAL_NESTING: usize = 128;

fn nullsafe_write_context_diagnostic(span: SourceSpan) -> Diagnostic {
    Diagnostic::new(NULLSAFE_WRITE_CONTEXT_MESSAGE, Some(span))
}

fn nullsafe_reference_diagnostic(span: SourceSpan) -> Diagnostic {
    Diagnostic::new(NULLSAFE_REFERENCE_MESSAGE, Some(span))
}

fn is_nullsafe_write_context_diagnostic(diagnostic: &Diagnostic) -> bool {
    diagnostic.message == NULLSAFE_WRITE_CONTEXT_MESSAGE
}

pub fn parse(source: &str) -> Result<Program> {
    parse_with_runtime_class_aliases(source, &HashMap::new())
}

pub(crate) fn parse_for_include_collection(
    source: &str,
    runtime_class_aliases: &HashMap<String, String>,
) -> Result<Program> {
    parse_with_options(source, runtime_class_aliases, &[], &[], false, false, false)
}

pub(crate) fn parse_with_runtime_class_aliases(
    source: &str,
    runtime_class_aliases: &HashMap<String, String>,
) -> Result<Program> {
    parse_with_options(source, runtime_class_aliases, &[], &[], true, true, false)
}

pub(crate) fn parse_with_runtime_class_aliases_and_symbols(
    source: &str,
    runtime_class_aliases: &HashMap<String, String>,
    external_classes: &[ClassDecl],
    external_traits: &[TraitDecl],
) -> Result<Program> {
    parse_with_options(
        source,
        runtime_class_aliases,
        external_classes,
        external_traits,
        true,
        true,
        false,
    )
}

pub(crate) fn parse_include_with_runtime_class_aliases_and_symbols(
    source: &str,
    runtime_class_aliases: &HashMap<String, String>,
    external_classes: &[ClassDecl],
    external_traits: &[TraitDecl],
) -> Result<Program> {
    parse_with_options(
        source,
        runtime_class_aliases,
        external_classes,
        external_traits,
        true,
        false,
        false,
    )
}

fn parse_with_options(
    source: &str,
    runtime_class_aliases: &HashMap<String, String>,
    external_classes: &[ClassDecl],
    external_traits: &[TraitDecl],
    validate_method_signatures: bool,
    validate_function_names: bool,
    force_top_level_declarations_conditional: bool,
) -> Result<Program> {
    let lexed = lex_with_warnings(source)?;
    let tokens = lexed.tokens;
    let compiler_halt_offset = find_compiler_halt_offset(&tokens);
    let mut parser = Parser {
        source,
        tokens,
        index: 0,
        block_depth: 0,
        function_depth: 0,
        method_depth: 0,
        current_namespace: None,
        seen_namespace_declaration: false,
        namespace_declaration_style: None,
        class_aliases: HashMap::new(),
        function_aliases: HashMap::new(),
        constant_aliases: HashMap::new(),
        seen_class_symbols: HashMap::new(),
        seen_function_symbols: HashMap::new(),
        seen_constant_symbols: HashMap::new(),
        runtime_class_aliases: runtime_class_aliases.clone(),
        external_classes: external_classes.to_vec(),
        external_traits: external_traits.to_vec(),
        eval_string_constants: HashMap::new(),
        eval_scalar_variables: HashMap::new(),
        eval_visible_classes: external_classes.to_vec(),
        eval_visible_traits: external_traits.to_vec(),
        declared_functions: HashSet::new(),
        declared_constants: HashSet::new(),
        declared_class_names: HashMap::new(),
        anonymous_classes: Vec::new(),
        anonymous_traits: Vec::new(),
        nested_functions: Vec::new(),
        anonymous_class_name_counts: HashMap::new(),
        allow_append_array_read: false,
        allow_standalone_list_array_element: false,
        active_type_scope: None,
        anonymous_function_depth: 0,
        allow_unscoped_relative_types: 0,
        allow_unscoped_constant_relative_class_member_fetch: 0,
        allow_void_cast_expression: 0,
        array_literal_depth: 0,
        return_by_ref_stack: Vec::new(),
        property_hook_body_depth: 0,
        active_property_hook_scope: None,
        strict_types: false,
        ticks: false,
        strict_types_declare_allowed: true,
        compiler_halt_offset,
        compile_warnings: lexed.compile_warnings,
        validate_method_signatures,
        validate_function_names,
        force_top_level_declarations_conditional,
        current_statement_doc_comment: None,
    };
    parser.parse_program().map_err(|error| {
        error.with_notices(diagnostic_notices_from_compile_warnings(
            &parser.compile_warnings,
        ))
    })
}

fn diagnostic_notices_from_compile_warnings(warnings: &[CompileWarning]) -> Vec<DiagnosticNotice> {
    warnings
        .iter()
        .map(|warning| DiagnosticNotice {
            message: warning.message.clone(),
            span: warning.span,
            kind: diagnostic_notice_kind_from_compile_warning_kind(warning.kind),
        })
        .collect()
}

fn diagnostic_notice_kind_from_compile_warning_kind(
    kind: CompileWarningKind,
) -> DiagnosticNoticeKind {
    match kind {
        CompileWarningKind::Warning => DiagnosticNoticeKind::Warning,
        CompileWarningKind::UncaughtError => DiagnosticNoticeKind::UncaughtError,
        CompileWarningKind::Deprecation => DiagnosticNoticeKind::Deprecation,
    }
}

struct Parser<'a> {
    source: &'a str,
    tokens: Vec<Token>,
    index: usize,
    block_depth: usize,
    function_depth: usize,
    method_depth: usize,
    current_namespace: Option<String>,
    seen_namespace_declaration: bool,
    namespace_declaration_style: Option<NamespaceDeclarationStyle>,
    class_aliases: HashMap<String, String>,
    function_aliases: HashMap<String, String>,
    constant_aliases: HashMap<String, String>,
    seen_class_symbols: HashMap<String, String>,
    seen_function_symbols: HashMap<String, String>,
    seen_constant_symbols: HashMap<String, String>,
    runtime_class_aliases: HashMap<String, String>,
    external_classes: Vec<ClassDecl>,
    external_traits: Vec<TraitDecl>,
    eval_string_constants: HashMap<String, String>,
    eval_scalar_variables: HashMap<String, EvalScalarValue>,
    eval_visible_classes: Vec<ClassDecl>,
    eval_visible_traits: Vec<TraitDecl>,
    declared_functions: HashSet<String>,
    declared_constants: HashSet<String>,
    declared_class_names: HashMap<String, SourceSpan>,
    anonymous_classes: Vec<ClassDecl>,
    anonymous_traits: Vec<TraitDecl>,
    nested_functions: Vec<FunctionDecl>,
    anonymous_class_name_counts: HashMap<String, usize>,
    allow_append_array_read: bool,
    allow_standalone_list_array_element: bool,
    active_type_scope: Option<ActiveTypeScope>,
    anonymous_function_depth: usize,
    allow_unscoped_relative_types: usize,
    allow_unscoped_constant_relative_class_member_fetch: usize,
    allow_void_cast_expression: usize,
    array_literal_depth: usize,
    return_by_ref_stack: Vec<bool>,
    property_hook_body_depth: usize,
    active_property_hook_scope: Option<ActivePropertyHookScope>,
    strict_types: bool,
    ticks: bool,
    strict_types_declare_allowed: bool,
    compiler_halt_offset: Option<i64>,
    compile_warnings: Vec<CompileWarning>,
    validate_method_signatures: bool,
    validate_function_names: bool,
    force_top_level_declarations_conditional: bool,
    current_statement_doc_comment: Option<String>,
}

#[derive(Clone)]
enum EvalScalarValue {
    Int(i64),
    String(String),
}

impl EvalScalarValue {
    fn to_interpolated_string(&self) -> String {
        match self {
            Self::Int(value) => value.to_string(),
            Self::String(value) => value.clone(),
        }
    }
}

