fn modeled_builtin_interface_extends(interface_name: &str, target_name: &str) -> bool {
    let interface_name = interface_name.trim_start_matches('\\').to_ascii_lowercase();
    let target_name = target_name.trim_start_matches('\\').to_ascii_lowercase();
    if interface_name == target_name {
        return true;
    }
    matches!(
        (interface_name.as_str(), target_name.as_str()),
        ("iterator", "traversable")
            | ("iteratoraggregate", "traversable")
            | ("outeriterator", "iterator")
            | ("outeriterator", "traversable")
            | ("recursiveiterator", "iterator")
            | ("recursiveiterator", "traversable")
            | ("seekableiterator", "iterator")
            | ("seekableiterator", "traversable")
    )
}

fn visibility_allows_set_visibility(
    read_visibility: PropertyVisibility,
    set_visibility: PropertyVisibility,
) -> bool {
    visibility_rank(set_visibility) >= visibility_rank(read_visibility)
}

fn validate_asymmetric_property_visibility(
    class_name: &str,
    property_name: &str,
    read_visibility: PropertyVisibility,
    set_visibility: PropertyVisibility,
    span: SourceSpan,
) -> Result<()> {
    if visibility_allows_set_visibility(read_visibility, set_visibility) {
        return Ok(());
    }
    Err(Diagnostic::new(
        format!(
            "Visibility of property {class_name}::${property_name} must not be weaker than set visibility"
        ),
        Some(span),
    ))
}

fn validate_property_hook_modifiers(
    is_final: bool,
    is_abstract: bool,
    visibility: PropertyVisibility,
    span: SourceSpan,
) -> Result<()> {
    if is_final && visibility == PropertyVisibility::Private {
        return Err(Diagnostic::new(
            "Property hook cannot be both final and private",
            Some(span),
        ));
    }
    if is_final && is_abstract {
        return Err(Diagnostic::new(
            "Property hook cannot be both abstract and final",
            Some(span),
        ));
    }
    if is_abstract && visibility == PropertyVisibility::Private {
        return Err(Diagnostic::new(
            "Property hook cannot be both abstract and private",
            Some(span),
        ));
    }
    Ok(())
}

fn reject_asymmetric_virtual_property_hook_metadata(
    class_name: &str,
    property_name: &str,
    visibility: PropertyVisibility,
    set_visibility: PropertyVisibility,
    hooks: &ParsedPropertyHookBlock,
    span: SourceSpan,
) -> Result<()> {
    if set_visibility == visibility || !hooks.is_virtual || (hooks.has_get && hooks.has_set) {
        return Ok(());
    }
    let hook_kind = match (hooks.has_get, hooks.has_set) {
        (true, false) => "get-only",
        (false, true) => "set-only",
        _ => "virtual",
    };
    Err(Diagnostic::new(
        format!(
            "{hook_kind} virtual property {class_name}::${property_name} must not specify asymmetric visibility"
        ),
        Some(span),
    ))
}

fn promoted_properties_from_constructor(
    method: &MethodDecl,
    class_is_readonly: bool,
) -> Vec<PropertyDecl> {
    method
        .parameters
        .iter()
        .filter_map(|parameter| {
            let promoted = parameter.promoted_property.as_ref()?;
            Some(PropertyDecl {
                name: parameter.name.clone(),
                declaring_class_name: None,
                trait_name: None,
                visibility: promoted.visibility,
                set_visibility: promoted.set_visibility,
                is_final: promoted.is_final,
                is_abstract: false,
                is_readonly: class_is_readonly || promoted.is_readonly,
                is_promoted: true,
                has_hooks: promoted.has_hooks,
                is_virtual: promoted.is_virtual,
                hook_has_get: promoted.hook_has_get,
                hook_has_set: promoted.hook_has_set,
                hook_get_is_final: promoted.hook_get_is_final,
                hook_get_is_abstract: promoted.hook_get_is_abstract,
                hook_get_returns_by_ref: promoted.hook_get_returns_by_ref,
                hook_set_is_final: promoted.hook_set_is_final,
                hook_set_is_abstract: promoted.hook_set_is_abstract,
                hook_get_override_span: promoted.hook_get_override_span,
                hook_set_override_span: promoted.hook_set_override_span,
                hook_get_attributes: promoted.hook_get_attributes.clone(),
                hook_set_attributes: promoted.hook_set_attributes.clone(),
                hook_get_doc_comment: promoted.hook_get_doc_comment.clone(),
                hook_set_doc_comment: promoted.hook_set_doc_comment.clone(),
                hook_get_span: promoted.hook_get_span,
                hook_set_span: promoted.hook_set_span,
                hook_get_value: promoted.hook_get_value.clone(),
                hook_set_value: promoted.hook_set_value.clone(),
                hook_get_body: promoted.hook_get_body.clone(),
                hook_set_body: promoted.hook_set_body.clone(),
                hook_set_parameter_name: promoted.hook_set_parameter_name.clone(),
                hook_set_parameter_attributes: promoted.hook_set_parameter_attributes.clone(),
                hook_set_parameter_type: promoted.hook_set_parameter_type.clone(),
                hook_set_parameter_doc_comment: promoted.hook_set_parameter_doc_comment.clone(),
                hook_set_parameter_span: promoted.hook_set_parameter_span,
                hook_set_parameter_is_explicit: promoted.hook_set_parameter_is_explicit,
                type_hint: parameter
                    .type_hint
                    .as_ref()
                    .map(property_type_hint_from_type_hint),
                attributes: parameter.attributes.clone(),
                doc_comment: promoted.doc_comment.clone(),
                has_override_attribute: promoted.has_override_attribute,
                value: None,
                span: promoted.span,
            })
        })
        .collect()
}

fn constructor_promoted_property_assignments(parameters: &[FunctionParameter]) -> Vec<Statement> {
    parameters
        .iter()
        .filter(|parameter| parameter.promoted_property.is_some())
        .map(|parameter| {
            let span = parameter.span;
            let target = AssignmentTarget::Property {
                receiver: Box::new(Expr::Variable("this".to_string(), span)),
                name: parameter.name.clone(),
                span,
            };
            if parameter.by_ref {
                return Statement::Expression {
                    expression: Expr::AssignRef {
                        target,
                        source: Box::new(Expr::Variable(parameter.name.clone(), span)),
                        span,
                    },
                    span,
                };
            }
            Statement::Expression {
                expression: Expr::Assign {
                    target,
                    op: AssignmentOp::Assign,
                    value: Box::new(Expr::Variable(parameter.name.clone(), span)),
                    span,
                },
                span,
            }
        })
        .collect()
}

fn visibility_rank(visibility: PropertyVisibility) -> u8 {
    match visibility {
        PropertyVisibility::Public => 0,
        PropertyVisibility::Protected => 1,
        PropertyVisibility::Private => 2,
    }
}

fn property_visibility_name(visibility: PropertyVisibility) -> &'static str {
    match visibility {
        PropertyVisibility::Public => "public",
        PropertyVisibility::Protected => "protected",
        PropertyVisibility::Private => "private",
    }
}

fn default_set_visibility(
    read_visibility: PropertyVisibility,
    is_readonly: bool,
) -> PropertyVisibility {
    if !is_readonly {
        return read_visibility;
    }
    match read_visibility {
        PropertyVisibility::Public | PropertyVisibility::Protected => PropertyVisibility::Protected,
        PropertyVisibility::Private => PropertyVisibility::Private,
    }
}

fn token_is_identifier_named(token: &Token, expected: &str) -> bool {
    matches!(&token.kind, TokenKind::Identifier(name) if name.eq_ignore_ascii_case(expected))
}

fn token_is_statement_only_keyword(kind: &TokenKind) -> bool {
    matches!(
        kind,
        TokenKind::Echo
            | TokenKind::If
            | TokenKind::Elseif
            | TokenKind::Else
            | TokenKind::Do
            | TokenKind::While
            | TokenKind::For
            | TokenKind::Foreach
            | TokenKind::As
            | TokenKind::Switch
            | TokenKind::Case
            | TokenKind::Default
            | TokenKind::Break
            | TokenKind::Continue
            | TokenKind::Return
            | TokenKind::Try
            | TokenKind::Catch
            | TokenKind::Goto
            | TokenKind::Const
            | TokenKind::Global
    )
}

fn is_exit_construct_name(name: &str) -> bool {
    name.eq_ignore_ascii_case("exit") || name.eq_ignore_ascii_case("die")
}

fn exit_reserved_name_syntax_error(token: &Token, expecting: &str) -> Diagnostic {
    Diagnostic::parse_error(
        format!("syntax error, unexpected token \"exit\", expecting {expecting}"),
        Some(token.span),
    )
}

fn token_starts_type_hint_atom(token: &Token) -> bool {
    matches!(
        token.kind,
        TokenKind::LeftParen
            | TokenKind::Backslash
            | TokenKind::Null
            | TokenKind::IntType
            | TokenKind::IntegerType
            | TokenKind::FloatType
            | TokenKind::DoubleType
            | TokenKind::StringType
            | TokenKind::BinaryType
            | TokenKind::BoolType
            | TokenKind::BooleanType
            | TokenKind::Identifier(_)
    )
}

fn normalize_runtime_class_alias_key(name: &str) -> String {
    normalize_runtime_class_alias_target(name).to_ascii_lowercase()
}

fn normalize_runtime_class_alias_target(name: &str) -> String {
    name.trim_start_matches('\\').to_string()
}

fn literal_member_name_from_expr(expr: &Expr) -> Option<String> {
    match expr {
        Expr::String(value, _) if !value.contains('\0') => Some(value.clone()),
        Expr::Int(value, _) => Some(value.to_string()),
        Expr::DynamicVariable { name, .. } => literal_member_name_from_expr(name),
        _ => None,
    }
}

fn source_contains_ascii_keyword(source: &str, keyword: &str) -> bool {
    source
        .split(|ch: char| !(ch == '_' || ch.is_ascii_alphanumeric()))
        .any(|part| part == keyword)
}

fn source_may_contain_class_property_declaration(lower_source: &str) -> bool {
    lower_source.contains('$')
        && ["public", "protected", "private", "var"]
            .iter()
            .any(|keyword| source_contains_ascii_keyword(lower_source, keyword))
}

fn reject_named_language_construct_arguments(
    argument_names: &[Option<String>],
    span: SourceSpan,
) -> Result<()> {
    if argument_names.iter().any(Option::is_some) {
        return Err(Diagnostic::new(
            "named arguments are unsupported for this language construct",
            Some(span),
        ));
    }
    Ok(())
}

fn reject_unpacked_language_construct_arguments(
    argument_unpacks: &[bool],
    span: SourceSpan,
) -> Result<()> {
    if argument_unpacks.iter().any(|unpack| *unpack) {
        return Err(Diagnostic::new(
            "argument unpacking is unsupported for this language construct",
            Some(span),
        ));
    }
    Ok(())
}

fn compose_traits(
    traits: &mut [TraitDecl],
    global_constant_values: &HashMap<String, ConstExprStaticValue>,
) -> Result<()> {
    let originals = traits.to_vec();
    let mut cache = HashMap::new();
    let mut visiting = HashSet::new();
    for trait_decl in traits {
        *trait_decl = compose_trait_decl(
            &trait_decl.name,
            &originals,
            &mut visiting,
            &mut cache,
            global_constant_values,
        )?;
    }
    Ok(())
}

fn compose_trait_decl(
    name: &str,
    traits: &[TraitDecl],
    visiting: &mut HashSet<String>,
    cache: &mut HashMap<String, TraitDecl>,
    global_constant_values: &HashMap<String, ConstExprStaticValue>,
) -> Result<TraitDecl> {
    let lookup_name = name.to_ascii_lowercase();
    if let Some(cached) = cache.get(&lookup_name) {
        return Ok(cached.clone());
    }
    if !visiting.insert(lookup_name.clone()) {
        return Err(Diagnostic::new(
            format!("Trait \"{name}\" circular reference detected"),
            None,
        ));
    }
    let Some(trait_decl) = traits
        .iter()
        .find(|candidate| candidate.name.eq_ignore_ascii_case(name))
    else {
        visiting.remove(&lookup_name);
        return Err(Diagnostic::new(format!("Trait \"{name}\" not found"), None));
    };
    let mut composed = trait_decl.clone();
    let mut used_traits = Vec::new();
    for trait_use in &trait_decl.trait_uses {
        let used_trait = compose_trait_decl(
            &trait_use.name,
            traits,
            visiting,
            cache,
            global_constant_values,
        )?;
        used_traits.push(used_trait);
    }
    let used_trait_refs = used_traits.iter().collect::<Vec<_>>();
    validate_trait_use_adaptations(
        &trait_decl.name,
        &trait_decl.trait_uses,
        traits,
        &used_trait_refs,
        None,
    )?;
    for (trait_use, used_trait) in trait_decl.trait_uses.iter().zip(used_traits.iter()) {
        import_trait_members_into_trait(
            &mut composed,
            used_trait,
            trait_use,
            global_constant_values,
        )?;
    }
    visiting.remove(&lookup_name);
    cache.insert(lookup_name, composed.clone());
    Ok(composed)
}

fn validate_trait_use_adaptations(
    composer_name: &str,
    trait_uses: &[TraitUseDecl],
    all_traits: &[TraitDecl],
    used_traits: &[&TraitDecl],
    non_trait_names: Option<&HashSet<String>>,
) -> Result<()> {
    validate_duplicate_trait_precedence_exclusions(trait_uses)?;
    for (index, trait_use) in trait_uses.iter().enumerate() {
        if trait_use.adaptations.is_empty()
            || trait_uses
                .iter()
                .take(index)
                .any(|previous| previous.adaptations == trait_use.adaptations)
        {
            continue;
        }
        let adaptation_traits = used_traits
            .iter()
            .copied()
            .filter(|trait_decl| {
                trait_uses.iter().any(|candidate| {
                    candidate.adaptations == trait_use.adaptations
                        && candidate.name.eq_ignore_ascii_case(&trait_decl.name)
                })
            })
            .collect::<Vec<_>>();
        for adaptation in &trait_use.adaptations {
            match adaptation {
                TraitAdaptation::Alias(alias) => {
                    if let Some(trait_name) = &alias.method.trait_name {
                        validate_adaptation_trait_reference(
                            trait_name,
                            composer_name,
                            alias.method.span,
                            all_traits,
                            &adaptation_traits,
                            non_trait_names,
                        )?;
                    }
                    if alias.method.trait_name.is_none() {
                        if let Some((first, second)) =
                            ambiguous_trait_method_reference(&alias.method.method_name, used_traits)
                        {
                            let method_name = &alias.method.method_name;
                            return Err(Diagnostic::new(
                                format!(
                                    "An alias was defined for method {method_name}(), which exists in both {first} and {second}. Use {first}::{method_name} or {second}::{method_name} to resolve the ambiguity"
                                ),
                                Some(alias.span),
                            ));
                        }
                    }
                    if trait_method_reference_exists(&alias.method, &adaptation_traits) {
                        continue;
                    }
                    let method_name = &alias.method.method_name;
                    if let Some(alias_name) = &alias.alias {
                        let referenced_method = trait_method_reference_label(&alias.method);
                        let message = if alias.method.trait_name.is_some() {
                            format!(
                                "An alias was defined for {referenced_method} but this method does not exist"
                            )
                        } else {
                            format!(
                                "An alias ({alias_name}) was defined for {referenced_method}, but this method does not exist"
                            )
                        };
                        return Err(Diagnostic::new(message, Some(alias.span)));
                    }
                    return Err(Diagnostic::new(
                        format!(
                            "The modifiers of the trait method {method_name}() are changed, but this method does not exist. Error"
                        ),
                        Some(alias.span),
                    ));
                }
                TraitAdaptation::Precedence(precedence) => {
                    if let Some(preferred_trait) = &precedence.method.trait_name {
                        validate_adaptation_trait_reference(
                            preferred_trait,
                            composer_name,
                            precedence.method.span,
                            all_traits,
                            &adaptation_traits,
                            non_trait_names,
                        )?;
                        if precedence
                            .instead_of
                            .iter()
                            .any(|excluded| excluded.eq_ignore_ascii_case(preferred_trait))
                        {
                            return Err(Diagnostic::new(
                                format!(
                                    "Inconsistent insteadof definition. The method {} is to be used from {preferred_trait}, but {preferred_trait} is also on the exclude list",
                                    precedence.method.method_name
                                ),
                                Some(precedence.span),
                            ));
                        }
                    }
                    for excluded_trait in &precedence.instead_of {
                        validate_adaptation_trait_reference(
                            excluded_trait,
                            composer_name,
                            precedence.span,
                            all_traits,
                            used_traits,
                            non_trait_names,
                        )?;
                    }
                    if !trait_method_reference_exists(&precedence.method, &adaptation_traits) {
                        let referenced_method = trait_method_reference_label(&precedence.method);
                        return Err(Diagnostic::new(
                            format!(
                                "A precedence rule was defined for {referenced_method} but this method does not exist"
                            ),
                            Some(precedence.span),
                        ));
                    }
                }
            }
        }
    }
    Ok(())
}

fn validate_duplicate_trait_precedence_exclusions(trait_uses: &[TraitUseDecl]) -> Result<()> {
    let mut excluded_methods = HashSet::new();
    for (index, trait_use) in trait_uses.iter().enumerate() {
        if trait_use.adaptations.is_empty()
            || trait_uses
                .iter()
                .take(index)
                .any(|previous| previous.adaptations == trait_use.adaptations)
        {
            continue;
        }
        for adaptation in &trait_use.adaptations {
            let TraitAdaptation::Precedence(precedence) = adaptation else {
                continue;
            };
            for excluded_trait in &precedence.instead_of {
                let key = (
                    precedence.method.method_name.to_ascii_lowercase(),
                    excluded_trait.to_ascii_lowercase(),
                );
                if !excluded_methods.insert(key) {
                    return Err(Diagnostic::new(
                        format!(
                            "Failed to evaluate a trait precedence ({}). Method of trait {excluded_trait} was defined to be excluded multiple times",
                            precedence.method.method_name
                        ),
                        Some(precedence.span),
                    ));
                }
            }
        }
    }
    Ok(())
}

fn ambiguous_trait_method_reference(
    method_name: &str,
    traits: &[&TraitDecl],
) -> Option<(String, String)> {
    let mut matches = traits.iter().filter(|trait_decl| {
        trait_decl
            .methods
            .iter()
            .any(|method| method.name.eq_ignore_ascii_case(method_name))
    });
    let first = matches.next()?;
    let second = matches.next()?;
    Some((first.name.clone(), second.name.clone()))
}

fn validate_adaptation_trait_reference(
    trait_name: &str,
    composer_name: &str,
    span: SourceSpan,
    all_traits: &[TraitDecl],
    used_traits: &[&TraitDecl],
    non_trait_names: Option<&HashSet<String>>,
) -> Result<()> {
    reject_reserved_trait_reference(trait_name, span)?;
    if used_traits
        .iter()
        .any(|trait_decl| trait_decl.name.eq_ignore_ascii_case(trait_name))
    {
        return Ok(());
    }
    if all_traits
        .iter()
        .any(|trait_decl| trait_decl.name.eq_ignore_ascii_case(trait_name))
    {
        return Err(Diagnostic::new(
            format!("Required Trait {trait_name} wasn't added to {composer_name}"),
            Some(span),
        ));
    }
    if non_trait_names.is_some_and(|names| names.contains(&trait_name.to_ascii_lowercase())) {
        return Err(Diagnostic::new(
            format!(
                "Class {trait_name} is not a trait, Only traits may be used in 'as' and 'insteadof' statements"
            ),
            Some(span),
        ));
    }
    Err(Diagnostic::new(
        format!("Could not find trait {trait_name}"),
        Some(span),
    ))
}

fn reject_reserved_trait_reference(name: &str, span: SourceSpan) -> Result<()> {
    if let Some(reserved_name) = reserved_class_name_segment(&name.to_ascii_lowercase()) {
        return Err(Diagnostic::new(
            format!("Cannot use \"{reserved_name}\" as trait name, as it is reserved"),
            Some(span),
        ));
    }
    Ok(())
}

fn trait_method_reference_label(reference: &TraitMethodReference) -> String {
    if let Some(trait_name) = &reference.trait_name {
        format!("{trait_name}::{}", reference.method_name)
    } else {
        format!("method {}()", reference.method_name)
    }
}

fn trait_method_reference_exists(reference: &TraitMethodReference, traits: &[&TraitDecl]) -> bool {
    traits.iter().any(|trait_decl| {
        reference
            .trait_name
            .as_deref()
            .is_none_or(|name| name.eq_ignore_ascii_case(&trait_decl.name))
            && trait_decl
                .methods
                .iter()
                .any(|method| method.name.eq_ignore_ascii_case(&reference.method_name))
    })
}

fn import_trait_members_into_trait(
    target: &mut TraitDecl,
    source: &TraitDecl,
    trait_use: &TraitUseDecl,
    global_constant_values: &HashMap<String, ConstExprStaticValue>,
) -> Result<()> {
    for property in &source.properties {
        if let Some(existing) = target
            .properties
            .iter()
            .find(|candidate| candidate.name == property.name)
        {
            validate_composed_property_compatibility(
                &target.name,
                &source.name,
                &target.name,
                existing,
                property,
                target.span,
                global_constant_values,
            )?;
        } else if target
            .static_properties
            .iter()
            .any(|candidate| candidate.name == property.name)
        {
            validate_composed_property_kind_compatibility(
                &target.name,
                &source.name,
                &target.name,
                &property.name,
                target.span,
            )?;
        } else {
            let mut imported = property.clone();
            imported
                .declaring_class_name
                .get_or_insert_with(|| source.name.clone());
            imported
                .trait_name
                .get_or_insert_with(|| source.name.clone());
            target.properties.push(imported);
        }
    }
    for property in &source.static_properties {
        if let Some(existing) = target
            .static_properties
            .iter()
            .find(|candidate| candidate.name == property.name)
        {
            validate_composed_static_property_compatibility(
                &target.name,
                &source.name,
                &target.name,
                existing,
                property,
                target.span,
                global_constant_values,
            )?;
        } else if target
            .properties
            .iter()
            .any(|candidate| candidate.name == property.name)
        {
            validate_composed_property_kind_compatibility(
                &target.name,
                &source.name,
                &target.name,
                &property.name,
                target.span,
            )?;
        } else {
            target.static_properties.push(property.clone());
        }
    }
    for constant in &source.constants {
        if let Some(existing) = target
            .constants
            .iter()
            .find(|candidate| candidate.name.eq_ignore_ascii_case(&constant.name))
        {
            validate_composed_constant_compatibility(
                &target.name,
                &source.name,
                &target.name,
                existing,
                constant,
                target.span,
                global_constant_values,
            )?;
        } else {
            target.constants.push(constant.clone());
        }
    }
    for method in &source.methods {
        import_trait_method_into_method_list(&mut target.methods, source, trait_use, method)?;
    }
    Ok(())
}

fn compose_class_traits(
    classes: &mut [ClassDecl],
    traits: &[TraitDecl],
    global_constant_values: &HashMap<String, ConstExprStaticValue>,
) -> Result<()> {
    let class_snapshot = classes.to_vec();
    let non_trait_names = classes
        .iter()
        .map(|class| class.name.to_ascii_lowercase())
        .collect::<HashSet<_>>();
    for class in classes {
        if class.trait_uses.is_empty() {
            continue;
        }
        let own_method_names = class
            .methods
            .iter()
            .map(|method| method.name.to_ascii_lowercase())
            .collect::<HashSet<_>>();
        let parent_concrete_method_names =
            visible_parent_concrete_method_names(class, &class_snapshot);
        let mut imported_method_names = HashSet::new();
        let mut property_origins = class
            .properties
            .iter()
            .map(|property| (property.name.clone(), class.name.clone()))
            .collect::<HashMap<_, _>>();
        let mut static_property_origins = class
            .static_properties
            .iter()
            .map(|property| (property.name.clone(), class.name.clone()))
            .collect::<HashMap<_, _>>();
        let mut constant_origins = class
            .constants
            .iter()
            .map(|constant| (constant.name.to_ascii_lowercase(), class.name.clone()))
            .collect::<HashMap<_, _>>();
        let trait_uses = class.trait_uses.clone();
        let mut used_trait_pairs = Vec::new();
        let mut trait_resolution_failed = false;
        for trait_use in &trait_uses {
            let Some(trait_decl) = traits
                .iter()
                .find(|candidate| candidate.name.eq_ignore_ascii_case(&trait_use.name))
            else {
                let lowered_trait_name = trait_use.name.to_ascii_lowercase();
                if trait_use.adaptations.is_empty()
                    && internal_trait_available_for_runtime_use(&trait_use.name)
                {
                    continue;
                }
                if class.is_conditionally_declared
                    && reserved_class_name_segment(&lowered_trait_name).is_none()
                    && !non_trait_names.contains(&lowered_trait_name)
                {
                    continue;
                }
                let message =
                    if let Some(reserved_name) = reserved_class_name_segment(&lowered_trait_name) {
                        format!("Cannot use \"{reserved_name}\" as trait name, as it is reserved")
                    } else if non_trait_names.contains(&lowered_trait_name) {
                        format!(
                            "{} cannot use {} - it is not a trait",
                            class.name, trait_use.name
                        )
                    } else {
                        format!("Trait \"{}\" not found", trait_use.name)
                    };
                defer_class_declaration_fatal(
                    class,
                    Diagnostic::uncaught_fatal("Error", message, Some(trait_use.span), None),
                );
                trait_resolution_failed = true;
                continue;
            };
            used_trait_pairs.push((trait_use, trait_decl));
        }
        if trait_resolution_failed {
            class.trait_uses.clear();
            continue;
        }
        let resolved_trait_uses = used_trait_pairs
            .iter()
            .map(|(trait_use, _)| (*trait_use).clone())
            .collect::<Vec<_>>();
        let used_traits = used_trait_pairs
            .iter()
            .map(|(_, trait_decl)| *trait_decl)
            .collect::<Vec<_>>();
        if !resolved_trait_uses.is_empty() {
            if let Err(diagnostic) = validate_trait_use_adaptations(
                &class.name,
                &resolved_trait_uses,
                traits,
                &used_traits,
                Some(&non_trait_names),
            ) {
                defer_class_declaration_fatal(class, diagnostic);
                class.trait_uses.clear();
                continue;
            }
        }
        for (trait_use, trait_decl) in used_trait_pairs {
            if let Err(diagnostic) = import_trait_members_into_class(
                class,
                trait_decl,
                trait_use,
                &own_method_names,
                &parent_concrete_method_names,
                &mut imported_method_names,
                &mut property_origins,
                &mut static_property_origins,
                &mut constant_origins,
                global_constant_values,
            ) {
                defer_class_declaration_fatal(class, diagnostic);
                class.trait_uses.clear();
                break;
            }
        }
    }
    Ok(())
}

fn internal_trait_available_for_runtime_use(name: &str) -> bool {
    name.eq_ignore_ascii_case("_ZendTestTrait")
}

fn defer_class_declaration_fatal(class: &mut ClassDecl, diagnostic: Diagnostic) {
    let span = diagnostic.span.unwrap_or(class.span);
    class.declaration_fatals.push(ClassDeclarationFatal {
        message: diagnostic.message,
        span,
    });
}

fn visible_parent_concrete_method_names(
    class: &ClassDecl,
    classes: &[ClassDecl],
) -> HashSet<String> {
    let mut names = HashSet::new();
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let Some(parent) = find_class(classes, name) else {
            break;
        };
        for method in &parent.methods {
            if method.visibility != PropertyVisibility::Private && !method.is_abstract {
                names.insert(method.name.to_ascii_lowercase());
            }
        }
        parent_name = parent.parent_name.as_deref();
    }
    names
}

fn import_trait_members_into_class(
    class: &mut ClassDecl,
    trait_decl: &TraitDecl,
    trait_use: &TraitUseDecl,
    own_method_names: &HashSet<String>,
    parent_concrete_method_names: &HashSet<String>,
    imported_method_names: &mut HashSet<String>,
    property_origins: &mut HashMap<String, String>,
    static_property_origins: &mut HashMap<String, String>,
    constant_origins: &mut HashMap<String, String>,
    global_constant_values: &HashMap<String, ConstExprStaticValue>,
) -> Result<()> {
    for property in &trait_decl.properties {
        if class.is_readonly && !property.is_readonly {
            return Err(Diagnostic::new(
                format!(
                    "Readonly class {} cannot use trait with a non-readonly property {}::${}",
                    class.name, trait_decl.name, property.name
                ),
                Some(class.span),
            ));
        }
        if let Some(existing) = class
            .properties
            .iter()
            .find(|candidate| candidate.name == property.name)
        {
            let existing_owner = property_origins
                .get(&property.name)
                .map(String::as_str)
                .unwrap_or(&class.name);
            validate_composed_property_compatibility(
                existing_owner,
                &trait_decl.name,
                &class.name,
                existing,
                property,
                class.span,
                global_constant_values,
            )?;
        } else if let Some(existing) = class
            .static_properties
            .iter()
            .find(|candidate| candidate.name == property.name)
        {
            let existing_owner = static_property_origins
                .get(&existing.name)
                .map(String::as_str)
                .unwrap_or(&class.name);
            validate_composed_property_kind_compatibility(
                existing_owner,
                &trait_decl.name,
                &class.name,
                &property.name,
                class.span,
            )?;
        } else {
            let mut imported = property.clone();
            imported
                .declaring_class_name
                .get_or_insert_with(|| trait_decl.name.clone());
            imported
                .trait_name
                .get_or_insert_with(|| trait_decl.name.clone());
            substitute_trait_relative_property_type_hint(
                &mut imported.type_hint,
                &trait_decl.name,
                &class.name,
                class.parent_name.as_deref(),
            );
            class.properties.push(imported);
            property_origins.insert(property.name.clone(), trait_decl.name.clone());
        }
    }
    for property in &trait_decl.static_properties {
        if let Some(existing) = class
            .properties
            .iter()
            .find(|candidate| candidate.name == property.name)
        {
            let existing_owner = property_origins
                .get(&existing.name)
                .map(String::as_str)
                .unwrap_or(&class.name);
            validate_composed_property_kind_compatibility(
                existing_owner,
                &trait_decl.name,
                &class.name,
                &property.name,
                class.span,
            )?;
        } else if let Some(existing) = class
            .static_properties
            .iter()
            .find(|candidate| candidate.name == property.name)
        {
            let existing_owner = static_property_origins
                .get(&property.name)
                .map(String::as_str)
                .unwrap_or(&class.name);
            validate_composed_static_property_compatibility(
                existing_owner,
                &trait_decl.name,
                &class.name,
                existing,
                property,
                class.span,
                global_constant_values,
            )?;
        } else {
            let mut imported = property.clone();
            substitute_trait_relative_property_type_hint(
                &mut imported.type_hint,
                &trait_decl.name,
                &class.name,
                class.parent_name.as_deref(),
            );
            class.static_properties.push(imported);
            static_property_origins.insert(property.name.clone(), trait_decl.name.clone());
        }
    }
    for constant in &trait_decl.constants {
        if let Some(existing) = class
            .constants
            .iter()
            .find(|candidate| candidate.name.eq_ignore_ascii_case(&constant.name))
        {
            if class.is_enum && existing.is_enum_case {
                return Err(Diagnostic::new(
                    format!(
                        "Cannot use trait {}, because {}::{} conflicts with enum case {}::{}",
                        trait_decl.name, trait_decl.name, constant.name, class.name, existing.name
                    ),
                    Some(class.span),
                ));
            }
            let constant_key = constant.name.to_ascii_lowercase();
            let existing_owner = constant_origins
                .get(&constant_key)
                .map(String::as_str)
                .unwrap_or(&class.name);
            validate_composed_constant_compatibility(
                existing_owner,
                &trait_decl.name,
                &class.name,
                existing,
                constant,
                class.span,
                global_constant_values,
            )?;
        } else {
            class.constants.push(constant.clone());
            constant_origins.insert(constant.name.to_ascii_lowercase(), trait_decl.name.clone());
        }
    }
    for method in &trait_decl.methods {
        import_trait_method_into_class(
            class,
            trait_decl,
            trait_use,
            method,
            own_method_names,
            parent_concrete_method_names,
            imported_method_names,
        )?;
    }
    Ok(())
}

fn import_trait_method_into_method_list(
    methods: &mut Vec<MethodDecl>,
    trait_decl: &TraitDecl,
    trait_use: &TraitUseDecl,
    method: &MethodDecl,
) -> Result<()> {
    let own_method_names = methods
        .iter()
        .map(|candidate| candidate.name.to_ascii_lowercase())
        .collect::<HashSet<_>>();
    let mut imported_method_names = own_method_names.clone();
    let mut pseudo_class = ClassDecl {
        name: trait_decl.name.clone(),
        source_file: None,
        parent_name: None,
        interfaces: Vec::new(),
        trait_uses: Vec::new(),
        declaration_fatals: Vec::new(),
        attributes: AttributeMetadata::default(),
        doc_comment: None,
        is_conditionally_declared: false,
        is_syntactically_conditionally_declared: false,
        is_anonymous: false,
        is_abstract: false,
        is_final: false,
        is_interface: false,
        is_readonly: false,
        is_enum: false,
        enum_backing_type: None,
        properties: Vec::new(),
        static_properties: Vec::new(),
        constants: Vec::new(),
        methods: methods.clone(),
        span: method.span,
    };
    import_trait_method_into_class(
        &mut pseudo_class,
        trait_decl,
        trait_use,
        method,
        &own_method_names,
        &HashSet::new(),
        &mut imported_method_names,
    )?;
    *methods = pseudo_class.methods;
    Ok(())
}

fn import_trait_method_into_class(
    class: &mut ClassDecl,
    trait_decl: &TraitDecl,
    trait_use: &TraitUseDecl,
    method: &MethodDecl,
    own_method_names: &HashSet<String>,
    parent_concrete_method_names: &HashSet<String>,
    imported_method_names: &mut HashSet<String>,
) -> Result<()> {
    let method_key = method.name.to_ascii_lowercase();
    for alias in matching_trait_aliases(&trait_use.adaptations, &trait_decl.name, &method.name) {
        let Some(alias_name) = alias.alias.as_ref() else {
            continue;
        };
        let alias_key = alias_name.to_ascii_lowercase();
        if own_method_names.contains(&alias_key) || (class.is_enum && alias_key == "cases") {
            continue;
        }
        let mut imported = method_with_trait_origin_for_class(method, trait_decl, class);
        imported.name = alias_name.clone();
        if let Some(visibility) = alias.visibility {
            imported.visibility = visibility;
        }
        if alias.is_final {
            imported.is_final = true;
        }
        if let Err(existing) =
            insert_imported_trait_method(class, imported_method_names, &alias_key, imported)
        {
            return Err(trait_method_collision_diagnostic(
                class, trait_decl, method, alias_name, &existing, alias.span,
            ));
        }
    }

    let original_excluded =
        trait_method_excluded_by_precedence(&trait_use.adaptations, &trait_decl.name, &method.name);
    if !original_excluded
        && !own_method_names.contains(&method_key)
        && !(method.is_abstract && parent_concrete_method_names.contains(&method_key))
        && !(class.is_enum && method_key == "cases")
    {
        let imported = adapted_original_trait_method_for_class(
            method,
            trait_decl,
            class,
            &trait_use.adaptations,
        );
        if let Err(existing) =
            insert_imported_trait_method(class, imported_method_names, &method_key, imported)
        {
            return Err(trait_method_collision_diagnostic(
                class,
                trait_decl,
                method,
                &method.name,
                &existing,
                class.span,
            ));
        }
    }
    Ok(())
}

fn insert_imported_trait_method(
    class: &mut ClassDecl,
    imported_method_names: &mut HashSet<String>,
    method_key: &str,
    imported: MethodDecl,
) -> std::result::Result<(), MethodDecl> {
    if imported_method_names.insert(method_key.to_string()) {
        class.methods.push(imported);
        return Ok(());
    }
    let Some(existing) = class
        .methods
        .iter_mut()
        .find(|candidate| candidate.name.eq_ignore_ascii_case(&imported.name))
    else {
        return Err(imported);
    };
    if existing.trait_name == imported.trait_name
        && existing.trait_method_name == imported.trait_method_name
    {
        return Ok(());
    }
    match (existing.is_abstract, imported.is_abstract) {
        (true, false) => {
            *existing = imported;
            Ok(())
        }
        (false, true) | (true, true) => Ok(()),
        _ => Err(existing.clone()),
    }
}

fn trait_method_collision_diagnostic(
    class: &ClassDecl,
    trait_decl: &TraitDecl,
    method: &MethodDecl,
    applied_name: &str,
    existing: &MethodDecl,
    span: SourceSpan,
) -> Diagnostic {
    let existing_trait = existing.trait_name.as_deref().unwrap_or(&class.name);
    Diagnostic::new(
        format!(
            "Trait method {}::{} has not been applied as {}::{}, because of collision with {}::{}",
            trait_decl.name, method.name, class.name, applied_name, existing_trait, existing.name
        ),
        Some(span),
    )
}

fn validate_composed_property_compatibility(
    existing_owner: &str,
    imported_owner: &str,
    composer_name: &str,
    existing: &PropertyDecl,
    imported: &PropertyDecl,
    span: SourceSpan,
    global_constant_values: &HashMap<String, ConstExprStaticValue>,
) -> Result<()> {
    if existing.has_hooks || imported.has_hooks {
        return Err(Diagnostic::new(
            format!(
                "{existing_owner} and {imported_owner} define the same hooked property (${}) in the composition of {composer_name}. Conflict resolution between hooked properties is currently not supported. Class was composed",
                existing.name
            ),
            Some(span),
        ));
    }
    if existing.visibility == imported.visibility
        && existing.set_visibility == imported.set_visibility
        && existing.is_final == imported.is_final
        && existing.is_abstract == imported.is_abstract
        && existing.is_readonly == imported.is_readonly
        && existing.type_hint == imported.type_hint
        && composed_property_defaults_compatible(
            &existing.value,
            &imported.value,
            global_constant_values,
        )
    {
        return Ok(());
    }
    Err(Diagnostic::new(
        format!(
            "{existing_owner} and {imported_owner} define the same property (${}) in the composition of {composer_name}. However, the definition differs and is considered incompatible. Class was composed",
            existing.name
        ),
        Some(span),
    ))
}

fn validate_composed_property_kind_compatibility(
    existing_owner: &str,
    imported_owner: &str,
    composer_name: &str,
    property_name: &str,
    span: SourceSpan,
) -> Result<()> {
    Err(Diagnostic::new(
        format!(
            "{existing_owner} and {imported_owner} define the same property (${property_name}) in the composition of {composer_name}. However, the definition differs and is considered incompatible. Class was composed",
        ),
        Some(span),
    ))
}

fn validate_composed_static_property_compatibility(
    existing_owner: &str,
    imported_owner: &str,
    composer_name: &str,
    existing: &StaticPropertyDecl,
    imported: &StaticPropertyDecl,
    span: SourceSpan,
    global_constant_values: &HashMap<String, ConstExprStaticValue>,
) -> Result<()> {
    if existing.visibility == imported.visibility
        && existing.set_visibility == imported.set_visibility
        && existing.is_final == imported.is_final
        && existing.type_hint == imported.type_hint
        && composed_property_defaults_compatible(
            &existing.value,
            &imported.value,
            global_constant_values,
        )
    {
        return Ok(());
    }
    Err(Diagnostic::new(
        format!(
            "{existing_owner} and {imported_owner} define the same property (${}) in the composition of {composer_name}. However, the definition differs and is considered incompatible. Class was composed",
            existing.name
        ),
        Some(span),
    ))
}

fn validate_composed_constant_compatibility(
    existing_owner: &str,
    imported_owner: &str,
    composer_name: &str,
    existing: &ClassConstantDecl,
    imported: &ClassConstantDecl,
    span: SourceSpan,
    global_constant_values: &HashMap<String, ConstExprStaticValue>,
) -> Result<()> {
    if existing.visibility == imported.visibility
        && existing.is_final == imported.is_final
        && existing.type_hint == imported.type_hint
        && !const_expr_values_provably_different(
            &existing.value,
            &imported.value,
            global_constant_values,
        )
    {
        return Ok(());
    }
    Err(Diagnostic::new(
        format!(
            "{existing_owner} and {imported_owner} define the same constant ({}) in the composition of {composer_name}. However, the definition differs and is considered incompatible. Class was composed",
            existing.name
        ),
        Some(span),
    ))
}

#[derive(Debug, Clone, PartialEq)]
enum ConstExprStaticValue {
    String(String),
    Int(i64),
    Float(u64),
    Bool(bool),
    Null,
    Array(Vec<(Option<ConstExprStaticValue>, ConstExprStaticValue)>),
}

fn collect_global_const_expr_static_values(
    statements: &[Statement],
) -> HashMap<String, ConstExprStaticValue> {
    let mut values = HashMap::new();
    collect_global_const_expr_static_values_in(statements, &mut values);
    values
}

fn collect_global_const_expr_static_values_in(
    statements: &[Statement],
    values: &mut HashMap<String, ConstExprStaticValue>,
) {
    for statement in statements {
        match statement {
            Statement::Const { declarations, .. } => {
                for declaration in declarations {
                    if let Some(value) = const_expr_static_value(&declaration.value, values) {
                        values.insert(declaration.name.to_ascii_lowercase(), value);
                    }
                }
            }
            Statement::Block { statements, .. } => {
                collect_global_const_expr_static_values_in(statements, values);
            }
            _ => {}
        }
    }
}

fn composed_property_defaults_compatible(
    existing: &Option<Expr>,
    imported: &Option<Expr>,
    global_constant_values: &HashMap<String, ConstExprStaticValue>,
) -> bool {
    match (existing, imported) {
        (None, None) => true,
        (Some(existing), Some(imported)) => {
            !const_expr_values_provably_different(existing, imported, global_constant_values)
        }
        _ => false,
    }
}

fn const_expr_values_provably_different(
    left: &Expr,
    right: &Expr,
    global_constant_values: &HashMap<String, ConstExprStaticValue>,
) -> bool {
    match (
        const_expr_static_value(left, global_constant_values),
        const_expr_static_value(right, global_constant_values),
    ) {
        (Some(left), Some(right)) => left != right,
        _ => false,
    }
}

fn const_expr_static_value(
    expr: &Expr,
    global_constant_values: &HashMap<String, ConstExprStaticValue>,
) -> Option<ConstExprStaticValue> {
    match ungroup_const_expr(expr) {
        Expr::String(value, _) => Some(ConstExprStaticValue::String(value.clone())),
        Expr::Int(value, _) => Some(ConstExprStaticValue::Int(*value)),
        Expr::Float(value, _) => Some(ConstExprStaticValue::Float(value.to_bits())),
        Expr::Bool(value, _) => Some(ConstExprStaticValue::Bool(*value)),
        Expr::Null(_) => Some(ConstExprStaticValue::Null),
        Expr::Constant(name, _) => global_constant_values
            .get(&name.to_ascii_lowercase())
            .cloned(),
        Expr::Unary {
            op: UnaryOp::Positive,
            expr,
            ..
        } => const_expr_static_value(expr, global_constant_values),
        Expr::Unary {
            op: UnaryOp::Negate,
            expr,
            ..
        } => match const_expr_static_value(expr, global_constant_values)? {
            ConstExprStaticValue::Int(value) => value.checked_neg().map(ConstExprStaticValue::Int),
            ConstExprStaticValue::Float(value) => Some(ConstExprStaticValue::Float(
                (-f64::from_bits(value)).to_bits(),
            )),
            _ => None,
        },
        Expr::Binary {
            op: BinaryOp::Concat,
            left,
            right,
            ..
        } => match (
            const_expr_static_value(left, global_constant_values)?,
            const_expr_static_value(right, global_constant_values)?,
        ) {
            (ConstExprStaticValue::String(left), ConstExprStaticValue::String(right)) => {
                Some(ConstExprStaticValue::String(format!("{left}{right}")))
            }
            _ => None,
        },
        Expr::Binary {
            op, left, right, ..
        } => {
            let left = const_expr_static_int_value(left, global_constant_values)?;
            let right = const_expr_static_int_value(right, global_constant_values)?;
            const_expr_eval_int_binary(*op, left, right).map(ConstExprStaticValue::Int)
        }
        Expr::Array { elements, .. } => {
            let mut values = Vec::with_capacity(elements.len());
            for element in elements {
                let key = match &element.key {
                    Some(key) => Some(const_expr_static_value(key, global_constant_values)?),
                    None => None,
                };
                let value = match &element.value {
                    ArrayElementValue::Value(value) => {
                        const_expr_static_value(value, global_constant_values)?
                    }
                    _ => return None,
                };
                values.push((key, value));
            }
            Some(ConstExprStaticValue::Array(values))
        }
        _ => None,
    }
}

fn const_expr_static_int_value(
    expr: &Expr,
    global_constant_values: &HashMap<String, ConstExprStaticValue>,
) -> Option<i64> {
    match const_expr_static_value(expr, global_constant_values)? {
        ConstExprStaticValue::Int(value) => Some(value),
        _ => None,
    }
}

fn const_expr_eval_int_binary(op: BinaryOp, left: i64, right: i64) -> Option<i64> {
    match op {
        BinaryOp::Add => left.checked_add(right),
        BinaryOp::Subtract => left.checked_sub(right),
        BinaryOp::Multiply => left.checked_mul(right),
        BinaryOp::Modulo if right != 0 => left.checked_rem(right),
        BinaryOp::ShiftLeft if (0..63).contains(&right) => left.checked_shl(right as u32),
        BinaryOp::ShiftRight if (0..63).contains(&right) => left.checked_shr(right as u32),
        BinaryOp::BitwiseAnd => Some(left & right),
        BinaryOp::BitwiseOr => Some(left | right),
        BinaryOp::BitwiseXor => Some(left ^ right),
        _ => None,
    }
}

fn ungroup_const_expr(mut expr: &Expr) -> &Expr {
    while let Expr::Grouped { expr: inner, .. } = expr {
        expr = inner;
    }
    expr
}

fn adapted_original_trait_method_for_class(
    method: &MethodDecl,
    trait_decl: &TraitDecl,
    class: &ClassDecl,
    adaptations: &[TraitAdaptation],
) -> MethodDecl {
    let mut imported = method_with_trait_origin_for_class(method, trait_decl, class);
    for alias in matching_trait_aliases(adaptations, &trait_decl.name, &method.name) {
        if alias.alias.is_none() {
            if let Some(visibility) = alias.visibility {
                imported.visibility = visibility;
            }
            if alias.is_final {
                imported.is_final = true;
            }
        }
    }
    imported
}

fn matching_trait_aliases<'a>(
    adaptations: &'a [TraitAdaptation],
    trait_name: &str,
    method_name: &str,
) -> Vec<&'a TraitAliasAdaptation> {
    adaptations
        .iter()
        .filter_map(|adaptation| match adaptation {
            TraitAdaptation::Alias(alias)
                if trait_method_reference_matches(&alias.method, trait_name, method_name) =>
            {
                Some(alias)
            }
            _ => None,
        })
        .collect()
}

fn trait_method_excluded_by_precedence(
    adaptations: &[TraitAdaptation],
    trait_name: &str,
    method_name: &str,
) -> bool {
    adaptations.iter().any(|adaptation| {
        let TraitAdaptation::Precedence(precedence) = adaptation else {
            return false;
        };
        precedence
            .method
            .method_name
            .eq_ignore_ascii_case(method_name)
            && precedence
                .instead_of
                .iter()
                .any(|excluded| excluded.eq_ignore_ascii_case(trait_name))
    })
}

fn trait_method_reference_matches(
    reference: &TraitMethodReference,
    trait_name: &str,
    method_name: &str,
) -> bool {
    reference.method_name.eq_ignore_ascii_case(method_name)
        && reference
            .trait_name
            .as_deref()
            .is_none_or(|reference_trait| reference_trait.eq_ignore_ascii_case(trait_name))
}

fn method_with_trait_origin(method: &MethodDecl, trait_decl: &TraitDecl) -> MethodDecl {
    let mut imported = method.clone();
    if imported.trait_name.is_none() {
        imported.trait_name = Some(trait_decl.name.clone());
    }
    if imported.trait_method_name.is_none() {
        imported.trait_method_name = Some(method.name.clone());
    }
    imported
}

fn method_with_trait_origin_for_class(
    method: &MethodDecl,
    trait_decl: &TraitDecl,
    class: &ClassDecl,
) -> MethodDecl {
    let mut imported = method_with_trait_origin(method, trait_decl);
    substitute_trait_relative_method_type_hints(
        &mut imported,
        &trait_decl.name,
        &class.name,
        class.parent_name.as_deref(),
    );
    imported
}

fn substitute_trait_relative_method_type_hints(
    method: &mut MethodDecl,
    trait_name: &str,
    class_name: &str,
    parent_name: Option<&str>,
) {
    for parameter in &mut method.parameters {
        if let Some(type_hint) = &mut parameter.type_hint {
            substitute_trait_relative_type_hint(type_hint, trait_name, class_name, parent_name);
        }
    }
    if let Some(return_type) = &mut method.return_type {
        substitute_trait_relative_type_hint(return_type, trait_name, class_name, parent_name);
    }
}

fn validate_class_names(
    classes: &[ClassDecl],
    traits: &[TraitDecl],
    compile_warnings: &mut Vec<CompileWarning>,
) -> Result<()> {
    #[derive(Clone, Copy)]
    enum ClassLikeKind {
        Class,
        Interface,
        Trait,
        Enum,
    }
    impl ClassLikeKind {
        fn as_php_label(self) -> &'static str {
            match self {
                ClassLikeKind::Class => "class",
                ClassLikeKind::Interface => "interface",
                ClassLikeKind::Trait => "trait",
                ClassLikeKind::Enum => "enum",
            }
        }
    }
    struct ClassLikeSymbol<'a> {
        kind: ClassLikeKind,
        name: &'a str,
        span: SourceSpan,
        unconditionally_declared: bool,
    }
    let mut names: HashMap<String, ClassLikeSymbol<'_>> = HashMap::new();
    for class in classes {
        let lookup_name = class.name.to_ascii_lowercase();
        if lookup_name == "stdclass" {
            return Err(Diagnostic::new(
                "Cannot redeclare class stdClass",
                Some(class.span),
            ));
        }
        if declaration_name_segment(&lookup_name) == "_" {
            let subject = if class.is_interface {
                "an interface"
            } else if class.is_enum {
                "an enum"
            } else {
                "a class"
            };
            compile_warnings.push(CompileWarning {
                message: format!("Using \"_\" as {subject} name is deprecated since 8.4"),
                span: class.span,
                kind: CompileWarningKind::Deprecation,
            });
        }
        let unconditionally_declared = !class.is_conditionally_declared;
        if unconditionally_declared {
            if let Some(previous) = names.get(&lookup_name) {
                if previous.unconditionally_declared {
                    return Err(Diagnostic::new(
                        format!(
                            "Cannot redeclare {} {} (previously declared in Unknown:{})",
                            previous.kind.as_php_label(),
                            previous.name,
                            previous.span.line
                        ),
                        Some(class.span),
                    ));
                }
            }
        }
        names
            .entry(lookup_name)
            .and_modify(|previous| {
                if unconditionally_declared && !previous.unconditionally_declared {
                    *previous = ClassLikeSymbol {
                        kind: if class.is_enum {
                            ClassLikeKind::Enum
                        } else if class.is_interface {
                            ClassLikeKind::Interface
                        } else {
                            ClassLikeKind::Class
                        },
                        name: &class.name,
                        span: class.span,
                        unconditionally_declared,
                    };
                }
            })
            .or_insert(ClassLikeSymbol {
                kind: if class.is_enum {
                    ClassLikeKind::Enum
                } else if class.is_interface {
                    ClassLikeKind::Interface
                } else {
                    ClassLikeKind::Class
                },
                name: &class.name,
                span: class.span,
                unconditionally_declared,
            });
    }
    for trait_decl in traits {
        let lookup_name = trait_decl.name.to_ascii_lowercase();
        if let Some(previous) = names.get(&lookup_name) {
            if previous.unconditionally_declared {
                return Err(Diagnostic::new(
                    format!(
                        "Cannot redeclare {} {} (previously declared in Unknown:{})",
                        previous.kind.as_php_label(),
                        previous.name,
                        previous.span.line
                    ),
                    Some(trait_decl.span),
                ));
            }
        }
        names.insert(
            lookup_name,
            ClassLikeSymbol {
                kind: ClassLikeKind::Trait,
                name: &trait_decl.name,
                span: trait_decl.span,
                unconditionally_declared: true,
            },
        );
    }
    Ok(())
}

fn declaration_name_segment(name: &str) -> &str {
    name.rsplit('\\').next().unwrap_or(name)
}

fn reserved_class_name_segment(name: &str) -> Option<&str> {
    let segment = declaration_name_segment(name);
    matches!(
        segment,
        "array"
            | "bool"
            | "callable"
            | "false"
            | "float"
            | "int"
            | "iterable"
            | "mixed"
            | "never"
            | "null"
            | "object"
            | "parent"
            | "self"
            | "static"
            | "string"
            | "true"
            | "void"
    )
    .then_some(segment)
}

fn reject_reserved_parent_class_name(name: &str, span: SourceSpan) -> Result<()> {
    let lowered = name.to_ascii_lowercase();
    let Some(reserved_name) = reserved_class_name_segment(&lowered) else {
        return Ok(());
    };
    Err(Diagnostic::new(
        format!("Cannot use \"{reserved_name}\" as class name, as it is reserved"),
        Some(span),
    ))
}

fn reject_reserved_interface_name(name: &str, span: SourceSpan) -> Result<()> {
    let lowered = name.to_ascii_lowercase();
    let Some(reserved_name) = reserved_class_name_segment(&lowered) else {
        return Ok(());
    };
    Err(Diagnostic::new(
        format!("Cannot use \"{reserved_name}\" as interface name, as it is reserved"),
        Some(span),
    ))
}

fn reject_static_declaration_name(name: &str, span: SourceSpan) -> Result<()> {
    if declaration_name_segment(name) != "static" {
        return Ok(());
    }
    Err(Diagnostic::parse_error(
        "syntax error, unexpected token \"static\", expecting T_STRING",
        Some(span),
    ))
}

fn validate_trait_names(
    traits: &[TraitDecl],
    compile_warnings: &mut Vec<CompileWarning>,
) -> Result<()> {
    let mut names: HashMap<String, &TraitDecl> = HashMap::new();
    for trait_decl in traits {
        let lookup_name = trait_decl.name.to_ascii_lowercase();
        if declaration_name_segment(&lookup_name) == "_" {
            compile_warnings.push(CompileWarning {
                message: "Using \"_\" as a trait name is deprecated since 8.4".to_string(),
                span: trait_decl.span,
                kind: CompileWarningKind::Deprecation,
            });
        }
        if let Some(previous) = names.get(&lookup_name) {
            return Err(Diagnostic::new(
                format!(
                    "Cannot redeclare trait {} (previously declared in Unknown:{})",
                    previous.name, previous.span.line
                ),
                Some(trait_decl.span),
            ));
        }
        names.insert(lookup_name, trait_decl);
    }
    Ok(())
}

fn validate_parent_class_names(classes: &mut [ClassDecl], traits: &[TraitDecl]) -> Result<()> {
    let names = classes
        .iter()
        .filter(|class| !class.is_interface)
        .map(|class| class.name.to_ascii_lowercase())
        .collect::<HashSet<_>>();
    let trait_names = traits
        .iter()
        .map(|trait_decl| trait_decl.name.to_ascii_lowercase())
        .collect::<HashSet<_>>();
    for class in classes.iter_mut() {
        if class.is_interface {
            continue;
        }
        let Some(parent_name) = class.parent_name.clone() else {
            continue;
        };
        if parent_name.eq_ignore_ascii_case("stdClass")
            || is_modeled_spl_iterator_class_name(&parent_name)
            || is_modeled_builtin_date_class_name(&parent_name)
            || is_modeled_builtin_enum_class_name(&parent_name)
            || is_modeled_builtin_exception_class_name(&parent_name)
            || is_modeled_builtin_reflection_class_name(&parent_name)
            || is_modeled_archive_network_class_name(&parent_name)
            || is_modeled_extension_internal_class_name(&parent_name)
            || parent_name
                .trim_start_matches('\\')
                .eq_ignore_ascii_case("PhpToken")
            || parent_name
                .trim_start_matches('\\')
                .eq_ignore_ascii_case("BcMath\\Number")
            || parent_name.eq_ignore_ascii_case("Generator")
        {
            continue;
        }
        if trait_names.contains(&parent_name.to_ascii_lowercase()) {
            class.declaration_fatals.push(ClassDeclarationFatal {
                message: format!("Class {} cannot extend trait {parent_name}", class.name),
                span: class.span,
            });
            continue;
        }
        if !names.contains(&parent_name.to_ascii_lowercase()) {
            class.is_conditionally_declared = true;
        }
    }
    Ok(())
}

fn validate_interface_references(
    classes: &mut [ClassDecl],
    traits: &[TraitDecl],
    compile_warnings: &mut Vec<CompileWarning>,
) -> Result<()> {
    let interface_names = classes
        .iter()
        .filter(|class| class.is_interface)
        .map(|class| class.name.to_ascii_lowercase())
        .collect::<HashSet<_>>();
    let trait_names = traits
        .iter()
        .map(|trait_decl| trait_decl.name.to_ascii_lowercase())
        .collect::<HashSet<_>>();
    for class in classes.iter_mut() {
        let mut seen_interfaces = HashSet::new();
        for interface_name in class.interfaces.clone() {
            if !seen_interfaces.insert(interface_name.to_ascii_lowercase()) {
                let declaration_kind = class_declaration_kind(class);
                return Err(Diagnostic::new(
                    format!(
                        "{declaration_kind} {} cannot implement previously implemented interface {interface_name}",
                        class.name
                    ),
                    Some(class.span),
                ));
            }
            if class.is_enum && interface_name.eq_ignore_ascii_case("Throwable") {
                return Err(Diagnostic::new(
                    format!("Enum {} cannot implement interface Throwable", class.name),
                    Some(class.span),
                ));
            }
            if class.is_interface && class.name.eq_ignore_ascii_case(&interface_name) {
                compile_warnings.push(CompileWarning {
                    message: format!("Interface \"{interface_name}\" not found"),
                    span: class.span,
                    kind: CompileWarningKind::UncaughtError,
                });
                return Ok(());
            }
            if interface_names.contains(&interface_name.to_ascii_lowercase())
                || is_modeled_builtin_interface_name(&interface_name)
            {
                continue;
            }
            if trait_names.contains(&interface_name.to_ascii_lowercase()) {
                class.declaration_fatals.push(ClassDeclarationFatal {
                    message: format!(
                        "{} cannot implement {interface_name} - it is not an interface",
                        class.name
                    ),
                    span: class.span,
                });
                continue;
            }
            class.is_conditionally_declared = true;
        }
    }
    Ok(())
}

fn class_declaration_kind(class: &ClassDecl) -> &'static str {
    if class.is_interface {
        "Interface"
    } else if class.is_enum {
        "Enum"
    } else {
        "Class"
    }
}

fn validate_interface_method_conflicts(classes: &[ClassDecl]) -> Result<()> {
    for interface in classes.iter().filter(|class| class.is_interface) {
        let mut seen_interfaces = HashSet::new();
        let mut inherited_methods = Vec::new();
        for parent_name in &interface.interfaces {
            collect_interface_hierarchy_methods(
                parent_name,
                classes,
                &mut seen_interfaces,
                &mut inherited_methods,
            );
        }
        inherited_methods.extend(interface.methods.iter().map(|method| (interface, method)));
        for (index, (left_interface, left_method)) in inherited_methods.iter().enumerate() {
            for (right_interface, right_method) in inherited_methods.iter().skip(index + 1) {
                if !left_method.name.eq_ignore_ascii_case(&right_method.name)
                    || left_method.is_static == right_method.is_static
                {
                    continue;
                }
                let (non_static_interface, static_interface, static_method) =
                    if left_method.is_static {
                        (*right_interface, *left_interface, *left_method)
                    } else {
                        (*left_interface, *right_interface, *right_method)
                    };
                return Err(Diagnostic::new(
                    format!(
                        "Cannot make non static method {}::{}() static in class {}",
                        non_static_interface.name, static_method.name, static_interface.name
                    ),
                    Some(static_method.span),
                ));
            }
        }
    }
    Ok(())
}

fn collect_interface_hierarchy_methods<'a>(
    interface_name: &str,
    classes: &'a [ClassDecl],
    seen: &mut HashSet<String>,
    methods: &mut Vec<(&'a ClassDecl, &'a MethodDecl)>,
) {
    let lookup_name = interface_name.trim_start_matches('\\').to_ascii_lowercase();
    if !seen.insert(lookup_name) {
        return;
    }
    let Some(interface) = find_class(classes, interface_name) else {
        return;
    };
    if !interface.is_interface {
        return;
    }
    methods.extend(interface.methods.iter().map(|method| (interface, method)));
    for parent_name in &interface.interfaces {
        collect_interface_hierarchy_methods(parent_name, classes, seen, methods);
    }
}

fn class_hierarchy_implements_interface(
    classes: &[ClassDecl],
    class: &ClassDecl,
    interface_name: &str,
) -> bool {
    if class
        .interfaces
        .iter()
        .any(|interface| modeled_builtin_interface_extends(interface, interface_name))
    {
        return true;
    }
    class
        .parent_name
        .as_deref()
        .and_then(|parent_name| {
            classes
                .iter()
                .find(|candidate| candidate.name.eq_ignore_ascii_case(parent_name))
        })
        .is_some_and(|parent| class_hierarchy_implements_interface(classes, parent, interface_name))
}

fn validate_traversable_implementations(classes: &[ClassDecl]) -> Result<()> {
    for class in classes {
        if class.is_interface {
            continue;
        }
        if class_hierarchy_implements_interface(classes, class, "Iterator")
            && class_hierarchy_implements_interface(classes, class, "IteratorAggregate")
        {
            let declaration_kind = class_declaration_kind(class);
            return Err(Diagnostic::new(
                format!(
                    "{declaration_kind} {} cannot implement both Iterator and IteratorAggregate at the same time",
                    class.name
                ),
                Some(class.span),
            ));
        }
        if class.is_abstract {
            continue;
        }
        if class_hierarchy_implements_interface(classes, class, "Traversable")
            && !class_hierarchy_implements_interface(classes, class, "Iterator")
            && !class_hierarchy_implements_interface(classes, class, "IteratorAggregate")
        {
            let declaration_kind = class_declaration_kind(class);
            return Err(Diagnostic::new(
                format!(
                    "{declaration_kind} {} must implement interface Traversable as part of either Iterator or IteratorAggregate",
                    class.name
                ),
                Some(SourceSpan::new(0, 0, 0, 0)),
            ));
        }
    }
    Ok(())
}

fn validate_method_signature_compatibility(
    classes: &[ClassDecl],
    traits: &[TraitDecl],
    runtime_class_aliases: &HashMap<String, String>,
    local_class_count: usize,
    compile_warnings: &mut Vec<CompileWarning>,
) -> Result<()> {
    for (class_index, class) in classes.iter().enumerate() {
        if class.is_conditionally_declared {
            continue;
        }
        let type_validation_classes =
            method_signature_type_validation_classes(classes, class_index, local_class_count);
        let type_classes = type_validation_classes.as_slice();
        for method in &class.methods {
            if method.name.eq_ignore_ascii_case("__construct") {
                if let Some((parent_class, parent_method)) =
                    find_final_private_parent_constructor(class, classes)
                {
                    if parent_method.trait_name.is_some() {
                        continue;
                    }
                    return Err(Diagnostic::new(
                        format!(
                            "Cannot override final method {}::{}()",
                            parent_class.name, parent_method.name
                        ),
                        Some(method.span),
                    ));
                }
                if let Some((parent_class, parent_method)) =
                    find_final_modeled_internal_parent_method(class, &method.name, classes)
                {
                    return Err(Diagnostic::new(
                        format!("Cannot override final method {parent_class}::{parent_method}()"),
                        Some(method.span),
                    ));
                }
            }

            let visible_parent_method = find_visible_parent_method(class, &method.name, classes);
            let has_visible_parent_method = if let Some((parent_class, parent_method)) =
                visible_parent_method
            {
                if parent_method.is_final {
                    return Err(Diagnostic::new(
                        format!(
                            "Cannot override final method {}::{}()",
                            parent_class.name, parent_method.name
                        ),
                        Some(method.span),
                    ));
                }
                if parent_method.is_static != method.is_static {
                    return Err(Diagnostic::new(
                        format!(
                            "Cannot make {} method {}::{}() {} in class {}",
                            if parent_method.is_static {
                                "static"
                            } else {
                                "non static"
                            },
                            parent_class.name,
                            parent_method.name,
                            if method.is_static {
                                "static"
                            } else {
                                "non static"
                            },
                            class.name
                        ),
                        Some(method.span),
                    ));
                }
                let inherited_visibility_requirement =
                    if method_requires_parent_visibility_compatibility(method, parent_method) {
                        Some((parent_class, parent_method))
                    } else {
                        inherited_abstract_constructor_visibility_requirement(
                            method,
                            parent_class,
                            parent_method,
                            classes,
                        )
                    };
                if let Some((visibility_class, visibility_method)) =
                    inherited_visibility_requirement
                {
                    let (required_class, required_method) = method_visibility_requirement_source(
                        visibility_class,
                        visibility_method,
                        classes,
                    );
                    if !method_visibility_compatibility_deferred_to_runtime(method)
                        && visibility_rank(method.visibility)
                            > visibility_rank(required_method.visibility)
                    {
                        let suffix = if required_method.visibility == PropertyVisibility::Public {
                            ""
                        } else {
                            " or weaker"
                        };
                        return Err(Diagnostic::new(
                            format!(
                                "Access level to {}::{}() must be {} (as in class {}){}",
                                class.name,
                                method.name,
                                property_visibility_name(required_method.visibility),
                                required_class.name,
                                suffix
                            ),
                            Some(method.span),
                        ));
                    }
                }
                if method.visibility == PropertyVisibility::Private {
                    continue;
                }
                if !method_signature_compatibility_deferred_to_runtime(class, method) {
                    if method_requires_parent_signature_compatibility(method, parent_method) {
                        validate_method_signature_pair(
                            class,
                            method,
                            parent_class,
                            parent_method,
                            type_classes,
                            runtime_class_aliases,
                        )?;
                    } else if let Some((signature_class, signature_method)) =
                        inherited_abstract_constructor_signature_requirement(
                            method,
                            parent_class,
                            parent_method,
                            classes,
                        )
                    {
                        validate_method_signature_pair(
                            class,
                            method,
                            signature_class,
                            signature_method,
                            type_classes,
                            runtime_class_aliases,
                        )?;
                    }
                }
                true
            } else {
                false
            };

            if method.name.eq_ignore_ascii_case("__construct") {
                if let Some((prototype_class, prototype_method)) =
                    find_abstract_parent_constructor(class, classes)
                {
                    let already_checked =
                        visible_parent_method.is_some_and(|(parent_class, parent_method)| {
                            parent_class
                                .name
                                .eq_ignore_ascii_case(&prototype_class.name)
                                && parent_method.span == prototype_method.span
                        });
                    if !already_checked {
                        validate_method_signature_pair(
                            class,
                            method,
                            prototype_class,
                            prototype_method,
                            type_classes,
                            runtime_class_aliases,
                        )?;
                    }
                }
            }

            let mut trait_methods = Vec::new();
            collect_class_trait_abstract_methods(class, &method.name, traits, &mut trait_methods);
            for (trait_decl, trait_method) in trait_methods {
                if trait_method.is_static != method.is_static {
                    return Err(Diagnostic::new(
                        format!(
                            "Cannot make {} method {}::{}() {} in class {}",
                            if trait_method.is_static {
                                "static"
                            } else {
                                "non static"
                            },
                            trait_decl.name,
                            trait_method.name,
                            if method.is_static {
                                "static"
                            } else {
                                "non static"
                            },
                            class.name
                        ),
                        Some(method.span),
                    ));
                }
                let normalized_trait_method =
                    trait_abstract_method_for_class(&class.name, &trait_decl.name, trait_method);
                validate_method_signature_pair_named(
                    class,
                    method,
                    &trait_decl.name,
                    &normalized_trait_method,
                    type_classes,
                    runtime_class_aliases,
                )?;
            }

            if method.visibility == PropertyVisibility::Private {
                continue;
            }

            if !has_visible_parent_method {
                if let Some(tentative_method) =
                    find_tentative_internal_parent_method(class, &method.name, classes)
                {
                    validate_tentative_internal_return_signature(
                        class,
                        method,
                        &tentative_method,
                        type_classes,
                        runtime_class_aliases,
                        compile_warnings,
                    )?;
                }
            }

            if let Some(tentative_method) =
                find_tentative_internal_interface_method(class, &method.name, classes)
            {
                validate_tentative_internal_return_signature(
                    class,
                    method,
                    &tentative_method,
                    type_classes,
                    runtime_class_aliases,
                    compile_warnings,
                )?;
            }

            let mut interface_methods = Vec::new();
            collect_class_interface_methods(class, &method.name, classes, &mut interface_methods);
            for (interface, interface_method) in interface_methods {
                if visibility_rank(method.visibility) > visibility_rank(interface_method.visibility)
                {
                    return Err(Diagnostic::new(
                        format!(
                            "Access level to {}::{}() must be {} (as in class {})",
                            class.name,
                            method.name,
                            property_visibility_name(interface_method.visibility),
                            interface.name
                        ),
                        Some(method.span),
                    ));
                }
                validate_method_signature_pair(
                    class,
                    method,
                    interface,
                    interface_method,
                    type_classes,
                    runtime_class_aliases,
                )?;
            }
        }

        let mut inherited_trait_methods = Vec::new();
        collect_class_trait_abstract_method_entries(class, traits, &mut inherited_trait_methods);
        for (trait_decl, method) in inherited_trait_methods {
            if class.methods.iter().any(|candidate| {
                !candidate.is_abstract && candidate.name.eq_ignore_ascii_case(&method.name)
            }) {
                continue;
            }
            let Some((parent_class, parent_method)) =
                find_visible_parent_method(class, &method.name, classes)
            else {
                continue;
            };
            if parent_method.is_abstract {
                continue;
            }
            let trait_name = &trait_decl.name;
            let normalized_trait_method =
                trait_abstract_method_for_class(&class.name, trait_name, method);
            validate_method_signature_pair_named(
                parent_class,
                parent_method,
                trait_name,
                &normalized_trait_method,
                type_classes,
                runtime_class_aliases,
            )?;
        }
    }
    Ok(())
}

fn defer_runtime_class_declaration_validations(classes: &mut [ClassDecl]) {
    let validation_classes = classes.to_vec();
    for class in classes.iter_mut() {
        if class_has_runtime_deferred_trait_abstract_method(class, &validation_classes) {
            class.is_conditionally_declared = true;
        }
        defer_trait_imported_final_private_constructor_fatal(class, &validation_classes);
    }
}

fn class_has_runtime_deferred_trait_abstract_method(
    class: &ClassDecl,
    classes: &[ClassDecl],
) -> bool {
    if class.is_abstract || class.is_interface {
        return false;
    }
    class.methods.iter().any(|method| {
        method.is_abstract
            && method.trait_name.is_some()
            && method.visibility != PropertyVisibility::Private
            && method
                .trait_method_name
                .as_deref()
                .is_some_and(|trait_method| method.name.eq_ignore_ascii_case(trait_method))
            && !trait_abstract_method_has_concrete_implementation(class, method, classes)
    })
}

fn defer_trait_imported_final_private_constructor_fatal(
    class: &mut ClassDecl,
    classes: &[ClassDecl],
) {
    let Some(method) = class
        .methods
        .iter()
        .find(|method| method.name.eq_ignore_ascii_case("__construct"))
    else {
        return;
    };
    let Some((parent_class, parent_method)) = find_final_private_parent_constructor(class, classes)
    else {
        return;
    };
    if parent_method.trait_name.is_none() {
        return;
    }
    let message = format!(
        "Cannot override final method {}::{}()",
        parent_class.name, parent_method.name
    );
    if class
        .declaration_fatals
        .iter()
        .any(|fatal| fatal.message == message)
    {
        return;
    }
    class.is_conditionally_declared = true;
    class.declaration_fatals.push(ClassDeclarationFatal {
        message,
        span: method.span,
    });
}

fn method_signature_type_validation_classes(
    classes: &[ClassDecl],
    class_index: usize,
    local_class_count: usize,
) -> Vec<ClassDecl> {
    if class_index >= local_class_count {
        return classes.to_vec();
    }
    classes
        .iter()
        .take(class_index + 1)
        .chain(
            classes
                .iter()
                .take(local_class_count)
                .skip(class_index + 1)
                .filter(|class| class.is_conditionally_declared),
        )
        .chain(classes.iter().skip(local_class_count))
        .cloned()
        .collect()
}

fn collect_final_private_method_warnings(
    classes: &[ClassDecl],
    traits: &[TraitDecl],
    compile_warnings: &mut Vec<CompileWarning>,
) {
    for class in classes {
        for method in &class.methods {
            if method.is_final
                && method.visibility == PropertyVisibility::Private
                && !method.name.eq_ignore_ascii_case("__construct")
            {
                if imported_trait_method_final_private_warning_is_suppressed(method, traits) {
                    continue;
                }
                compile_warnings.push(CompileWarning {
                    message:
                        "Private methods cannot be final as they are never overridden by other classes"
                            .to_string(),
                    span: method.span,
                    kind: CompileWarningKind::Warning,
                });
            }
        }
    }
}

fn imported_trait_method_final_private_warning_is_suppressed(
    method: &MethodDecl,
    traits: &[TraitDecl],
) -> bool {
    let (Some(trait_name), Some(trait_method_name)) = (
        method.trait_name.as_deref(),
        method.trait_method_name.as_deref(),
    ) else {
        return false;
    };
    let Some(trait_decl) = find_trait(traits, trait_name) else {
        return false;
    };
    let Some(source_method) = trait_decl
        .methods
        .iter()
        .find(|candidate| candidate.name.eq_ignore_ascii_case(trait_method_name))
    else {
        return false;
    };
    source_method.visibility != PropertyVisibility::Private
}

fn collect_parameter_default_compile_warnings(
    classes: &[ClassDecl],
    traits: &[TraitDecl],
    functions: &[FunctionDecl],
    compile_warnings: &mut Vec<CompileWarning>,
) {
    for function in functions {
        if function.is_conditionally_declared {
            continue;
        }
        collect_parameter_default_compile_warnings_for_signature(
            &function.name,
            &function.parameters,
            function.span,
            compile_warnings,
        );
    }
    for class in classes {
        if class.is_conditionally_declared || class.is_anonymous {
            continue;
        }
        for method in &class.methods {
            if method
                .trait_name
                .as_deref()
                .is_some_and(|trait_name| !trait_name.eq_ignore_ascii_case(&class.name))
            {
                continue;
            }
            collect_parameter_default_compile_warnings_for_signature(
                &format!("{}::{}", class.name, method.name),
                &method.parameters,
                method.span,
                compile_warnings,
            );
        }
    }
    for trait_decl in traits {
        for method in &trait_decl.methods {
            collect_parameter_default_compile_warnings_for_signature(
                &format!("{}::{}", trait_decl.name, method.name),
                &method.parameters,
                method.span,
                compile_warnings,
            );
        }
    }
}

fn collect_parameter_default_compile_warnings_for_signature(
    function_name: &str,
    parameters: &[FunctionParameter],
    span: SourceSpan,
    compile_warnings: &mut Vec<CompileWarning>,
) {
    for parameter in parameters {
        if parameter_default_emits_implicit_nullable_compile_warning(parameter) {
            compile_warnings.push(CompileWarning {
                message: format!(
                    "{function_name}(): Implicitly marking parameter ${} as nullable is deprecated, the explicit nullable type must be used instead",
                    parameter.name
                ),
                span,
                kind: CompileWarningKind::Deprecation,
            });
        }
    }
    let Some((required_index, required_parameter)) = parameters
        .iter()
        .enumerate()
        .rfind(|(_, parameter)| !parameter.is_variadic && parameter.default_value.is_none())
    else {
        return;
    };
    for optional_parameter in parameters.iter().take(required_index) {
        if optional_parameter.default_value.is_none()
            || parameter_default_emits_implicit_nullable_compile_warning(optional_parameter)
        {
            continue;
        }
        compile_warnings.push(CompileWarning {
            message: format!(
                "{function_name}(): Optional parameter ${} declared before required parameter ${} is implicitly treated as a required parameter",
                optional_parameter.name, required_parameter.name
            ),
            span,
            kind: CompileWarningKind::Deprecation,
        });
    }
}

fn parameter_default_emits_implicit_nullable_compile_warning(
    parameter: &FunctionParameter,
) -> bool {
    let Some(type_hint) = parameter.type_hint.as_ref() else {
        return false;
    };
    parameter_default_value_is_null_expr(parameter)
        && !type_hint_accepts_null_default(type_hint)
        && type_hint_allows_implicit_nullable_default(type_hint)
}

fn trait_abstract_method_for_class(
    class_name: &str,
    trait_name: &str,
    method: &MethodDecl,
) -> MethodDecl {
    let mut normalized = method.clone();
    for parameter in &mut normalized.parameters {
        if let Some(type_hint) = &mut parameter.type_hint {
            substitute_trait_self_type_hint(type_hint, trait_name, class_name);
        }
    }
    if let Some(return_type) = &mut normalized.return_type {
        substitute_trait_self_type_hint(return_type, trait_name, class_name);
    }
    normalized
}

fn substitute_trait_self_type_hint(type_hint: &mut TypeHint, trait_name: &str, class_name: &str) {
    match type_hint {
        TypeHint::Class(name)
            if name.eq_ignore_ascii_case(trait_name) || name.eq_ignore_ascii_case("self") =>
        {
            *name = class_name.to_string();
        }
        TypeHint::Nullable(inner) => substitute_trait_self_type_hint(inner, trait_name, class_name),
        TypeHint::Union(types) | TypeHint::Intersection(types) => {
            for member in types {
                substitute_trait_self_type_hint(member, trait_name, class_name);
            }
        }
        TypeHint::Null
        | TypeHint::Array
        | TypeHint::Callable
        | TypeHint::Int
        | TypeHint::Float
        | TypeHint::String
        | TypeHint::Bool
        | TypeHint::True
        | TypeHint::False
        | TypeHint::Object
        | TypeHint::Iterable
        | TypeHint::Mixed
        | TypeHint::Void
        | TypeHint::Never
        | TypeHint::Static
        | TypeHint::Class(_) => {}
    }
}

fn substitute_trait_relative_property_type_hint(
    type_hint: &mut Option<PropertyTypeHint>,
    trait_name: &str,
    class_name: &str,
    parent_name: Option<&str>,
) {
    let Some(type_hint) = type_hint else {
        return;
    };
    substitute_trait_relative_property_type_kind(
        &mut type_hint.kind,
        trait_name,
        class_name,
        parent_name,
    );
    if let Some(semantic_type) = &mut type_hint.semantic_type {
        substitute_trait_relative_type_hint(semantic_type, trait_name, class_name, parent_name);
    }
}

fn substitute_trait_relative_property_type_kind(
    kind: &mut PropertyTypeKind,
    trait_name: &str,
    class_name: &str,
    parent_name: Option<&str>,
) {
    let PropertyTypeKind::Class(name) = kind else {
        return;
    };
    if name.eq_ignore_ascii_case(trait_name) || name.eq_ignore_ascii_case("self") {
        *name = class_name.to_string();
    } else if name.eq_ignore_ascii_case("parent") {
        if let Some(parent_name) = parent_name {
            *name = parent_name.to_string();
        }
    }
}

fn substitute_trait_relative_type_hint(
    type_hint: &mut TypeHint,
    trait_name: &str,
    class_name: &str,
    parent_name: Option<&str>,
) {
    match type_hint {
        TypeHint::Class(name)
            if name.eq_ignore_ascii_case(trait_name) || name.eq_ignore_ascii_case("self") =>
        {
            *name = class_name.to_string();
        }
        TypeHint::Class(name) if name.eq_ignore_ascii_case("parent") => {
            if let Some(parent_name) = parent_name {
                *name = parent_name.to_string();
            }
        }
        TypeHint::Nullable(inner) => {
            substitute_trait_relative_type_hint(inner, trait_name, class_name, parent_name)
        }
        TypeHint::Union(types) | TypeHint::Intersection(types) => {
            for member in types {
                substitute_trait_relative_type_hint(member, trait_name, class_name, parent_name);
            }
        }
        TypeHint::Null
        | TypeHint::Array
        | TypeHint::Callable
        | TypeHint::Int
        | TypeHint::Float
        | TypeHint::String
        | TypeHint::Bool
        | TypeHint::True
        | TypeHint::False
        | TypeHint::Object
        | TypeHint::Iterable
        | TypeHint::Mixed
        | TypeHint::Void
        | TypeHint::Never
        | TypeHint::Static
        | TypeHint::Class(_) => {}
    }
}

fn collect_class_interface_methods<'a>(
    class: &'a ClassDecl,
    method_name: &str,
    classes: &'a [ClassDecl],
    methods: &mut Vec<(&'a ClassDecl, &'a MethodDecl)>,
) {
    fn collect_class<'a>(
        class: &'a ClassDecl,
        method_name: &str,
        classes: &'a [ClassDecl],
        seen_classes: &mut HashSet<String>,
        seen_interfaces: &mut HashSet<String>,
        methods: &mut Vec<(&'a ClassDecl, &'a MethodDecl)>,
    ) {
        if !seen_classes.insert(class.name.to_ascii_lowercase()) {
            return;
        }
        for interface_name in &class.interfaces {
            collect_interface_methods(
                interface_name,
                method_name,
                classes,
                seen_interfaces,
                methods,
            );
        }
        if let Some(parent_name) = &class.parent_name {
            if let Some(parent) = find_class(classes, parent_name) {
                collect_class(
                    parent,
                    method_name,
                    classes,
                    seen_classes,
                    seen_interfaces,
                    methods,
                );
            }
        }
    }

    let mut seen_classes = HashSet::new();
    let mut seen_interfaces = HashSet::new();
    collect_class(
        class,
        method_name,
        classes,
        &mut seen_classes,
        &mut seen_interfaces,
        methods,
    );
}

fn collect_class_trait_abstract_methods<'a>(
    class: &'a ClassDecl,
    method_name: &str,
    traits: &'a [TraitDecl],
    methods: &mut Vec<(&'a TraitDecl, &'a MethodDecl)>,
) {
    let mut seen_traits = HashSet::new();
    for trait_use in &class.trait_uses {
        collect_trait_abstract_methods(
            &trait_use.name,
            method_name,
            traits,
            &mut seen_traits,
            methods,
        );
    }
}

fn collect_class_trait_abstract_method_entries<'a>(
    class: &'a ClassDecl,
    traits: &'a [TraitDecl],
    methods: &mut Vec<(&'a TraitDecl, &'a MethodDecl)>,
) {
    let mut seen_traits = HashSet::new();
    for trait_use in &class.trait_uses {
        collect_trait_abstract_method_entries(&trait_use.name, traits, &mut seen_traits, methods);
    }
}

fn collect_trait_abstract_method_entries<'a>(
    trait_name: &str,
    traits: &'a [TraitDecl],
    seen_traits: &mut HashSet<String>,
    methods: &mut Vec<(&'a TraitDecl, &'a MethodDecl)>,
) {
    let lookup_name = trait_name.trim_start_matches('\\').to_ascii_lowercase();
    if !seen_traits.insert(lookup_name) {
        return;
    }
    let Some(trait_decl) = find_trait(traits, trait_name) else {
        return;
    };
    for method in &trait_decl.methods {
        if method.is_abstract {
            methods.push((trait_decl, method));
        }
    }
    for nested_use in &trait_decl.trait_uses {
        collect_trait_abstract_method_entries(&nested_use.name, traits, seen_traits, methods);
    }
}

fn collect_trait_abstract_methods<'a>(
    trait_name: &str,
    method_name: &str,
    traits: &'a [TraitDecl],
    seen_traits: &mut HashSet<String>,
    methods: &mut Vec<(&'a TraitDecl, &'a MethodDecl)>,
) {
    let lookup_name = trait_name.trim_start_matches('\\').to_ascii_lowercase();
    if !seen_traits.insert(lookup_name) {
        return;
    }
    let Some(trait_decl) = find_trait(traits, trait_name) else {
        return;
    };
    for method in &trait_decl.methods {
        if method.is_abstract && method.name.eq_ignore_ascii_case(method_name) {
            methods.push((trait_decl, method));
        }
    }
    for nested_use in &trait_decl.trait_uses {
        collect_trait_abstract_methods(&nested_use.name, method_name, traits, seen_traits, methods);
    }
}

#[derive(Clone)]
struct TentativeInternalMethod {
    class_name: &'static str,
    signature: &'static str,
    method: MethodDecl,
}

fn find_tentative_internal_parent_method(
    class: &ClassDecl,
    method_name: &str,
    classes: &[ClassDecl],
) -> Option<TentativeInternalMethod> {
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        let normalized = name.trim_start_matches('\\').to_ascii_lowercase();
        if !seen.insert(normalized.clone()) {
            break;
        }
        if let Some(method) = tentative_internal_method(&normalized, method_name) {
            return Some(method);
        }
        parent_name = find_class(classes, name).and_then(|parent| parent.parent_name.as_deref());
    }
    None
}

fn find_tentative_internal_interface_method(
    class: &ClassDecl,
    method_name: &str,
    classes: &[ClassDecl],
) -> Option<TentativeInternalMethod> {
    fn find_in_interface(
        interface_name: &str,
        method_name: &str,
        classes: &[ClassDecl],
        seen_interfaces: &mut HashSet<String>,
    ) -> Option<TentativeInternalMethod> {
        let normalized = interface_name.trim_start_matches('\\').to_ascii_lowercase();
        if !seen_interfaces.insert(normalized.clone()) {
            return None;
        }
        if let Some(method) = tentative_internal_method(&normalized, method_name) {
            return Some(method);
        }
        let interface = find_class(classes, interface_name).filter(|class| class.is_interface)?;
        for parent_name in &interface.interfaces {
            if let Some(method) =
                find_in_interface(parent_name, method_name, classes, seen_interfaces)
            {
                return Some(method);
            }
        }
        None
    }

    fn find_in_class(
        class: &ClassDecl,
        method_name: &str,
        classes: &[ClassDecl],
        seen_classes: &mut HashSet<String>,
        seen_interfaces: &mut HashSet<String>,
    ) -> Option<TentativeInternalMethod> {
        if !seen_classes.insert(class.name.to_ascii_lowercase()) {
            return None;
        }
        for interface_name in &class.interfaces {
            if let Some(method) =
                find_in_interface(interface_name, method_name, classes, seen_interfaces)
            {
                return Some(method);
            }
        }
        let parent = class
            .parent_name
            .as_deref()
            .and_then(|parent_name| find_class(classes, parent_name))?;
        find_in_class(parent, method_name, classes, seen_classes, seen_interfaces)
    }

    find_in_class(
        class,
        method_name,
        classes,
        &mut HashSet::new(),
        &mut HashSet::new(),
    )
}

fn tentative_internal_method(
    normalized_class_name: &str,
    method_name: &str,
) -> Option<TentativeInternalMethod> {
    match (normalized_class_name, method_name.to_ascii_lowercase().as_str()) {
        ("arrayaccess", "offsetset") => Some(modeled_internal_method(
            "ArrayAccess",
            "offsetSet",
            "offsetSet(mixed $offset, mixed $value): void",
            false,
            vec![
                internal_parameter("offset", Some(TypeHint::Mixed), None),
                internal_parameter("value", Some(TypeHint::Mixed), None),
            ],
            TypeHint::Void,
        )),
        ("countable", "count") => Some(modeled_internal_method(
            "Countable",
            "count",
            "count(): int",
            false,
            Vec::new(),
            TypeHint::Int,
        )),
        ("datetimeinterface", "diff") => Some(modeled_internal_method(
            "DateTimeInterface",
            "diff",
            "diff(DateTimeInterface $targetObject, bool $absolute = false): DateInterval",
            false,
            vec![
                internal_parameter(
                    "targetObject",
                    Some(TypeHint::Class("DateTimeInterface".to_string())),
                    None,
                ),
                internal_parameter(
                    "absolute",
                    Some(TypeHint::Bool),
                    Some(Expr::Bool(false, internal_source_span())),
                ),
            ],
            TypeHint::Class("DateInterval".to_string()),
        )),
        ("datetimezone", "gettransitions") => Some(modeled_internal_method(
            "DateTimeZone",
            "getTransitions",
            "getTransitions(int $timestampBegin = PHP_INT_MIN, int $timestampEnd = 2147483647): array|false",
            false,
            vec![
                internal_parameter(
                    "timestampBegin",
                    Some(TypeHint::Int),
                    Some(Expr::Constant(
                        "PHP_INT_MIN".to_string(),
                        internal_source_span(),
                    )),
                ),
                internal_parameter(
                    "timestampEnd",
                    Some(TypeHint::Int),
                    Some(Expr::Int(2147483647, internal_source_span())),
                ),
            ],
            TypeHint::Union(vec![TypeHint::Array, TypeHint::False]),
        )),
        ("datetimezone", "listidentifiers") => Some(modeled_internal_method(
            "DateTimeZone",
            "listIdentifiers",
            "listIdentifiers(int $timezoneGroup = DateTimeZone::ALL, ?string $countryCode = null): array",
            true,
            vec![
                internal_parameter(
                    "timezoneGroup",
                    Some(TypeHint::Int),
                    Some(Expr::ClassConstantFetch {
                        class_name: "DateTimeZone".to_string(),
                        name: "ALL".to_string(),
                        span: internal_source_span(),
                    }),
                ),
                internal_parameter(
                    "countryCode",
                    Some(TypeHint::Nullable(Box::new(TypeHint::String))),
                    Some(Expr::Null(internal_source_span())),
                ),
            ],
            TypeHint::Array,
        )),
        ("datetime", "createfromformat") => Some(modeled_internal_method(
            "DateTime",
            "createFromFormat",
            "createFromFormat(string $format, string $datetime, ?DateTimeZone $timezone = null): DateTime|false",
            true,
            vec![
                internal_parameter("format", Some(TypeHint::String), None),
                internal_parameter("datetime", Some(TypeHint::String), None),
                internal_parameter(
                    "timezone",
                    Some(TypeHint::Nullable(Box::new(TypeHint::Class(
                        "DateTimeZone".to_string(),
                    )))),
                    Some(Expr::Null(internal_source_span())),
                ),
            ],
            TypeHint::Union(vec![
                TypeHint::Class("DateTime".to_string()),
                TypeHint::False,
            ]),
        )),
        ("datetime", "settime") => Some(modeled_internal_method(
            "DateTime",
            "setTime",
            "setTime(int $hour, int $minute, int $second = 0, int $microsecond = 0): DateTime",
            false,
            vec![
                internal_parameter("hour", Some(TypeHint::Int), None),
                internal_parameter("minute", Some(TypeHint::Int), None),
                internal_parameter(
                    "second",
                    Some(TypeHint::Int),
                    Some(Expr::Int(0, internal_source_span())),
                ),
                internal_parameter(
                    "microsecond",
                    Some(TypeHint::Int),
                    Some(Expr::Int(0, internal_source_span())),
                ),
            ],
            TypeHint::Class("DateTime".to_string()),
        )),
        ("datetime", "modify") => Some(modeled_internal_method(
            "DateTime",
            "modify",
            "modify(string $modifier): DateTime|false",
            false,
            vec![internal_parameter("modifier", Some(TypeHint::String), None)],
            TypeHint::Union(vec![
                TypeHint::Class("DateTime".to_string()),
                TypeHint::False,
            ]),
        )),
        ("php_user_filter", "filter") => Some(modeled_internal_method(
            "php_user_filter",
            "filter",
            "filter($in, $out, &$consumed, bool $closing): int",
            false,
            vec![
                internal_parameter("in", None, None),
                internal_parameter("out", None, None),
                internal_parameter_by_ref("consumed", None, None),
                internal_parameter("closing", Some(TypeHint::Bool), None),
            ],
            TypeHint::Int,
        )),
        ("php_user_filter", "oncreate") => Some(modeled_internal_method(
            "php_user_filter",
            "onCreate",
            "onCreate(): bool",
            false,
            Vec::new(),
            TypeHint::Bool,
        )),
        ("php_user_filter", "onclose") => Some(modeled_internal_method(
            "php_user_filter",
            "onClose",
            "onClose(): void",
            false,
            Vec::new(),
            TypeHint::Void,
        )),
        ("php_user_filter", "seek") => Some(modeled_internal_method(
            "php_user_filter",
            "seek",
            "seek(int $offset, int $whence, int $chain): bool",
            false,
            vec![
                internal_parameter("offset", Some(TypeHint::Int), None),
                internal_parameter("whence", Some(TypeHint::Int), None),
                internal_parameter("chain", Some(TypeHint::Int), None),
            ],
            TypeHint::Bool,
        )),
        _ => None,
    }
}

fn modeled_internal_method(
    class_name: &'static str,
    method_name: &str,
    signature: &'static str,
    is_static: bool,
    parameters: Vec<FunctionParameter>,
    return_type: TypeHint,
) -> TentativeInternalMethod {
    TentativeInternalMethod {
        class_name,
        signature,
        method: MethodDecl {
            name: method_name.to_string(),
            visibility: PropertyVisibility::Public,
            trait_name: None,
            trait_method_name: None,
            attributes: AttributeMetadata::default(),
            doc_comment: None,
            has_override_attribute: false,
            parameters,
            return_type: Some(return_type),
            return_by_ref: false,
            is_static,
            is_final: false,
            is_abstract: false,
            body: Vec::new(),
            span: internal_source_span(),
        },
    }
}

fn internal_parameter(
    name: &str,
    type_hint: Option<TypeHint>,
    default_value: Option<Expr>,
) -> FunctionParameter {
    internal_parameter_with_ref(name, type_hint, default_value, false)
}

fn internal_parameter_by_ref(
    name: &str,
    type_hint: Option<TypeHint>,
    default_value: Option<Expr>,
) -> FunctionParameter {
    internal_parameter_with_ref(name, type_hint, default_value, true)
}

fn internal_parameter_with_ref(
    name: &str,
    type_hint: Option<TypeHint>,
    default_value: Option<Expr>,
    by_ref: bool,
) -> FunctionParameter {
    FunctionParameter {
        name: name.to_string(),
        attributes: AttributeMetadata::default(),
        doc_comment: None,
        type_hint,
        by_ref,
        is_variadic: false,
        default_value,
        promoted_property: None,
        span: internal_source_span(),
    }
}

fn internal_source_span() -> SourceSpan {
    SourceSpan::new(0, 0, 0, 0)
}

fn validate_tentative_internal_return_signature(
    class: &ClassDecl,
    method: &MethodDecl,
    tentative_method: &TentativeInternalMethod,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
    compile_warnings: &mut Vec<CompileWarning>,
) -> Result<()> {
    if method.is_static != tentative_method.method.is_static {
        return Ok(());
    }
    validate_method_parameter_signature_pair_named(
        class,
        method,
        tentative_method.class_name,
        &tentative_method.method,
        classes,
        runtime_class_aliases,
    )?;
    if let Some(unavailable_name) = method
        .parameters
        .iter()
        .filter_map(|parameter| parameter.type_hint.as_ref())
        .find_map(|type_hint| first_unavailable_class_name(type_hint, classes))
    {
        return Err(
            method_signature_unresolved_compatibility_error_with_display(
                class,
                method,
                tentative_method.class_name,
                tentative_method.signature,
                &unavailable_name,
            ),
        );
    }
    if method.return_type.as_ref().is_some_and(|return_type| {
        method_return_type_is_subtype(
            class,
            return_type,
            tentative_method
                .method
                .return_type
                .as_ref()
                .expect("modeled internal method must have a return type"),
            classes,
            runtime_class_aliases,
        )
    }) {
        return Ok(());
    }
    if method.attributes.return_type_will_change_count > 0 {
        return Ok(());
    }
    if let Some(return_type) = method.return_type.as_ref() {
        if let Some(unavailable_name) = first_unavailable_class_name(return_type, classes) {
            return Err(
                method_signature_unresolved_compatibility_error_with_display(
                    class,
                    method,
                    tentative_method.class_name,
                    tentative_method.signature,
                    &unavailable_name,
                ),
            );
        }
    }
    compile_warnings.push(CompileWarning {
        message: format!(
            "Return type of {}::{} should either be compatible with {}::{}, or the #[\\ReturnTypeWillChange] attribute should be used to temporarily suppress the notice",
            class.name,
            method_signature_display(method),
            tentative_method.class_name,
            tentative_method.signature,
        ),
        span: method.span,
        kind: CompileWarningKind::Deprecation,
    });
    Ok(())
}

fn method_requires_parent_signature_compatibility(
    method: &MethodDecl,
    parent_method: &MethodDecl,
) -> bool {
    !method.name.eq_ignore_ascii_case("__construct") || parent_method.is_abstract
}

fn method_requires_parent_visibility_compatibility(
    method: &MethodDecl,
    parent_method: &MethodDecl,
) -> bool {
    !method.name.eq_ignore_ascii_case("__construct") || parent_method.is_abstract
}

fn method_signature_compatibility_deferred_to_runtime(
    class: &ClassDecl,
    method: &MethodDecl,
) -> bool {
    method
        .trait_name
        .as_deref()
        .is_some_and(|trait_name| !trait_name.eq_ignore_ascii_case(&class.name))
}

fn inherited_abstract_constructor_visibility_requirement<'a>(
    method: &MethodDecl,
    parent_class: &'a ClassDecl,
    parent_method: &'a MethodDecl,
    classes: &'a [ClassDecl],
) -> Option<(&'a ClassDecl, &'a MethodDecl)> {
    if !method.name.eq_ignore_ascii_case("__construct") || parent_method.is_abstract {
        return None;
    }
    let (required_class, required_method) =
        method_visibility_requirement_source(parent_class, parent_method, classes);
    required_method
        .is_abstract
        .then_some((required_class, required_method))
}

fn inherited_abstract_constructor_signature_requirement<'a>(
    method: &MethodDecl,
    parent_class: &'a ClassDecl,
    parent_method: &'a MethodDecl,
    classes: &'a [ClassDecl],
) -> Option<(&'a ClassDecl, &'a MethodDecl)> {
    if !method.name.eq_ignore_ascii_case("__construct") || parent_method.is_abstract {
        return None;
    }
    let mut parent_name = parent_class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let parent = find_class(classes, name)?;
        if let Some(method) = parent.methods.iter().find(|candidate| {
            candidate.visibility != PropertyVisibility::Private
                && candidate.name.eq_ignore_ascii_case("__construct")
                && candidate.is_abstract
        }) {
            return Some((parent, method));
        }
        parent_name = parent.parent_name.as_deref();
    }
    None
}

fn method_visibility_compatibility_deferred_to_runtime(method: &MethodDecl) -> bool {
    method.visibility != PropertyVisibility::Public
        && magic_method_requires_public_visibility_name(&method.name)
}

fn magic_method_requires_public_visibility_name(name: &str) -> bool {
    matches!(
        name.to_ascii_lowercase().as_str(),
        "__call"
            | "__callstatic"
            | "__get"
            | "__set"
            | "__isset"
            | "__unset"
            | "__sleep"
            | "__wakeup"
            | "__serialize"
            | "__unserialize"
            | "__tostring"
            | "__set_state"
            | "__debuginfo"
    )
}

fn method_visibility_requirement_source<'a>(
    fallback_class: &'a ClassDecl,
    fallback_method: &'a MethodDecl,
    classes: &'a [ClassDecl],
) -> (&'a ClassDecl, &'a MethodDecl) {
    if !fallback_method.name.eq_ignore_ascii_case("__construct") {
        return (fallback_class, fallback_method);
    }

    let mut result = (fallback_class, fallback_method);
    let required_visibility = fallback_method.visibility;
    let mut parent_name = fallback_class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let Some(parent) = find_class(classes, name) else {
            break;
        };
        if let Some(method) = parent.methods.iter().find(|candidate| {
            candidate.visibility != PropertyVisibility::Private
                && candidate.name.eq_ignore_ascii_case("__construct")
                && candidate.visibility == required_visibility
                && candidate.is_abstract
        }) {
            result = (parent, method);
        }
        parent_name = parent.parent_name.as_deref();
    }
    result
}

fn find_visible_parent_method<'a>(
    class: &ClassDecl,
    method_name: &str,
    classes: &'a [ClassDecl],
) -> Option<(&'a ClassDecl, &'a MethodDecl)> {
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let parent = find_class(classes, name)?;
        if let Some(method) = parent.methods.iter().find(|candidate| {
            candidate.visibility != PropertyVisibility::Private
                && candidate.name.eq_ignore_ascii_case(method_name)
        }) {
            return Some((parent, method));
        }
        parent_name = parent.parent_name.as_deref();
    }
    None
}

fn find_final_private_parent_constructor<'a>(
    class: &ClassDecl,
    classes: &'a [ClassDecl],
) -> Option<(&'a ClassDecl, &'a MethodDecl)> {
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let parent = find_class(classes, name)?;
        if let Some(method) = parent.methods.iter().find(|candidate| {
            candidate.name.eq_ignore_ascii_case("__construct")
                && candidate.visibility == PropertyVisibility::Private
                && candidate.is_final
        }) {
            return Some((parent, method));
        }
        parent_name = parent.parent_name.as_deref();
    }
    None
}

fn find_final_modeled_internal_parent_method(
    class: &ClassDecl,
    method_name: &str,
    classes: &[ClassDecl],
) -> Option<(&'static str, &'static str)> {
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        let canonical = name.trim_start_matches('\\');
        if canonical.eq_ignore_ascii_case("PhpToken")
            && method_name.eq_ignore_ascii_case("__construct")
        {
            return Some(("PhpToken", "__construct"));
        }
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let Some(parent) = find_class(classes, name) else {
            break;
        };
        parent_name = parent.parent_name.as_deref();
    }
    None
}

fn find_abstract_parent_constructor<'a>(
    class: &ClassDecl,
    classes: &'a [ClassDecl],
) -> Option<(&'a ClassDecl, &'a MethodDecl)> {
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let parent = find_class(classes, name)?;
        if let Some(method) = parent.methods.iter().find(|candidate| {
            candidate.visibility != PropertyVisibility::Private
                && candidate.name.eq_ignore_ascii_case("__construct")
                && candidate.is_abstract
        }) {
            return Some((parent, method));
        }
        parent_name = parent.parent_name.as_deref();
    }
    None
}

fn collect_interface_methods<'a>(
    interface_name: &str,
    method_name: &str,
    classes: &'a [ClassDecl],
    seen: &mut HashSet<String>,
    methods: &mut Vec<(&'a ClassDecl, &'a MethodDecl)>,
) {
    let lookup_name = interface_name.trim_start_matches('\\').to_ascii_lowercase();
    if !seen.insert(lookup_name) {
        return;
    }
    let Some(interface) = find_class(classes, interface_name) else {
        return;
    };
    if !interface.is_interface {
        return;
    }
    for method in &interface.methods {
        if method.name.eq_ignore_ascii_case(method_name) {
            methods.push((interface, method));
        }
    }
    for parent_name in &interface.interfaces {
        collect_interface_methods(parent_name, method_name, classes, seen, methods);
    }
}

fn validate_method_signature_pair(
    class: &ClassDecl,
    method: &MethodDecl,
    parent_class: &ClassDecl,
    parent_method: &MethodDecl,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> Result<()> {
    validate_method_signature_pair_named(
        class,
        method,
        &parent_class.name,
        parent_method,
        classes,
        runtime_class_aliases,
    )
}

fn validate_method_signature_pair_named(
    class: &ClassDecl,
    method: &MethodDecl,
    parent_class_name: &str,
    parent_method: &MethodDecl,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> Result<()> {
    validate_method_parameter_signature_pair_named(
        class,
        method,
        parent_class_name,
        parent_method,
        classes,
        runtime_class_aliases,
    )?;

    if let Some(parent_return_type) = &parent_method.return_type {
        let Some(return_type) = &method.return_type else {
            return Err(method_signature_compatibility_error_named(
                class,
                method,
                parent_class_name,
                parent_method,
            ));
        };
        if !method_return_type_is_subtype(
            class,
            return_type,
            parent_return_type,
            classes,
            runtime_class_aliases,
        ) {
            if let Some(unavailable_name) =
                unresolved_compatibility_class(return_type, parent_return_type, classes)
            {
                return Err(method_signature_unresolved_compatibility_error_named(
                    class,
                    method,
                    parent_class_name,
                    parent_method,
                    &unavailable_name,
                ));
            }
            return Err(method_signature_compatibility_error_named(
                class,
                method,
                parent_class_name,
                parent_method,
            ));
        }
    }

    Ok(())
}

fn validate_method_parameter_signature_pair_named(
    class: &ClassDecl,
    method: &MethodDecl,
    parent_class_name: &str,
    parent_method: &MethodDecl,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> Result<()> {
    if parent_method.return_by_ref && !method.return_by_ref {
        return Err(method_signature_compatibility_error_named(
            class,
            method,
            parent_class_name,
            parent_method,
        ));
    }

    let mut parameter_index = 0;
    for parent_parameter in &parent_method.parameters {
        if parent_parameter.is_variadic {
            let mut has_covering_variadic = false;
            while let Some(parameter) = method.parameters.get(parameter_index) {
                if !parameter_can_satisfy_parent_parameter(
                    parameter,
                    parent_parameter,
                    classes,
                    runtime_class_aliases,
                ) {
                    return Err(parameter_signature_compatibility_error_named(
                        class,
                        method,
                        parent_class_name,
                        parent_method,
                        parameter,
                        parent_parameter,
                        classes,
                    ));
                }
                if !parameter.is_variadic && parameter.default_value.is_none() {
                    return Err(method_signature_compatibility_error_named(
                        class,
                        method,
                        parent_class_name,
                        parent_method,
                    ));
                }
                if parameter.is_variadic {
                    has_covering_variadic = true;
                    break;
                }
                parameter_index += 1;
            }
            if !has_covering_variadic {
                return Err(method_signature_compatibility_error_named(
                    class,
                    method,
                    parent_class_name,
                    parent_method,
                ));
            }
            return Ok(());
        }

        let Some(parameter) = method.parameters.get(parameter_index) else {
            return Err(method_signature_compatibility_error_named(
                class,
                method,
                parent_class_name,
                parent_method,
            ));
        };
        if !parameter_can_satisfy_parent_parameter(
            parameter,
            parent_parameter,
            classes,
            runtime_class_aliases,
        ) || (parent_parameter.default_value.is_some()
            && parameter.default_value.is_none()
            && !parameter.is_variadic)
        {
            if !parameter_can_satisfy_parent_parameter(
                parameter,
                parent_parameter,
                classes,
                runtime_class_aliases,
            ) {
                return Err(parameter_signature_compatibility_error_named(
                    class,
                    method,
                    parent_class_name,
                    parent_method,
                    parameter,
                    parent_parameter,
                    classes,
                ));
            }
            return Err(method_signature_compatibility_error_named(
                class,
                method,
                parent_class_name,
                parent_method,
            ));
        }
        if !parameter.is_variadic {
            parameter_index += 1;
        }
    }
    for parameter in method.parameters.iter().skip(parameter_index) {
        if parameter.default_value.is_none() && !parameter.is_variadic {
            return Err(method_signature_compatibility_error_named(
                class,
                method,
                parent_class_name,
                parent_method,
            ));
        }
    }

    Ok(())
}

fn parameter_can_satisfy_parent_parameter(
    parameter: &FunctionParameter,
    parent_parameter: &FunctionParameter,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> bool {
    parameter.by_ref == parent_parameter.by_ref
        && parameter_type_is_contravariant(
            parameter,
            parent_parameter,
            classes,
            runtime_class_aliases,
        )
}

fn parameter_signature_compatibility_error_named(
    class: &ClassDecl,
    method: &MethodDecl,
    parent_class_name: &str,
    parent_method: &MethodDecl,
    parameter: &FunctionParameter,
    parent_parameter: &FunctionParameter,
    classes: &[ClassDecl],
) -> Diagnostic {
    if let (Some(type_hint), Some(parent_type_hint)) =
        (&parameter.type_hint, &parent_parameter.type_hint)
    {
        if let Some(unavailable_name) =
            unresolved_compatibility_class(type_hint, parent_type_hint, classes)
        {
            if unresolved_class_can_affect_subtype_check(parent_type_hint, type_hint) {
                return method_signature_unresolved_compatibility_error_named(
                    class,
                    method,
                    parent_class_name,
                    parent_method,
                    &unavailable_name,
                );
            }
        }
    }
    method_signature_compatibility_error_named(class, method, parent_class_name, parent_method)
}

fn unresolved_class_can_affect_subtype_check(candidate: &TypeHint, target: &TypeHint) -> bool {
    type_hint_alternatives(candidate).iter().any(|candidate| {
        type_hint_alternatives(target)
            .iter()
            .any(|target| type_alternative_unresolved_class_can_affect(candidate, target))
    })
}

fn type_alternative_unresolved_class_can_affect(
    candidate: &TypeAlternative,
    target: &TypeAlternative,
) -> bool {
    candidate.atoms.iter().any(|candidate_atom| {
        target
            .atoms
            .iter()
            .any(|target_atom| type_atom_unresolved_class_can_affect(candidate_atom, target_atom))
    })
}

fn type_atom_unresolved_class_can_affect(candidate: &TypeAtom, target: &TypeAtom) -> bool {
    match (candidate, target) {
        (TypeAtom::Class(_), TypeAtom::Array)
        | (TypeAtom::Class(_), TypeAtom::Int)
        | (TypeAtom::Class(_), TypeAtom::Float)
        | (TypeAtom::Class(_), TypeAtom::String)
        | (TypeAtom::Class(_), TypeAtom::Bool)
        | (TypeAtom::Class(_), TypeAtom::True)
        | (TypeAtom::Class(_), TypeAtom::False)
        | (TypeAtom::Class(_), TypeAtom::Null)
        | (TypeAtom::Class(_), TypeAtom::Void)
        | (TypeAtom::Class(_), TypeAtom::Never)
        | (TypeAtom::Array, TypeAtom::Class(_))
        | (TypeAtom::Int, TypeAtom::Class(_))
        | (TypeAtom::Float, TypeAtom::Class(_))
        | (TypeAtom::String, TypeAtom::Class(_))
        | (TypeAtom::Bool, TypeAtom::Class(_))
        | (TypeAtom::True, TypeAtom::Class(_))
        | (TypeAtom::False, TypeAtom::Class(_))
        | (TypeAtom::Null, TypeAtom::Class(_))
        | (TypeAtom::Void, TypeAtom::Class(_))
        | (TypeAtom::Never, TypeAtom::Class(_)) => false,
        (TypeAtom::Class(_), _) | (_, TypeAtom::Class(_)) => true,
        _ => false,
    }
}

fn unresolved_compatibility_class(
    candidate: &TypeHint,
    target: &TypeHint,
    classes: &[ClassDecl],
) -> Option<String> {
    first_unavailable_class_name(candidate, classes)
        .or_else(|| first_unavailable_class_name(target, classes))
}

fn first_unavailable_class_name(type_hint: &TypeHint, classes: &[ClassDecl]) -> Option<String> {
    match type_hint {
        TypeHint::Class(name) if !class_type_name_is_available(name, classes) => Some(name.clone()),
        TypeHint::Nullable(inner) => first_unavailable_class_name(inner, classes),
        TypeHint::Union(types) | TypeHint::Intersection(types) => types
            .iter()
            .find_map(|member| first_unavailable_class_name(member, classes)),
        TypeHint::Null
        | TypeHint::Array
        | TypeHint::Int
        | TypeHint::Float
        | TypeHint::String
        | TypeHint::Bool
        | TypeHint::True
        | TypeHint::False
        | TypeHint::Callable
        | TypeHint::Object
        | TypeHint::Iterable
        | TypeHint::Mixed
        | TypeHint::Void
        | TypeHint::Never
        | TypeHint::Static
        | TypeHint::Class(_) => None,
    }
}

fn class_type_name_is_available(name: &str, classes: &[ClassDecl]) -> bool {
    is_modeled_builtin_interface_name(name)
        || name.eq_ignore_ascii_case("stdClass")
        || name.eq_ignore_ascii_case("Closure")
        || name
            .trim_start_matches('\\')
            .eq_ignore_ascii_case("PhpToken")
        || name.eq_ignore_ascii_case("ArrayIterator")
        || name.eq_ignore_ascii_case("EmptyIterator")
        || name.eq_ignore_ascii_case("IteratorIterator")
        || name.eq_ignore_ascii_case("ArrayObject")
        || name.eq_ignore_ascii_case("DirectoryIterator")
        || name.eq_ignore_ascii_case("FilesystemIterator")
        || name.eq_ignore_ascii_case("GlobIterator")
        || name.eq_ignore_ascii_case("RegexIterator")
        || name.eq_ignore_ascii_case("RecursiveCachingIterator")
        || name.eq_ignore_ascii_case("RecursiveRegexIterator")
        || name.eq_ignore_ascii_case("SplFixedArray")
        || name.eq_ignore_ascii_case("SplObjectStorage")
        || name.eq_ignore_ascii_case("WeakMap")
        || name.eq_ignore_ascii_case("WeakReference")
        || name.eq_ignore_ascii_case("SplHeap")
        || name.eq_ignore_ascii_case("SplMaxHeap")
        || name.eq_ignore_ascii_case("SplMinHeap")
        || name.eq_ignore_ascii_case("SplPriorityQueue")
        || name.eq_ignore_ascii_case("SplDoublyLinkedList")
        || name.eq_ignore_ascii_case("SplQueue")
        || name.eq_ignore_ascii_case("SplStack")
        || name.eq_ignore_ascii_case("SplFileInfo")
        || name.eq_ignore_ascii_case("SplFileObject")
        || name.eq_ignore_ascii_case("SplTempFileObject")
        || name
            .trim_start_matches('\\')
            .eq_ignore_ascii_case("BcMath\\Number")
        || name.eq_ignore_ascii_case("Generator")
        || is_modeled_builtin_date_class_name(name)
        || is_modeled_builtin_enum_class_name(name)
        || is_modeled_builtin_exception_class_name(name)
        || is_modeled_builtin_reflection_class_name(name)
        || is_modeled_archive_network_class_name(name)
        || is_modeled_extension_internal_class_name(name)
        || is_modeled_builtin_uri_class_name(name)
        || find_class(classes, name).is_some()
}

fn parameter_type_is_contravariant(
    parameter: &FunctionParameter,
    parent_parameter: &FunctionParameter,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> bool {
    match (&parameter.type_hint, &parent_parameter.type_hint) {
        (None, _) => true,
        (Some(TypeHint::Mixed), None) => true,
        (Some(_), None) => false,
        (Some(type_hint), Some(parent_type_hint)) => {
            type_hint_is_subtype(parent_type_hint, type_hint, classes, runtime_class_aliases)
        }
    }
}

fn method_signature_compatibility_error_named(
    class: &ClassDecl,
    method: &MethodDecl,
    parent_class_name: &str,
    parent_method: &MethodDecl,
) -> Diagnostic {
    Diagnostic::new(
        format!(
            "Declaration of {} must be compatible with {}",
            class_method_signature_display_for_compatibility(&class.name, method),
            class_method_signature_display_for_compatibility(parent_class_name, parent_method)
        ),
        Some(method.span),
    )
}

fn method_signature_unresolved_compatibility_error_named(
    class: &ClassDecl,
    method: &MethodDecl,
    parent_class_name: &str,
    parent_method: &MethodDecl,
    unavailable_name: &str,
) -> Diagnostic {
    Diagnostic::new(
        format!(
            "Could not check compatibility between {}::{} and {}::{}, because class {} is not available",
            class.name,
            method_signature_display_canonical(method),
            parent_class_name,
            method_signature_display_canonical(parent_method),
            unavailable_name
        ),
        Some(method.span),
    )
}

fn method_signature_unresolved_compatibility_error_with_display(
    class: &ClassDecl,
    method: &MethodDecl,
    parent_class_name: &str,
    parent_method_signature: &str,
    unavailable_name: &str,
) -> Diagnostic {
    Diagnostic::new(
        format!(
            "Could not check compatibility between {}::{} and {}::{}, because class {} is not available",
            class.name,
            method_signature_display_canonical(method),
            parent_class_name,
            parent_method_signature,
            unavailable_name
        ),
        Some(method.span),
    )
}

fn method_signature_display(method: &MethodDecl) -> String {
    method_signature_display_with(method, type_hint_display)
}

fn method_signature_display_for_class(method: &MethodDecl, class_name: &str) -> String {
    method_signature_display_with_default_scope(method, type_hint_display, Some(class_name))
}

fn method_signature_display_canonical(method: &MethodDecl) -> String {
    method_signature_display_with(method, type_hint_display_canonical)
}

fn class_method_signature_display_for_compatibility(
    class_name: &str,
    method: &MethodDecl,
) -> String {
    let method_display = method_signature_display_for_class(method, class_name);
    if method.return_by_ref {
        format!(
            "&{}::{}",
            class_name,
            method_display.trim_start_matches('&')
        )
    } else {
        format!("{}::{}", class_name, method_display)
    }
}

fn method_signature_display_with(
    method: &MethodDecl,
    display_type: fn(&TypeHint) -> String,
) -> String {
    method_signature_display_with_default_scope(method, display_type, None)
}

fn method_signature_display_with_default_scope(
    method: &MethodDecl,
    display_type: fn(&TypeHint) -> String,
    default_scope: Option<&str>,
) -> String {
    let mut signature = String::new();
    if method.return_by_ref {
        signature.push('&');
    }
    signature.push_str(&method.name);
    signature.push('(');
    let required_parameter_count = signature_required_parameter_count(&method.parameters);
    for (index, parameter) in method.parameters.iter().enumerate() {
        if index > 0 {
            signature.push_str(", ");
        }
        signature.push_str(&parameter_signature_display_with(
            parameter,
            display_type,
            default_scope,
            index >= required_parameter_count,
        ));
    }
    signature.push(')');
    if let Some(return_type) = &method.return_type {
        signature.push_str(": ");
        signature.push_str(&display_type(return_type));
    }
    signature
}

fn parameter_signature_display_with(
    parameter: &FunctionParameter,
    display_type: fn(&TypeHint) -> String,
    default_scope: Option<&str>,
    show_default: bool,
) -> String {
    let mut display = String::new();
    if let Some(type_hint) = &parameter.type_hint {
        if parameter_default_value_is_null_expr(parameter)
            && !type_hint_accepts_null_default(type_hint)
            && type_hint_allows_implicit_nullable_default(type_hint)
        {
            display.push_str(&implicit_nullable_type_hint_display_with(
                type_hint,
                display_type,
            ));
        } else {
            display.push_str(&display_type(type_hint));
        }
        display.push(' ');
    }
    if parameter.by_ref {
        display.push('&');
    }
    if parameter.is_variadic {
        display.push_str("...");
    }
    display.push('$');
    display.push_str(&parameter.name);
    if show_default {
        if let Some(default_value) = &parameter.default_value {
            display.push_str(" = ");
            display.push_str(&parameter_default_display(default_value, default_scope));
        }
    }
    display
}

fn signature_required_parameter_count(parameters: &[FunctionParameter]) -> usize {
    parameters
        .iter()
        .rposition(|parameter| !parameter.is_variadic && parameter.default_value.is_none())
        .map_or(0, |index| index + 1)
}

fn parameter_default_value_is_null_expr(parameter: &FunctionParameter) -> bool {
    matches!(parameter.default_value.as_ref(), Some(Expr::Null(_)))
}

fn type_hint_allows_implicit_nullable_default(type_hint: &TypeHint) -> bool {
    match type_hint {
        TypeHint::Mixed | TypeHint::Null | TypeHint::Nullable(_) => false,
        TypeHint::Union(types) => !types.iter().any(|member| matches!(member, TypeHint::Null)),
        TypeHint::Void | TypeHint::Never => false,
        TypeHint::Array
        | TypeHint::Int
        | TypeHint::Float
        | TypeHint::String
        | TypeHint::Bool
        | TypeHint::True
        | TypeHint::False
        | TypeHint::Callable
        | TypeHint::Object
        | TypeHint::Iterable
        | TypeHint::Static
        | TypeHint::Intersection(_)
        | TypeHint::Class(_) => true,
    }
}

fn implicit_nullable_type_hint_display_with(
    type_hint: &TypeHint,
    display_type: fn(&TypeHint) -> String,
) -> String {
    match type_hint {
        TypeHint::Union(types) => {
            let mut members = types.iter().map(display_type).collect::<Vec<_>>();
            members.push("null".to_string());
            members.join("|")
        }
        TypeHint::Intersection(_) => format!("{}|null", display_type(type_hint)),
        _ => format!("?{}", display_type(type_hint)),
    }
}

fn parameter_default_display(default_value: &Expr, default_scope: Option<&str>) -> String {
    match default_value {
        Expr::Null(_) => "null".to_string(),
        Expr::Bool(value, _) => value.to_string(),
        Expr::Int(value, _) => value.to_string(),
        Expr::Float(value, _) => parameter_default_float_display(*value),
        Expr::String(value, _) => parameter_default_string_display(value),
        Expr::Array { elements, .. } if elements.is_empty() => "[]".to_string(),
        Expr::Array { .. } => "[...]".to_string(),
        Expr::Constant(name, _) => name.trim_start_matches('\\').to_string(),
        Expr::ClassConstantFetch {
            class_name, name, ..
        } if name.eq_ignore_ascii_case("class") && class_name.eq_ignore_ascii_case("self") => {
            default_scope
                .map(|scope| format!("'{}'", scope.replace('\'', "\\'")))
                .unwrap_or_else(|| format!("{class_name}::{name}"))
        }
        Expr::ClassConstantFetch {
            class_name, name, ..
        } => format!("{class_name}::{name}"),
        _ => "<expression>".to_string(),
    }
}

fn parameter_default_float_display(value: f64) -> String {
    let mut display = format!("{value:.13}");
    if display.contains('.') {
        display = display
            .trim_end_matches('0')
            .trim_end_matches('.')
            .to_string();
    }
    if display == "-0" {
        "0".to_string()
    } else {
        display
    }
}

fn parameter_default_string_display(value: &str) -> String {
    let escaped = value.replace('\'', "\\'");
    let display = if escaped.chars().count() > 15 {
        let mut truncated = escaped.chars().take(10).collect::<String>();
        truncated.push_str("...");
        truncated
    } else {
        escaped
    };
    format!("'{display}'")
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum TypeAtom {
    Null,
    Array,
    Int,
    Float,
    String,
    Bool,
    True,
    False,
    Callable,
    Object,
    Mixed,
    Void,
    Never,
    Static,
    Class(String),
}

#[derive(Debug, Clone)]
struct TypeAlternative {
    atoms: Vec<TypeAtom>,
}

fn type_hint_is_subtype(
    candidate: &TypeHint,
    target: &TypeHint,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> bool {
    type_hint_is_subtype_with_context(
        candidate,
        target,
        classes,
        runtime_class_aliases,
        TypeCompatibilityContext::default(),
    )
}

fn method_return_type_is_subtype(
    class: &ClassDecl,
    candidate: &TypeHint,
    target: &TypeHint,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> bool {
    type_hint_is_subtype_with_context(
        candidate,
        target,
        classes,
        runtime_class_aliases,
        TypeCompatibilityContext {
            current_class_name: Some(class.name.as_str()),
            final_class_static_name: class.is_final.then_some(class.name.as_str()),
        },
    )
}

#[derive(Clone, Copy, Default)]
struct TypeCompatibilityContext<'a> {
    current_class_name: Option<&'a str>,
    final_class_static_name: Option<&'a str>,
}

fn type_hint_is_subtype_with_context(
    candidate: &TypeHint,
    target: &TypeHint,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
    context: TypeCompatibilityContext<'_>,
) -> bool {
    let candidate_alternatives = type_hint_alternatives(candidate);
    let target_alternatives = type_hint_alternatives(target);
    candidate_alternatives.iter().all(|candidate| {
        target_alternatives.iter().any(|target| {
            type_alternative_is_subtype(candidate, target, classes, runtime_class_aliases, context)
        })
    })
}

fn type_hint_alternatives(type_hint: &TypeHint) -> Vec<TypeAlternative> {
    match type_hint {
        TypeHint::Null => vec![TypeAlternative {
            atoms: vec![TypeAtom::Null],
        }],
        TypeHint::Array => vec![TypeAlternative {
            atoms: vec![TypeAtom::Array],
        }],
        TypeHint::Int => vec![TypeAlternative {
            atoms: vec![TypeAtom::Int],
        }],
        TypeHint::Float => vec![TypeAlternative {
            atoms: vec![TypeAtom::Float],
        }],
        TypeHint::String => vec![TypeAlternative {
            atoms: vec![TypeAtom::String],
        }],
        TypeHint::Bool => vec![TypeAlternative {
            atoms: vec![TypeAtom::Bool],
        }],
        TypeHint::True => vec![TypeAlternative {
            atoms: vec![TypeAtom::True],
        }],
        TypeHint::False => vec![TypeAlternative {
            atoms: vec![TypeAtom::False],
        }],
        TypeHint::Callable => vec![TypeAlternative {
            atoms: vec![TypeAtom::Callable],
        }],
        TypeHint::Object => vec![TypeAlternative {
            atoms: vec![TypeAtom::Object],
        }],
        TypeHint::Iterable => vec![
            TypeAlternative {
                atoms: vec![TypeAtom::Array],
            },
            TypeAlternative {
                atoms: vec![TypeAtom::Class("Traversable".to_string())],
            },
        ],
        TypeHint::Mixed => vec![TypeAlternative {
            atoms: vec![TypeAtom::Mixed],
        }],
        TypeHint::Void => vec![TypeAlternative {
            atoms: vec![TypeAtom::Void],
        }],
        TypeHint::Never => vec![TypeAlternative {
            atoms: vec![TypeAtom::Never],
        }],
        TypeHint::Static => vec![TypeAlternative {
            atoms: vec![TypeAtom::Static],
        }],
        TypeHint::Nullable(inner) => {
            let mut alternatives = type_hint_alternatives(inner);
            alternatives.push(TypeAlternative {
                atoms: vec![TypeAtom::Null],
            });
            alternatives
        }
        TypeHint::Union(types) => types.iter().flat_map(type_hint_alternatives).collect(),
        TypeHint::Intersection(types) => {
            let mut alternatives = vec![TypeAlternative { atoms: Vec::new() }];
            for type_hint in types {
                let member_alternatives = type_hint_alternatives(type_hint);
                let mut combined = Vec::new();
                for current in &alternatives {
                    for member in &member_alternatives {
                        let mut atoms = current.atoms.clone();
                        atoms.extend(member.atoms.clone());
                        combined.push(TypeAlternative { atoms });
                    }
                }
                alternatives = combined;
            }
            alternatives
        }
        TypeHint::Class(class_name) => vec![TypeAlternative {
            atoms: vec![TypeAtom::Class(class_name.clone())],
        }],
    }
}

fn type_alternative_is_subtype(
    candidate: &TypeAlternative,
    target: &TypeAlternative,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
    context: TypeCompatibilityContext<'_>,
) -> bool {
    target.atoms.iter().all(|target_atom| {
        candidate.atoms.iter().any(|candidate_atom| {
            type_atom_is_subtype(
                candidate_atom,
                target_atom,
                classes,
                runtime_class_aliases,
                context,
            )
        })
    })
}

fn type_atom_is_subtype(
    candidate: &TypeAtom,
    target: &TypeAtom,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
    context: TypeCompatibilityContext<'_>,
) -> bool {
    if matches!(candidate, TypeAtom::Void) && matches!(target, TypeAtom::Mixed) {
        return false;
    }
    if matches!(candidate, TypeAtom::Never) || matches!(target, TypeAtom::Mixed) {
        return true;
    }
    if candidate == target {
        return true;
    }
    match (candidate, target) {
        (TypeAtom::True | TypeAtom::False, TypeAtom::Bool) => true,
        (TypeAtom::Static, TypeAtom::Object) => true,
        (TypeAtom::Static, TypeAtom::Class(target)) => {
            context.current_class_name.is_some_and(|class_name| {
                class_type_name_is_subtype(class_name, target, classes, runtime_class_aliases)
            })
        }
        (TypeAtom::Class(candidate), TypeAtom::Static) => {
            context.final_class_static_name.is_some_and(|class_name| {
                let candidate_name =
                    resolve_runtime_class_alias_from_map(candidate, runtime_class_aliases);
                candidate_name.eq_ignore_ascii_case(class_name)
            })
        }
        (TypeAtom::Class(candidate), TypeAtom::Callable)
            if candidate.eq_ignore_ascii_case("Closure") =>
        {
            true
        }
        (TypeAtom::Class(_), TypeAtom::Object) => true,
        (TypeAtom::Class(candidate), TypeAtom::Class(target)) => {
            class_type_name_is_subtype(candidate, target, classes, runtime_class_aliases)
        }
        _ => false,
    }
}

fn resolve_runtime_class_alias_from_map(
    name: &str,
    runtime_class_aliases: &HashMap<String, String>,
) -> String {
    if matches!(
        name.to_ascii_lowercase().as_str(),
        "self" | "static" | "parent"
    ) {
        return name.to_string();
    }
    let mut resolved = normalize_runtime_class_alias_target(name);
    let mut seen = HashSet::new();
    loop {
        let key = normalize_runtime_class_alias_key(&resolved);
        if !seen.insert(key.clone()) {
            break;
        }
        let Some(target) = runtime_class_aliases.get(&key) else {
            break;
        };
        resolved = normalize_runtime_class_alias_target(target);
    }
    resolved
}

fn class_type_name_is_subtype(
    candidate_name: &str,
    target_name: &str,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> bool {
    let candidate_name =
        resolve_runtime_class_alias_from_map(candidate_name, runtime_class_aliases);
    let target_name = resolve_runtime_class_alias_from_map(target_name, runtime_class_aliases);
    if candidate_name.eq_ignore_ascii_case(&target_name) {
        return true;
    }
    if class_type_name_is_conditionally_declared(&candidate_name, classes)
        || class_type_name_is_conditionally_declared(&target_name, classes)
    {
        return true;
    }
    if builtin_class_type_is_subtype(&candidate_name, &target_name) {
        return true;
    }
    let Some(candidate) = find_class(classes, &candidate_name) else {
        return false;
    };
    if candidate.is_interface {
        return interface_type_extends(candidate, &target_name, classes, runtime_class_aliases);
    }
    class_type_extends_or_implements(candidate, &target_name, classes, runtime_class_aliases)
}

fn class_type_name_is_conditionally_declared(name: &str, classes: &[ClassDecl]) -> bool {
    find_class(classes, name).is_some_and(|class| class.is_conditionally_declared)
}

fn builtin_class_type_is_subtype(candidate_name: &str, target_name: &str) -> bool {
    if target_name.eq_ignore_ascii_case("Traversable")
        && (candidate_name.eq_ignore_ascii_case("Iterator")
            || candidate_name.eq_ignore_ascii_case("IteratorAggregate"))
    {
        return true;
    }
    if target_name.eq_ignore_ascii_case("SplHeap")
        && (candidate_name.eq_ignore_ascii_case("SplMaxHeap")
            || candidate_name.eq_ignore_ascii_case("SplMinHeap"))
    {
        return true;
    }
    let implemented = if candidate_name.eq_ignore_ascii_case("ArrayIterator") {
        &["ArrayAccess", "Countable", "Iterator", "Traversable"][..]
    } else if candidate_name.eq_ignore_ascii_case("EmptyIterator") {
        &["Iterator", "Traversable"][..]
    } else if candidate_name.eq_ignore_ascii_case("IteratorIterator") {
        &["Iterator", "Traversable"][..]
    } else if candidate_name.eq_ignore_ascii_case("ArrayObject") {
        &[
            "ArrayAccess",
            "Countable",
            "IteratorAggregate",
            "Traversable",
        ][..]
    } else if candidate_name.eq_ignore_ascii_case("SplFixedArray") {
        &[
            "ArrayAccess",
            "Countable",
            "IteratorAggregate",
            "Traversable",
        ][..]
    } else if candidate_name.eq_ignore_ascii_case("SplObjectStorage") {
        &["ArrayAccess", "Countable", "Iterator", "Traversable"][..]
    } else if candidate_name.eq_ignore_ascii_case("WeakMap") {
        &["ArrayAccess", "Countable", "Iterator", "Traversable"][..]
    } else if candidate_name.eq_ignore_ascii_case("SplHeap")
        || candidate_name.eq_ignore_ascii_case("SplMaxHeap")
        || candidate_name.eq_ignore_ascii_case("SplMinHeap")
        || candidate_name.eq_ignore_ascii_case("SplPriorityQueue")
    {
        &["Countable", "Iterator", "Traversable"][..]
    } else if candidate_name.eq_ignore_ascii_case("SplDoublyLinkedList")
        || candidate_name.eq_ignore_ascii_case("SplQueue")
        || candidate_name.eq_ignore_ascii_case("SplStack")
    {
        &["ArrayAccess", "Countable", "Iterator", "Traversable"][..]
    } else if candidate_name.eq_ignore_ascii_case("DirectoryIterator")
        || candidate_name.eq_ignore_ascii_case("FilesystemIterator")
        || candidate_name.eq_ignore_ascii_case("GlobIterator")
        || candidate_name.eq_ignore_ascii_case("RecursiveDirectoryIterator")
    {
        &["Iterator", "SeekableIterator", "Stringable", "Traversable"][..]
    } else if candidate_name.eq_ignore_ascii_case("RegexIterator") {
        &["Iterator", "OuterIterator", "Traversable"][..]
    } else if candidate_name.eq_ignore_ascii_case("RecursiveCachingIterator")
        || candidate_name.eq_ignore_ascii_case("RecursiveRegexIterator")
    {
        &[
            "Iterator",
            "OuterIterator",
            "RecursiveIterator",
            "Traversable",
        ][..]
    } else if candidate_name.eq_ignore_ascii_case("SplFileObject")
        || candidate_name.eq_ignore_ascii_case("SplTempFileObject")
    {
        &[
            "Iterator",
            "RecursiveIterator",
            "SeekableIterator",
            "Traversable",
        ][..]
    } else if candidate_name.eq_ignore_ascii_case("Generator") {
        &["Iterator", "Traversable"][..]
    } else if candidate_name
        .trim_start_matches('\\')
        .eq_ignore_ascii_case("BcMath\\Number")
    {
        &["Stringable"][..]
    } else if candidate_name.eq_ignore_ascii_case("DateTime")
        || candidate_name.eq_ignore_ascii_case("DateTimeImmutable")
    {
        &["DateTimeInterface"][..]
    } else if is_modeled_builtin_enum_class_name(candidate_name) {
        &["UnitEnum", "BackedEnum"][..]
    } else if candidate_name.eq_ignore_ascii_case("ReflectionFunction")
        || candidate_name.eq_ignore_ascii_case("ReflectionMethod")
    {
        &["ReflectionFunctionAbstract"][..]
    } else if candidate_name.eq_ignore_ascii_case("ReflectionObject") {
        &["ReflectionClass"][..]
    } else {
        &[][..]
    };
    implemented
        .iter()
        .any(|interface| interface.eq_ignore_ascii_case(target_name))
}

fn class_type_extends_or_implements(
    class: &ClassDecl,
    target_name: &str,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> bool {
    if target_name.eq_ignore_ascii_case("Stringable")
        && class
            .methods
            .iter()
            .any(|method| method.name.eq_ignore_ascii_case("__toString"))
    {
        return true;
    }
    if class.interfaces.iter().any(|interface| {
        interface_name_is_subtype(interface, target_name, classes, runtime_class_aliases)
    }) {
        return true;
    }
    let Some(parent_name) = class.parent_name.as_deref() else {
        return false;
    };
    let parent_name = resolve_runtime_class_alias_from_map(parent_name, runtime_class_aliases);
    if parent_name.eq_ignore_ascii_case(target_name)
        || builtin_class_type_is_subtype(&parent_name, target_name)
    {
        return true;
    }
    find_class(classes, &parent_name).is_some_and(|parent| {
        class_type_extends_or_implements(parent, target_name, classes, runtime_class_aliases)
    })
}

fn interface_name_is_subtype(
    interface_name: &str,
    target_name: &str,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> bool {
    let interface_name =
        resolve_runtime_class_alias_from_map(interface_name, runtime_class_aliases);
    if interface_name.eq_ignore_ascii_case(target_name)
        || builtin_class_type_is_subtype(&interface_name, target_name)
    {
        return true;
    }
    find_class(classes, &interface_name)
        .filter(|interface| interface.is_interface)
        .is_some_and(|interface| {
            interface_type_extends(interface, target_name, classes, runtime_class_aliases)
        })
}

fn interface_type_extends(
    interface: &ClassDecl,
    target_name: &str,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> bool {
    interface.interfaces.iter().any(|parent_name| {
        interface_name_is_subtype(parent_name, target_name, classes, runtime_class_aliases)
    })
}

fn type_hint_display(type_hint: &TypeHint) -> String {
    match type_hint {
        TypeHint::Null => "null".to_string(),
        TypeHint::Array => "array".to_string(),
        TypeHint::Int => "int".to_string(),
        TypeHint::Float => "float".to_string(),
        TypeHint::String => "string".to_string(),
        TypeHint::Bool => "bool".to_string(),
        TypeHint::True => "true".to_string(),
        TypeHint::False => "false".to_string(),
        TypeHint::Callable => "callable".to_string(),
        TypeHint::Object => "object".to_string(),
        TypeHint::Iterable => "Traversable|array".to_string(),
        TypeHint::Mixed => "mixed".to_string(),
        TypeHint::Void => "void".to_string(),
        TypeHint::Never => "never".to_string(),
        TypeHint::Static => "static".to_string(),
        TypeHint::Nullable(inner) => match inner.as_ref() {
            TypeHint::Iterable => "Traversable|array|null".to_string(),
            TypeHint::Union(_) | TypeHint::Intersection(_) => {
                format!("{}|null", type_hint_display(inner))
            }
            _ => format!("?{}", type_hint_display(inner)),
        },
        TypeHint::Union(types) => {
            let mut members = types
                .iter()
                .map(|member| (member, type_hint_union_member_display(member)))
                .collect::<Vec<_>>();
            if members
                .iter()
                .all(|(_, display)| union_builtin_display_rank(display).is_some())
            {
                members.sort_by_key(|(_, display)| union_builtin_display_rank(display).unwrap());
            } else {
                members.sort_by_key(|(member, _)| type_hint_union_member_is_builtin_like(member));
            }
            members
                .into_iter()
                .map(|(_, display)| display)
                .collect::<Vec<_>>()
                .join("|")
        }
        TypeHint::Intersection(types) => types
            .iter()
            .map(type_hint_display)
            .collect::<Vec<_>>()
            .join("&"),
        TypeHint::Class(class_name) => class_name.clone(),
    }
}

fn type_hint_accepts_null_default(type_hint: &TypeHint) -> bool {
    match type_hint {
        TypeHint::Null | TypeHint::Mixed | TypeHint::Nullable(_) => true,
        TypeHint::Union(types) => types
            .iter()
            .any(|member| type_hint_accepts_null_default(member)),
        _ => false,
    }
}

fn validate_class_constant_literal_type(
    class_name: &str,
    constant_name: &str,
    type_hint: &Option<TypeHint>,
    value: &Expr,
    span: SourceSpan,
) -> Result<()> {
    let Some(type_hint) = type_hint else {
        return Ok(());
    };
    let Some(given_type) = class_constant_literal_type_name(value) else {
        return Ok(());
    };
    if class_constant_type_accepts_literal(type_hint, value) {
        return Ok(());
    }
    Err(Diagnostic::new(
        format!(
            "Cannot use {given_type} as value for class constant {class_name}::{constant_name} of type {}",
            type_hint_display(type_hint)
        ),
        Some(span),
    ))
}

fn validate_class_constant_type_allowed(
    class_name: &str,
    constant_name: &str,
    type_hint: &Option<TypeHint>,
    span: SourceSpan,
) -> Result<()> {
    let Some(type_hint) = type_hint else {
        return Ok(());
    };
    let Some(disallowed_type) = class_constant_disallowed_type_name(type_hint) else {
        return Ok(());
    };
    Err(Diagnostic::new(
        format!("Class constant {class_name}::{constant_name} cannot have type {disallowed_type}"),
        Some(span),
    ))
}

fn class_constant_disallowed_type_name(type_hint: &TypeHint) -> Option<&'static str> {
    match type_hint {
        TypeHint::Callable => Some("callable"),
        TypeHint::Void => Some("void"),
        TypeHint::Never => Some("never"),
        TypeHint::Nullable(inner) => class_constant_disallowed_type_name(inner),
        TypeHint::Union(types) | TypeHint::Intersection(types) => {
            types.iter().find_map(class_constant_disallowed_type_name)
        }
        _ => None,
    }
}

fn class_constant_literal_type_name(value: &Expr) -> Option<&'static str> {
    match value {
        Expr::Null(_) => Some("null"),
        Expr::Array { .. } => Some("array"),
        Expr::Int(_, _) => Some("int"),
        Expr::Float(_, _) => Some("float"),
        Expr::String(_, _) => Some("string"),
        Expr::Bool(_, _) => Some("bool"),
        _ => None,
    }
}

fn class_constant_type_accepts_literal(type_hint: &TypeHint, value: &Expr) -> bool {
    if let Expr::Grouped { expr, .. } = value {
        return class_constant_type_accepts_literal(type_hint, expr);
    }
    match type_hint {
        TypeHint::Null => matches!(value, Expr::Null(_)),
        TypeHint::Array => matches!(value, Expr::Array { .. }),
        TypeHint::Int => matches!(value, Expr::Int(_, _)),
        TypeHint::Float => matches!(value, Expr::Float(_, _) | Expr::Int(_, _)),
        TypeHint::String => matches!(value, Expr::String(_, _)),
        TypeHint::Bool => matches!(value, Expr::Bool(_, _)),
        TypeHint::True => matches!(value, Expr::Bool(true, _)),
        TypeHint::False => matches!(value, Expr::Bool(false, _)),
        TypeHint::Mixed => true,
        TypeHint::Iterable => matches!(value, Expr::Array { .. }),
        TypeHint::Nullable(inner) => {
            matches!(value, Expr::Null(_)) || class_constant_type_accepts_literal(inner, value)
        }
        TypeHint::Union(types) => types
            .iter()
            .any(|member| class_constant_type_accepts_literal(member, value)),
        TypeHint::Callable
        | TypeHint::Object
        | TypeHint::Void
        | TypeHint::Never
        | TypeHint::Static
        | TypeHint::Intersection(_)
        | TypeHint::Class(_) => false,
    }
}

fn union_builtin_display_rank(member: &str) -> Option<usize> {
    match member {
        "object" => Some(0),
        "array" => Some(1),
        "string" => Some(2),
        "int" => Some(3),
        "float" => Some(4),
        "bool" => Some(5),
        "false" => Some(6),
        "true" => Some(7),
        "null" => Some(8),
        _ => None,
    }
}

fn type_hint_union_member_is_builtin_like(type_hint: &TypeHint) -> bool {
    !matches!(type_hint, TypeHint::Class(_) | TypeHint::Intersection(_))
}

fn type_hint_display_canonical(type_hint: &TypeHint) -> String {
    match type_hint {
        TypeHint::Union(types) => {
            let mut members = types
                .iter()
                .map(|member| {
                    let display = match member {
                        TypeHint::Intersection(_) => {
                            format!("({})", type_hint_display_canonical(member))
                        }
                        _ => type_hint_display_canonical(member),
                    };
                    (member, display)
                })
                .collect::<Vec<_>>();
            if members
                .iter()
                .all(|(_, display)| union_builtin_display_rank(display).is_some())
            {
                members.sort_by_key(|(_, display)| union_builtin_display_rank(display).unwrap());
            } else {
                members.sort_by_key(|(member, _)| type_hint_union_member_is_builtin_like(member));
            }
            members
                .into_iter()
                .map(|(_, display)| display)
                .collect::<Vec<_>>()
                .join("|")
        }
        TypeHint::Intersection(types) => types
            .iter()
            .map(type_hint_display_canonical)
            .collect::<Vec<_>>()
            .join("&"),
        TypeHint::Nullable(inner) => match inner.as_ref() {
            TypeHint::Iterable => "Traversable|array|null".to_string(),
            TypeHint::Union(_) | TypeHint::Intersection(_) => {
                format!("{}|null", type_hint_display_canonical(inner))
            }
            _ => format!("?{}", type_hint_display_canonical(inner)),
        },
        _ => type_hint_display(type_hint),
    }
}

fn type_hint_union_member_display(type_hint: &TypeHint) -> String {
    match type_hint {
        TypeHint::Intersection(_) => format!("({})", type_hint_display(type_hint)),
        _ => type_hint_display(type_hint),
    }
}

fn validate_override_attributes(classes: &[ClassDecl], traits: &[TraitDecl]) -> Result<()> {
    for class in classes {
        for method in &class.methods {
            if !method.has_override_attribute {
                continue;
            }
            if method_override_target_exists(class, method, classes, traits) {
                continue;
            }
            return Err(Diagnostic::new(
                format!(
                    "{}::{}() has #[\\Override] attribute, but no matching parent method exists",
                    class.name, method.name
                ),
                Some(method.span),
            ));
        }
        for property in &class.properties {
            if !property.has_override_attribute {
                continue;
            }
            if property_override_target_exists(class, &property.name, false, classes) {
                continue;
            }
            return Err(Diagnostic::new(
                format!(
                    "{}::${} has #[\\Override] attribute, but no matching parent property exists",
                    class.name, property.name
                ),
                Some(property.span),
            ));
        }
        for property in &class.properties {
            if let Some(span) = property.hook_get_override_span {
                if !property_hook_override_target_exists(class, &property.name, "get", classes) {
                    return Err(Diagnostic::new(
                        format!(
                            "{}::${}::get() has #[\\Override] attribute, but no matching parent method exists",
                            class.name, property.name
                        ),
                        Some(span),
                    ));
                }
            }
            if let Some(span) = property.hook_set_override_span {
                if !property_hook_override_target_exists(class, &property.name, "set", classes) {
                    return Err(Diagnostic::new(
                        format!(
                            "{}::${}::set() has #[\\Override] attribute, but no matching parent method exists",
                            class.name, property.name
                        ),
                        Some(span),
                    ));
                }
            }
        }
        for property in &class.static_properties {
            if !property.has_override_attribute {
                continue;
            }
            if property_override_target_exists(class, &property.name, true, classes) {
                continue;
            }
            return Err(Diagnostic::new(
                format!(
                    "{}::${} has #[\\Override] attribute, but no matching parent property exists",
                    class.name, property.name
                ),
                Some(property.span),
            ));
        }
    }
    Ok(())
}

fn method_override_target_exists(
    class: &ClassDecl,
    method: &MethodDecl,
    classes: &[ClassDecl],
    traits: &[TraitDecl],
) -> bool {
    parent_method_override_target_exists(class, method, classes)
        || class_interface_method_exists(class, &method.name, classes)
        || trait_abstract_method_exists(class, &method.name, traits)
}

fn parent_method_override_target_exists(
    class: &ClassDecl,
    method: &MethodDecl,
    classes: &[ClassDecl],
) -> bool {
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let Some(parent) = find_class(classes, name) else {
            break;
        };
        if parent.methods.iter().any(|candidate| {
            method_can_satisfy_override(candidate, &method.name)
                && (!method.name.eq_ignore_ascii_case("__construct") || candidate.is_abstract)
        }) {
            return true;
        }
        parent_name = parent.parent_name.as_deref();
    }
    false
}

fn method_can_satisfy_override(method: &MethodDecl, name: &str) -> bool {
    method.visibility != PropertyVisibility::Private && method.name.eq_ignore_ascii_case(name)
}

fn class_interface_method_exists(
    class: &ClassDecl,
    method_name: &str,
    classes: &[ClassDecl],
) -> bool {
    let mut current = Some(class);
    let mut seen_classes = HashSet::new();
    while let Some(candidate) = current {
        if !seen_classes.insert(candidate.name.to_ascii_lowercase()) {
            break;
        }
        let mut seen_interfaces = HashSet::new();
        if candidate.interfaces.iter().any(|interface_name| {
            interface_method_exists(interface_name, method_name, classes, &mut seen_interfaces)
        }) {
            return true;
        }
        current = candidate
            .parent_name
            .as_deref()
            .and_then(|name| find_class(classes, name));
    }
    false
}

fn interface_method_exists(
    interface_name: &str,
    method_name: &str,
    classes: &[ClassDecl],
    seen: &mut HashSet<String>,
) -> bool {
    let lookup_name = interface_name.trim_start_matches('\\').to_ascii_lowercase();
    if !seen.insert(lookup_name) {
        return false;
    }
    if modeled_builtin_interface_method_exists(interface_name, method_name) {
        return true;
    }
    let Some(interface) = find_class(classes, interface_name) else {
        return false;
    };
    if !interface.is_interface {
        return false;
    }
    interface
        .methods
        .iter()
        .any(|method| method.name.eq_ignore_ascii_case(method_name))
        || interface
            .interfaces
            .iter()
            .any(|parent_name| interface_method_exists(parent_name, method_name, classes, seen))
}

fn modeled_builtin_interface_method_exists(interface_name: &str, method_name: &str) -> bool {
    let interface_name = interface_name.trim_start_matches('\\').to_ascii_lowercase();
    let method_name = method_name.to_ascii_lowercase();
    matches!(
        (interface_name.as_str(), method_name.as_str()),
        ("arrayaccess", "offsetexists")
            | ("arrayaccess", "offsetget")
            | ("arrayaccess", "offsetset")
            | ("arrayaccess", "offsetunset")
            | ("iterator", "current")
            | ("iterator", "key")
            | ("iterator", "next")
            | ("iterator", "rewind")
            | ("iterator", "valid")
            | ("iteratoraggregate", "getiterator")
            | ("countable", "count")
            | ("outeriterator", "getinneriterator")
            | ("recursiveiterator", "getchildren")
            | ("recursiveiterator", "haschildren")
            | ("serializable", "serialize")
            | ("seekableiterator", "seek")
            | ("serializable", "unserialize")
            | ("sessionhandlerinterface", "open")
            | ("sessionhandlerinterface", "close")
            | ("sessionhandlerinterface", "read")
            | ("sessionhandlerinterface", "write")
            | ("sessionhandlerinterface", "destroy")
            | ("sessionhandlerinterface", "gc")
            | ("sessionupdatetimestamphandlerinterface", "validateid")
            | ("sessionupdatetimestamphandlerinterface", "updatetimestamp")
            | ("stringable", "__tostring")
    )
}

fn trait_abstract_method_exists(
    class: &ClassDecl,
    method_name: &str,
    traits: &[TraitDecl],
) -> bool {
    class.trait_uses.iter().any(|trait_use| {
        find_trait(traits, &trait_use.name).is_some_and(|trait_decl| {
            trait_decl
                .methods
                .iter()
                .any(|method| method.is_abstract && method.name.eq_ignore_ascii_case(method_name))
        })
    })
}

fn property_override_target_exists(
    class: &ClassDecl,
    property_name: &str,
    is_static: bool,
    classes: &[ClassDecl],
) -> bool {
    parent_property_override_target_exists(class, property_name, is_static, classes)
        || class_interface_property_exists(class, property_name, is_static, classes)
}

fn property_hook_override_target_exists(
    class: &ClassDecl,
    property_name: &str,
    hook_name: &str,
    classes: &[ClassDecl],
) -> bool {
    parent_property_hook_override_target_exists(class, property_name, hook_name, classes)
        || class_interface_property_hook_exists(class, property_name, hook_name, classes)
}

fn parent_property_hook_override_target_exists(
    class: &ClassDecl,
    property_name: &str,
    hook_name: &str,
    classes: &[ClassDecl],
) -> bool {
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let Some(parent) = find_class(classes, name) else {
            break;
        };
        if parent.properties.iter().any(|property| {
            property.visibility != PropertyVisibility::Private
                && property.name == property_name
                && property_satisfies_hook(property, hook_name, false)
        }) {
            return true;
        }
        parent_name = parent.parent_name.as_deref();
    }
    false
}

fn class_interface_property_hook_exists(
    class: &ClassDecl,
    property_name: &str,
    hook_name: &str,
    classes: &[ClassDecl],
) -> bool {
    let mut current = Some(class);
    let mut seen_classes = HashSet::new();
    while let Some(candidate) = current {
        if !seen_classes.insert(candidate.name.to_ascii_lowercase()) {
            break;
        }
        let mut seen_interfaces = HashSet::new();
        if candidate.interfaces.iter().any(|interface_name| {
            interface_property_hook_exists(
                interface_name,
                property_name,
                hook_name,
                classes,
                &mut seen_interfaces,
            )
        }) {
            return true;
        }
        current = candidate
            .parent_name
            .as_deref()
            .and_then(|name| find_class(classes, name));
    }
    false
}

fn interface_property_hook_exists(
    interface_name: &str,
    property_name: &str,
    hook_name: &str,
    classes: &[ClassDecl],
    seen: &mut HashSet<String>,
) -> bool {
    let lookup_name = interface_name.trim_start_matches('\\').to_ascii_lowercase();
    if !seen.insert(lookup_name) {
        return false;
    }
    let Some(interface) = find_class(classes, interface_name) else {
        return false;
    };
    if !interface.is_interface {
        return false;
    }
    interface.properties.iter().any(|property| {
        property.name == property_name && property_satisfies_hook(property, hook_name, false)
    }) || interface.interfaces.iter().any(|parent_name| {
        interface_property_hook_exists(parent_name, property_name, hook_name, classes, seen)
    })
}

fn parent_property_override_target_exists(
    class: &ClassDecl,
    property_name: &str,
    is_static: bool,
    classes: &[ClassDecl],
) -> bool {
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let Some(parent) = find_class(classes, name) else {
            break;
        };
        let has_property = if is_static {
            parent.static_properties.iter().any(|candidate| {
                candidate.visibility != PropertyVisibility::Private
                    && candidate.name == property_name
            })
        } else {
            parent.properties.iter().any(|candidate| {
                candidate.visibility != PropertyVisibility::Private
                    && candidate.name == property_name
            })
        };
        if has_property {
            return true;
        }
        parent_name = parent.parent_name.as_deref();
    }
    false
}

fn class_interface_property_exists(
    class: &ClassDecl,
    property_name: &str,
    is_static: bool,
    classes: &[ClassDecl],
) -> bool {
    let mut current = Some(class);
    let mut seen_classes = HashSet::new();
    while let Some(candidate) = current {
        if !seen_classes.insert(candidate.name.to_ascii_lowercase()) {
            break;
        }
        let mut seen_interfaces = HashSet::new();
        if candidate.interfaces.iter().any(|interface_name| {
            interface_property_exists(
                interface_name,
                property_name,
                is_static,
                classes,
                &mut seen_interfaces,
            )
        }) {
            return true;
        }
        current = candidate
            .parent_name
            .as_deref()
            .and_then(|name| find_class(classes, name));
    }
    false
}

fn interface_property_exists(
    interface_name: &str,
    property_name: &str,
    is_static: bool,
    classes: &[ClassDecl],
    seen: &mut HashSet<String>,
) -> bool {
    let lookup_name = interface_name.trim_start_matches('\\').to_ascii_lowercase();
    if !seen.insert(lookup_name) {
        return false;
    }
    let Some(interface) = find_class(classes, interface_name) else {
        return false;
    };
    if !interface.is_interface {
        return false;
    }
    let has_property = if is_static {
        interface
            .static_properties
            .iter()
            .any(|property| property.name == property_name)
    } else {
        interface
            .properties
            .iter()
            .any(|property| property.name == property_name)
    };
    has_property
        || interface.interfaces.iter().any(|parent_name| {
            interface_property_exists(parent_name, property_name, is_static, classes, seen)
        })
}

fn find_class<'a>(classes: &'a [ClassDecl], name: &str) -> Option<&'a ClassDecl> {
    classes
        .iter()
        .find(|class| class.name.eq_ignore_ascii_case(name))
}

fn find_trait<'a>(traits: &'a [TraitDecl], name: &str) -> Option<&'a TraitDecl> {
    traits
        .iter()
        .find(|trait_decl| trait_decl.name.eq_ignore_ascii_case(name))
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum AttributeTarget {
    Class,
    Function,
    Method,
    Parameter,
    Property,
    ClassConstant,
    Constant,
}

fn validate_builtin_attributes_for_target(
    attributes: &AttributeMetadata,
    target: AttributeTarget,
    span: SourceSpan,
) -> Result<()> {
    if attributes.first_class_callable_argument_count > 0 {
        return Err(Diagnostic::new(
            "Cannot create Closure as attribute argument",
            Some(span),
        ));
    }

    validate_builtin_attribute_repetition("Attribute", attributes.attribute_count, span)?;
    validate_builtin_attribute_repetition(
        "AllowDynamicProperties",
        attributes.allow_dynamic_properties_count,
        span,
    )?;
    validate_builtin_attribute_repetition(
        "DelayedTargetValidation",
        attributes.delayed_target_validation_count,
        span,
    )?;
    validate_builtin_attribute_repetition("Deprecated", attributes.deprecated_count, span)?;
    validate_builtin_attribute_repetition("NoDiscard", attributes.no_discard_count, span)?;
    validate_builtin_attribute_repetition("Override", attributes.override_count, span)?;
    validate_builtin_attribute_repetition(
        "ReturnTypeWillChange",
        attributes.return_type_will_change_count,
        span,
    )?;

    if attributes.delayed_target_validation_count > 0 {
        return Ok(());
    }

    validate_builtin_attribute_target(
        "Attribute",
        attributes.attribute_count,
        target,
        &[AttributeTarget::Class],
        "class",
        span,
    )?;
    validate_builtin_attribute_target(
        "AllowDynamicProperties",
        attributes.allow_dynamic_properties_count,
        target,
        &[AttributeTarget::Class],
        "class",
        span,
    )?;
    validate_builtin_attribute_target(
        "Deprecated",
        attributes.deprecated_count,
        target,
        &[
            AttributeTarget::Class,
            AttributeTarget::Function,
            AttributeTarget::Method,
            AttributeTarget::ClassConstant,
            AttributeTarget::Constant,
        ],
        "class, function, method, class constant, constant",
        span,
    )?;
    validate_builtin_attribute_target(
        "NoDiscard",
        attributes.no_discard_count,
        target,
        &[AttributeTarget::Function, AttributeTarget::Method],
        "function, method",
        span,
    )?;
    validate_builtin_attribute_target(
        "ReturnTypeWillChange",
        attributes.return_type_will_change_count,
        target,
        &[AttributeTarget::Method],
        "method",
        span,
    )?;
    Ok(())
}

fn validate_builtin_attribute_repetition(name: &str, count: u16, span: SourceSpan) -> Result<()> {
    if count > 1 {
        return Err(Diagnostic::new(
            format!("Attribute \"{name}\" must not be repeated"),
            Some(span),
        ));
    }
    Ok(())
}

fn validate_builtin_attribute_target(
    name: &str,
    count: u16,
    target: AttributeTarget,
    allowed_targets: &[AttributeTarget],
    allowed_display: &str,
    span: SourceSpan,
) -> Result<()> {
    if count == 0 || allowed_targets.contains(&target) {
        return Ok(());
    }
    Err(Diagnostic::new(
        format!(
            "Attribute \"{name}\" cannot target {} (allowed targets: {allowed_display})",
            attribute_target_name(target)
        ),
        Some(span),
    ))
}

fn attribute_target_name(target: AttributeTarget) -> &'static str {
    match target {
        AttributeTarget::Class => "class",
        AttributeTarget::Function => "function",
        AttributeTarget::Method => "method",
        AttributeTarget::Parameter => "parameter",
        AttributeTarget::Property => "property",
        AttributeTarget::ClassConstant => "class constant",
        AttributeTarget::Constant => "constant",
    }
}

fn attribute_delays_target_validation(attributes: &AttributeMetadata) -> bool {
    attributes.delayed_target_validation_count > 0
}

fn validate_builtin_attribute_targets(
    classes: &[ClassDecl],
    traits: &[TraitDecl],
    functions: &[FunctionDecl],
) -> Result<()> {
    for function in functions {
        validate_builtin_attributes_for_target(
            &function.attributes,
            AttributeTarget::Function,
            function.span,
        )?;
        for parameter in &function.parameters {
            validate_builtin_attributes_for_target(
                &parameter.attributes,
                AttributeTarget::Parameter,
                parameter.span,
            )?;
        }
        if function.attributes.has_attribute
            && !attribute_delays_target_validation(&function.attributes)
        {
            return Err(Diagnostic::new(
                "Attribute \"Attribute\" cannot target function (allowed targets: class)",
                Some(function.span),
            ));
        }
        if !attribute_delays_target_validation(&function.attributes) {
            validate_no_discard_function_target(
                function.attributes.no_discard_message.is_some(),
                function.return_type.as_ref(),
                &format!("Function {}", function.name),
                function.span,
            )?;
        }
    }
    for class in classes {
        validate_builtin_attributes_for_target(
            &class.attributes,
            AttributeTarget::Class,
            class.span,
        )?;
        if class.attributes.has_attribute && !attribute_delays_target_validation(&class.attributes)
        {
            if class.is_enum {
                return Err(Diagnostic::new(
                    format!("Cannot apply #[\\Attribute] to enum {}", class.name),
                    Some(class.span),
                ));
            }
            if class.is_interface {
                return Err(Diagnostic::new(
                    format!("Cannot apply #[\\Attribute] to interface {}", class.name),
                    Some(class.span),
                ));
            }
            if class.is_abstract {
                return Err(Diagnostic::new(
                    format!(
                        "Cannot apply #[\\Attribute] to abstract class {}",
                        class.name
                    ),
                    Some(class.span),
                ));
            }
        }
        if class.attributes.has_allow_dynamic_properties
            && !attribute_delays_target_validation(&class.attributes)
        {
            if class.is_enum {
                return Err(Diagnostic::new(
                    format!(
                        "Cannot apply #[\\AllowDynamicProperties] to enum {}",
                        class.name
                    ),
                    Some(class.span),
                ));
            }
            if class.is_interface {
                return Err(Diagnostic::new(
                    format!(
                        "Cannot apply #[\\AllowDynamicProperties] to interface {}",
                        class.name
                    ),
                    Some(class.span),
                ));
            }
            if class.is_readonly {
                return Err(Diagnostic::new(
                    format!(
                        "Cannot apply #[\\AllowDynamicProperties] to readonly class {}",
                        class.name
                    ),
                    Some(class.span),
                ));
            }
        }
        if class.attributes.deprecated_message.is_some()
            && class.is_interface
            && !attribute_delays_target_validation(&class.attributes)
        {
            return Err(Diagnostic::new(
                format!("Cannot apply #[\\Deprecated] to interface {}", class.name),
                Some(class.span),
            ));
        }
        if class.attributes.deprecated_message.is_some()
            && class.is_enum
            && !attribute_delays_target_validation(&class.attributes)
        {
            return Err(Diagnostic::new(
                format!("Cannot apply #[\\Deprecated] to enum {}", class.name),
                Some(class.span),
            ));
        }
        if class.attributes.deprecated_message.is_some()
            && !class.is_interface
            && !class.is_enum
            && !attribute_delays_target_validation(&class.attributes)
        {
            return Err(Diagnostic::new(
                format!("Cannot apply #[\\Deprecated] to class {}", class.name),
                Some(class.span),
            ));
        }
        for constant in &class.constants {
            validate_builtin_attributes_for_target(
                &constant.attributes,
                AttributeTarget::ClassConstant,
                constant.span,
            )?;
        }
        for method in &class.methods {
            validate_builtin_attributes_for_target(
                &method.attributes,
                AttributeTarget::Method,
                method.span,
            )?;
            for parameter in &method.parameters {
                validate_builtin_attributes_for_target(
                    &parameter.attributes,
                    AttributeTarget::Parameter,
                    parameter.span,
                )?;
            }
            if method.attributes.has_attribute
                && !attribute_delays_target_validation(&method.attributes)
            {
                return Err(Diagnostic::new(
                    "Attribute \"Attribute\" cannot target method (allowed targets: class)",
                    Some(method.span),
                ));
            }
            if method.attributes.no_discard_message.is_some()
                && (method.name.eq_ignore_ascii_case("__construct")
                    || method.name.eq_ignore_ascii_case("__clone"))
                && !attribute_delays_target_validation(&method.attributes)
            {
                return Err(Diagnostic::new(
                    format!(
                        "Method {}::{} cannot be #[\\NoDiscard]",
                        class.name, method.name
                    ),
                    Some(method.span),
                ));
            }
            if !attribute_delays_target_validation(&method.attributes) {
                validate_no_discard_function_target(
                    method.attributes.no_discard_message.is_some(),
                    method.return_type.as_ref(),
                    &format!("Method {}::{}", class.name, method.name),
                    method.span,
                )?;
            }
        }
    }
    for trait_decl in traits {
        validate_builtin_attributes_for_target(
            &trait_decl.attributes,
            AttributeTarget::Class,
            trait_decl.span,
        )?;
        if trait_decl.attributes.has_attribute
            && !attribute_delays_target_validation(&trait_decl.attributes)
        {
            return Err(Diagnostic::new(
                format!("Cannot apply #[\\Attribute] to trait {}", trait_decl.name),
                Some(trait_decl.span),
            ));
        }
        if trait_decl.attributes.has_allow_dynamic_properties
            && !attribute_delays_target_validation(&trait_decl.attributes)
        {
            return Err(Diagnostic::new(
                format!(
                    "Cannot apply #[\\AllowDynamicProperties] to trait {}",
                    trait_decl.name
                ),
                Some(trait_decl.span),
            ));
        }
        for constant in &trait_decl.constants {
            validate_builtin_attributes_for_target(
                &constant.attributes,
                AttributeTarget::ClassConstant,
                constant.span,
            )?;
        }
        for method in &trait_decl.methods {
            validate_builtin_attributes_for_target(
                &method.attributes,
                AttributeTarget::Method,
                method.span,
            )?;
            for parameter in &method.parameters {
                validate_builtin_attributes_for_target(
                    &parameter.attributes,
                    AttributeTarget::Parameter,
                    parameter.span,
                )?;
            }
        }
    }
    Ok(())
}

fn validate_no_discard_function_target(
    has_no_discard: bool,
    return_type: Option<&TypeHint>,
    _display_name: &str,
    span: SourceSpan,
) -> Result<()> {
    if !has_no_discard {
        return Ok(());
    }
    match return_type {
        Some(TypeHint::Void) => Err(Diagnostic::new(
            "A void function does not return a value, but #[\\NoDiscard] requires a return value",
            Some(span),
        )),
        Some(TypeHint::Never) => Err(Diagnostic::new(
            "A never returning function does not return a value, but #[\\NoDiscard] requires a return value",
            Some(span),
        )),
        _ => Ok(()),
    }
}

fn validate_abstract_methods(classes: &[ClassDecl]) -> Result<()> {
    for class in classes {
        if class.is_enum {
            if let Some(method) = class.methods.iter().find(|method| method.is_abstract) {
                return Err(Diagnostic::new(
                    format!(
                        "Enum method {}::{}() must not be abstract",
                        class.name, method.name
                    ),
                    Some(method.span),
                ));
            }
        }
        let private_methods = unsatisfied_private_trait_abstract_methods(class);
        if !private_methods.is_empty() {
            return Err(private_abstract_methods_diagnostic(
                &class.name,
                &private_methods,
                class.span,
            ));
        }
        if class.is_anonymous {
            continue;
        }
        if class.is_abstract {
            continue;
        }
        let own_property_hooks = own_unsatisfied_abstract_property_hooks(class);
        if !own_property_hooks.is_empty() {
            return Err(abstract_property_hooks_diagnostic(
                &class.name,
                &own_property_hooks,
                class.span,
            ));
        }
        if let Some(method) = class
            .methods
            .iter()
            .find(|method| method.is_abstract && method.trait_name.is_none())
        {
            return Err(Diagnostic::new(
                format!(
                    "Class {} declares abstract method {}() and must therefore be declared abstract",
                    class.name, method.name
                ),
                Some(class.span),
            ));
        }
        let methods = unsatisfied_trait_abstract_methods(class, classes);
        if !methods.is_empty() {
            return Err(abstract_methods_diagnostic(
                &class.name,
                class.is_enum,
                &methods,
                class.span,
            ));
        }
        let property_hooks = inherited_unsatisfied_abstract_property_hooks(class, classes);
        if !property_hooks.is_empty() {
            return Err(abstract_property_hooks_diagnostic(
                &class.name,
                &property_hooks,
                class.span,
            ));
        }
    }
    Ok(())
}

#[derive(Clone)]
struct RequiredAbstractMethod {
    class_name: String,
    method_name: String,
}

fn unsatisfied_trait_abstract_methods(
    class: &ClassDecl,
    classes: &[ClassDecl],
) -> Vec<RequiredAbstractMethod> {
    let mut methods = Vec::new();
    let mut seen = HashSet::new();
    for method in &class.methods {
        if !method.is_abstract || method.trait_name.is_none() {
            continue;
        }
        if method.visibility != PropertyVisibility::Private
            && method
                .trait_method_name
                .as_deref()
                .is_some_and(|trait_method| method.name.eq_ignore_ascii_case(trait_method))
        {
            continue;
        }
        if trait_abstract_method_has_concrete_implementation(class, method, classes) {
            continue;
        }
        let class_name = class.name.clone();
        let method_name = method.name.clone();
        if seen.insert((class_name.clone(), method_name.to_ascii_lowercase())) {
            methods.push(RequiredAbstractMethod {
                class_name,
                method_name,
            });
        }
    }
    methods
}

fn unsatisfied_private_trait_abstract_methods(class: &ClassDecl) -> Vec<RequiredAbstractMethod> {
    let mut methods = Vec::new();
    let mut seen = HashSet::new();
    for method in &class.methods {
        if !method.is_abstract
            || method.trait_name.is_none()
            || method.visibility != PropertyVisibility::Private
        {
            continue;
        }
        if class.methods.iter().any(|candidate| {
            !candidate.is_abstract
                && candidate.visibility == PropertyVisibility::Private
                && candidate.name.eq_ignore_ascii_case(&method.name)
        }) {
            continue;
        }
        let class_name = class.name.clone();
        let method_name = method.name.clone();
        if seen.insert((class_name.clone(), method_name.to_ascii_lowercase())) {
            methods.push(RequiredAbstractMethod {
                class_name,
                method_name,
            });
        }
    }
    methods
}

fn trait_abstract_method_has_concrete_implementation(
    class: &ClassDecl,
    abstract_method: &MethodDecl,
    classes: &[ClassDecl],
) -> bool {
    if class.methods.iter().any(|method| {
        !method.is_abstract && method.name.eq_ignore_ascii_case(&abstract_method.name)
    }) {
        return true;
    }
    find_visible_parent_method(class, &abstract_method.name, classes)
        .is_some_and(|(_, method)| !method.is_abstract)
}

fn abstract_methods_diagnostic(
    class_name: &str,
    is_enum: bool,
    methods: &[RequiredAbstractMethod],
    span: SourceSpan,
) -> Diagnostic {
    let count = methods.len();
    let remaining = methods
        .iter()
        .map(|method| format!("{}::{}", method.class_name, method.method_name))
        .collect::<Vec<_>>()
        .join(", ");
    if is_enum {
        return Diagnostic::new(
            format!(
                "Enum {class_name} must implement {count} abstract method{} ({remaining})",
                if count == 1 { "" } else { "s" }
            ),
            Some(span),
        );
    }
    Diagnostic::new(
        format!(
            "Class {class_name} contains {count} abstract method{} and must therefore be declared abstract or implement the remaining method{} ({remaining})",
            if count == 1 { "" } else { "s" },
            if count == 1 { "" } else { "s" }
        ),
        Some(span),
    )
}

fn private_abstract_methods_diagnostic(
    class_name: &str,
    methods: &[RequiredAbstractMethod],
    span: SourceSpan,
) -> Diagnostic {
    let count = methods.len();
    let remaining = methods
        .iter()
        .map(|method| format!("{}::{}", method.class_name, method.method_name))
        .collect::<Vec<_>>()
        .join(", ");
    Diagnostic::new(
        format!(
            "Class {class_name} must implement {count} abstract method{} ({remaining})",
            if count == 1 { "" } else { "s" }
        ),
        Some(span),
    )
}

#[derive(Clone)]
struct RequiredAbstractPropertyHook {
    declaring_class: String,
    property_name: String,
    hook_name: &'static str,
    returns_by_ref: bool,
}

fn abstract_property_hooks_diagnostic(
    class_name: &str,
    hooks: &[RequiredAbstractPropertyHook],
    span: SourceSpan,
) -> Diagnostic {
    let count = hooks.len();
    let remaining = hooks
        .iter()
        .map(|hook| {
            format!(
                "{}::${}::{}",
                hook.declaring_class, hook.property_name, hook.hook_name
            )
        })
        .collect::<Vec<_>>()
        .join(", ");
    Diagnostic::new(
        format!(
            "Class {class_name} contains {count} abstract method{} and must therefore be declared abstract or implement the remaining method{} ({remaining})",
            if count == 1 { "" } else { "s" },
            if count == 1 { "" } else { "s" },
        ),
        Some(span),
    )
}

fn own_unsatisfied_abstract_property_hooks(class: &ClassDecl) -> Vec<RequiredAbstractPropertyHook> {
    class
        .properties
        .iter()
        .flat_map(|property| abstract_property_hooks_for(&class.name, property))
        .collect()
}

fn abstract_property_hooks_for(
    declaring_class: &str,
    property: &PropertyDecl,
) -> Vec<RequiredAbstractPropertyHook> {
    let mut hooks = Vec::new();
    if property.hook_get_is_abstract {
        hooks.push(RequiredAbstractPropertyHook {
            declaring_class: declaring_class.to_string(),
            property_name: property.name.clone(),
            hook_name: "get",
            returns_by_ref: property.hook_get_returns_by_ref,
        });
    }
    if property.hook_set_is_abstract {
        hooks.push(RequiredAbstractPropertyHook {
            declaring_class: declaring_class.to_string(),
            property_name: property.name.clone(),
            hook_name: "set",
            returns_by_ref: false,
        });
    }
    hooks
}

fn inherited_unsatisfied_abstract_property_hooks(
    class: &ClassDecl,
    classes: &[ClassDecl],
) -> Vec<RequiredAbstractPropertyHook> {
    let mut requirements = Vec::new();
    collect_parent_abstract_property_hooks(class, classes, &mut requirements);
    collect_interface_abstract_property_hooks(class, classes, &mut requirements);
    requirements
        .into_iter()
        .filter(|required| !class_satisfies_property_hook(class, required, classes))
        .collect()
}

fn collect_parent_abstract_property_hooks(
    class: &ClassDecl,
    classes: &[ClassDecl],
    requirements: &mut Vec<RequiredAbstractPropertyHook>,
) {
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let Some(parent) = find_class(classes, name) else {
            break;
        };
        for property in &parent.properties {
            requirements.extend(abstract_property_hooks_for(&parent.name, property));
        }
        parent_name = parent.parent_name.as_deref();
    }
}

fn collect_interface_abstract_property_hooks(
    class: &ClassDecl,
    classes: &[ClassDecl],
    requirements: &mut Vec<RequiredAbstractPropertyHook>,
) {
    let mut current = Some(class);
    let mut seen_classes = HashSet::new();
    while let Some(candidate) = current {
        if !seen_classes.insert(candidate.name.to_ascii_lowercase()) {
            break;
        }
        let mut seen_interfaces = HashSet::new();
        for interface_name in &candidate.interfaces {
            collect_interface_property_hooks(
                interface_name,
                classes,
                &mut seen_interfaces,
                requirements,
            );
        }
        current = candidate
            .parent_name
            .as_deref()
            .and_then(|name| find_class(classes, name));
    }
}

fn collect_interface_property_hooks(
    interface_name: &str,
    classes: &[ClassDecl],
    seen: &mut HashSet<String>,
    requirements: &mut Vec<RequiredAbstractPropertyHook>,
) {
    let lookup_name = interface_name.trim_start_matches('\\').to_ascii_lowercase();
    if !seen.insert(lookup_name) {
        return;
    }
    let Some(interface) = find_class(classes, interface_name) else {
        return;
    };
    if !interface.is_interface {
        return;
    }
    for property in &interface.properties {
        requirements.extend(abstract_property_hooks_for(&interface.name, property));
    }
    for parent_interface in &interface.interfaces {
        collect_interface_property_hooks(parent_interface, classes, seen, requirements);
    }
}

fn validate_property_hook_set_parameter_types(classes: &[ClassDecl]) -> Result<()> {
    let runtime_class_aliases = HashMap::new();
    for class in classes {
        for property in &class.properties {
            if !property.has_hooks
                || !property.hook_has_set
                || !property.hook_set_parameter_is_explicit
            {
                continue;
            }
            let parameter_type = property.hook_set_parameter_type.as_ref();
            let property_type = property
                .type_hint
                .as_ref()
                .and_then(|type_hint| type_hint.semantic_type.as_ref());
            let compatible = match (property_type, parameter_type) {
                (Some(property_type), Some(parameter_type)) => type_hint_is_subtype(
                    property_type,
                    parameter_type,
                    classes,
                    &runtime_class_aliases,
                ),
                (None, None) => true,
                _ => false,
            };
            if compatible {
                continue;
            }
            if let (Some(property_type), Some(parameter_type)) = (property_type, parameter_type) {
                if unresolved_compatibility_class(property_type, parameter_type, classes).is_some()
                    && unresolved_class_can_affect_subtype_check(property_type, parameter_type)
                {
                    continue;
                }
            }
            let parameter_name = property
                .hook_set_parameter_name
                .as_deref()
                .unwrap_or("value");
            return Err(Diagnostic::new(
                format!(
                    "Type of parameter ${parameter_name} of hook {}::${}::set must be compatible with property type",
                    class.name, property.name
                ),
                property
                    .hook_set_parameter_span
                    .or(property.hook_set_span)
                    .or(Some(property.span)),
            ));
        }
    }
    Ok(())
}

fn validate_property_hook_signature_compatibility(classes: &[ClassDecl]) -> Result<()> {
    for class in classes {
        for property in &class.properties {
            if property.hook_get_returns_by_ref
                && property.hook_has_set
                && property_hook_is_backed(class, property, classes)
            {
                return Err(Diagnostic::new(
                    format!(
                        "Get hook of backed property {}::{} with set hook may not return by reference",
                        class.name, property.name
                    ),
                    property.hook_get_span.or(Some(property.span)),
                ));
            }

            if let Some((parent_class, parent_property)) =
                visible_parent_property(class, &property.name, classes)
            {
                if property.hook_has_get && parent_property.hook_get_is_final {
                    return Err(Diagnostic::new(
                        format!(
                            "Cannot override final property hook {}::${}::get()",
                            parent_class.name, parent_property.name
                        ),
                        property.hook_get_span.or(Some(property.span)),
                    ));
                }
                if property.hook_has_set && parent_property.hook_set_is_final {
                    return Err(Diagnostic::new(
                        format!(
                            "Cannot override final property hook {}::${}::set()",
                            parent_class.name, parent_property.name
                        ),
                        property.hook_set_span.or(Some(property.span)),
                    ));
                }
            }
        }

        let mut requirements = Vec::new();
        collect_parent_abstract_property_hooks(class, classes, &mut requirements);
        collect_interface_abstract_property_hooks(class, classes, &mut requirements);
        for required in requirements {
            if required.hook_name != "get" || !required.returns_by_ref {
                continue;
            }
            let Some((actual_class, actual_property)) =
                visible_property_in_class_chain(class, &required.property_name, classes)
            else {
                continue;
            };
            if !actual_property.has_hooks
                || (actual_property.hook_has_get
                    && !actual_property.hook_get_is_abstract
                    && actual_property.hook_get_returns_by_ref)
            {
                continue;
            }
            return Err(Diagnostic::new(
                format!(
                    "Declaration of {}::{}::get() must be compatible with &{}::{}::get()",
                    actual_class.name,
                    property_hook_display_name(&actual_property.name),
                    required.declaring_class,
                    property_hook_display_name(&required.property_name)
                ),
                actual_property.hook_get_span.or(Some(actual_property.span)),
            ));
        }
    }
    Ok(())
}

fn property_hook_is_backed(
    class: &ClassDecl,
    property: &PropertyDecl,
    classes: &[ClassDecl],
) -> bool {
    !property.is_virtual
        || property.value.is_some()
        || visible_parent_property(class, &property.name, classes).is_some()
}

fn visible_parent_property<'a>(
    class: &'a ClassDecl,
    property_name: &str,
    classes: &'a [ClassDecl],
) -> Option<(&'a ClassDecl, &'a PropertyDecl)> {
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let Some(parent) = find_class(classes, name) else {
            break;
        };
        if let Some(property) = parent.properties.iter().find(|property| {
            property.visibility != PropertyVisibility::Private && property.name == property_name
        }) {
            return Some((parent, property));
        }
        parent_name = parent.parent_name.as_deref();
    }
    None
}

fn visible_property_in_class_chain<'a>(
    class: &'a ClassDecl,
    property_name: &str,
    classes: &'a [ClassDecl],
) -> Option<(&'a ClassDecl, &'a PropertyDecl)> {
    let mut current = Some(class);
    let mut seen = HashSet::new();
    while let Some(candidate) = current {
        if !seen.insert(candidate.name.to_ascii_lowercase()) {
            break;
        }
        if let Some(property) = candidate
            .properties
            .iter()
            .find(|property| property.name == property_name)
        {
            if property.visibility != PropertyVisibility::Private
                || candidate.name.eq_ignore_ascii_case(&class.name)
            {
                return Some((candidate, property));
            }
            return None;
        }
        current = candidate
            .parent_name
            .as_deref()
            .and_then(|name| find_class(classes, name));
    }
    None
}

fn property_hook_display_name(property_name: &str) -> String {
    format!("${property_name}")
}

fn class_satisfies_property_hook(
    class: &ClassDecl,
    required: &RequiredAbstractPropertyHook,
    classes: &[ClassDecl],
) -> bool {
    let mut current = Some(class);
    let mut seen = HashSet::new();
    while let Some(candidate) = current {
        if !seen.insert(candidate.name.to_ascii_lowercase()) {
            break;
        }
        if let Some(property) = candidate
            .properties
            .iter()
            .find(|property| property.name == required.property_name)
        {
            if property.visibility == PropertyVisibility::Private
                && !candidate.name.eq_ignore_ascii_case(&class.name)
            {
                return false;
            }
            return property_satisfies_hook(property, required.hook_name, required.returns_by_ref);
        }
        current = candidate
            .parent_name
            .as_deref()
            .and_then(|name| find_class(classes, name));
    }
    false
}

fn property_satisfies_hook(
    property: &PropertyDecl,
    hook_name: &str,
    requires_by_ref: bool,
) -> bool {
    if !property.has_hooks {
        return hook_name == "get" || (hook_name == "set" && !property.is_readonly);
    }
    match hook_name {
        "get" => {
            if property.hook_has_get {
                return !property.hook_get_is_abstract
                    && (!requires_by_ref || property.hook_get_returns_by_ref);
            }
            !property.is_virtual && !requires_by_ref
        }
        "set" => {
            if property.hook_has_set {
                return !property.hook_set_is_abstract;
            }
            !property.is_virtual && !property.is_readonly
        }
        _ => false,
    }
}

fn validate_final_class_inheritance(classes: &[ClassDecl]) -> Result<()> {
    for class in classes {
        if class.is_interface {
            continue;
        }
        let Some(parent_name) = &class.parent_name else {
            continue;
        };
        if let Some(final_name) = modeled_builtin_final_class_name(parent_name) {
            return Err(Diagnostic::new(
                format!(
                    "Class {} cannot extend final class {final_name}",
                    class.name
                ),
                Some(class.span),
            ));
        }
        let Some(parent) = classes
            .iter()
            .find(|candidate| candidate.name.eq_ignore_ascii_case(parent_name))
        else {
            continue;
        };
        if parent.is_enum {
            return Err(Diagnostic::new(
                format!("Class {} cannot extend enum {parent_name}", class.name),
                Some(class.span),
            ));
        }
        if parent.is_final {
            return Err(Diagnostic::new(
                format!(
                    "Class {} cannot extend final class {parent_name}",
                    class.name
                ),
                Some(class.span),
            ));
        }
    }
    Ok(())
}

fn modeled_builtin_final_class_name(name: &str) -> Option<&'static str> {
    match name.trim_start_matches('\\').to_ascii_lowercase().as_str() {
        "generator" => Some("Generator"),
        "bcmath\\number" => Some("BcMath\\Number"),
        "weakmap" => Some("WeakMap"),
        "weakreference" => Some("WeakReference"),
        _ => None,
    }
}

fn validate_readonly_class_inheritance(classes: &[ClassDecl]) -> Result<()> {
    for class in classes {
        if class.is_interface {
            continue;
        }
        let Some(parent_name) = &class.parent_name else {
            continue;
        };
        let parent = classes
            .iter()
            .find(|candidate| candidate.name.eq_ignore_ascii_case(parent_name));
        if !class.is_readonly {
            if let Some(parent) = parent {
                if parent.is_readonly {
                    return Err(Diagnostic::new(
                        format!(
                            "Non-readonly class {} cannot extend readonly class {parent_name}",
                            class.name
                        ),
                        Some(class.span),
                    ));
                }
            }
            continue;
        }
        if parent_name.eq_ignore_ascii_case("stdClass")
            || is_modeled_builtin_exception_class_name(parent_name)
        {
            return Err(Diagnostic::new(
                format!(
                    "Readonly class {} cannot extend non-readonly class {parent_name}",
                    class.name
                ),
                Some(class.span),
            ));
        }
        let Some(parent) = parent else {
            continue;
        };
        if !parent.is_readonly {
            return Err(Diagnostic::new(
                format!(
                    "Readonly class {} cannot extend non-readonly class {parent_name}",
                    class.name
                ),
                Some(class.span),
            ));
        }
    }
    Ok(())
}

fn validate_property_interface_set_visibility(classes: &[ClassDecl]) -> Result<()> {
    let runtime_class_aliases = HashMap::new();
    for class in classes {
        if class.is_interface {
            continue;
        }
        for property in &class.properties {
            let mut requirements = Vec::new();
            collect_class_interface_set_visibility_properties(
                class,
                &property.name,
                classes,
                &mut requirements,
            );
            for (interface, interface_property) in requirements {
                if !interface_property.has_hooks || !interface_property.hook_has_set {
                    continue;
                }
                if interface_property.set_visibility == interface_property.visibility
                    && property.set_visibility != property.visibility
                {
                    return Err(Diagnostic::new(
                        format!(
                            "Set access level of {}::${} must be omitted (as in class {})",
                            class.name, property.name, interface.name
                        ),
                        Some(property.span),
                    ));
                }
                if visibility_rank(property.set_visibility)
                    > visibility_rank(interface_property.set_visibility)
                {
                    return Err(Diagnostic::new(
                        format!(
                            "Set access level of {}::${} must be {}(set) (as in class {}) or weaker",
                            class.name,
                            property.name,
                            property_visibility_name(interface_property.set_visibility),
                            interface.name
                        ),
                        Some(property.span),
                    ));
                }
                let class_set_type = property_effective_set_parameter_type(property);
                let interface_set_type = property_effective_set_parameter_type(interface_property);
                if !type_hint_is_subtype(
                    &interface_set_type,
                    &class_set_type,
                    classes,
                    &runtime_class_aliases,
                ) {
                    return Err(Diagnostic::new(
                        format!(
                            "Set type of {}::${} must be supertype of {} (as in interface {})",
                            class.name,
                            property.name,
                            type_hint_display_canonical(&interface_set_type),
                            interface.name
                        ),
                        Some(property.span),
                    ));
                }
            }
        }
    }
    Ok(())
}

fn collect_class_interface_set_visibility_properties<'a>(
    class: &'a ClassDecl,
    property_name: &str,
    classes: &'a [ClassDecl],
    requirements: &mut Vec<(&'a ClassDecl, &'a PropertyDecl)>,
) {
    let mut current = Some(class);
    let mut seen_classes = HashSet::new();
    while let Some(candidate) = current {
        if !seen_classes.insert(candidate.name.to_ascii_lowercase()) {
            break;
        }
        let mut seen_interfaces = HashSet::new();
        for interface_name in &candidate.interfaces {
            collect_interface_set_visibility_properties(
                interface_name,
                property_name,
                classes,
                &mut seen_interfaces,
                requirements,
            );
        }
        current = candidate
            .parent_name
            .as_deref()
            .and_then(|name| find_class(classes, name));
    }
}

fn collect_interface_set_visibility_properties<'a>(
    interface_name: &str,
    property_name: &str,
    classes: &'a [ClassDecl],
    seen: &mut HashSet<String>,
    requirements: &mut Vec<(&'a ClassDecl, &'a PropertyDecl)>,
) {
    let lookup_name = interface_name.trim_start_matches('\\').to_ascii_lowercase();
    if !seen.insert(lookup_name) {
        return;
    }
    let Some(interface) = find_class(classes, interface_name) else {
        return;
    };
    if !interface.is_interface {
        return;
    }
    if let Some(property) = interface
        .properties
        .iter()
        .find(|property| property.name == property_name)
    {
        requirements.push((interface, property));
    }
    for parent_interface in &interface.interfaces {
        collect_interface_set_visibility_properties(
            parent_interface,
            property_name,
            classes,
            seen,
            requirements,
        );
    }
}

fn validate_property_override_set_visibility(classes: &[ClassDecl]) -> Result<()> {
    for class in classes {
        let Some(parent_name) = &class.parent_name else {
            continue;
        };
        let Some(parent) = classes
            .iter()
            .find(|candidate| candidate.name.eq_ignore_ascii_case(parent_name))
        else {
            continue;
        };
        for property in &class.properties {
            let Some(parent_property) = parent
                .properties
                .iter()
                .find(|candidate| candidate.name == property.name)
            else {
                continue;
            };
            if parent_property.visibility == PropertyVisibility::Private {
                continue;
            }
            if visibility_rank(property.visibility) > visibility_rank(parent_property.visibility) {
                continue;
            }
            if parent_property.is_final
                || (parent_property.set_visibility == PropertyVisibility::Private
                    && parent_property.visibility != PropertyVisibility::Private)
            {
                return Err(Diagnostic::new(
                    format!(
                        "Cannot override final property {}::${}",
                        parent.name, parent_property.name
                    ),
                    Some(property.span),
                ));
            }
            if parent_property.is_readonly != property.is_readonly {
                let message = if parent_property.is_readonly {
                    format!(
                        "Cannot redeclare readonly property {}::${} as non-readonly {}::${}",
                        parent.name, parent_property.name, class.name, property.name
                    )
                } else {
                    format!(
                        "Cannot redeclare non-readonly property {}::${} as readonly {}::${}",
                        parent.name, parent_property.name, class.name, property.name
                    )
                };
                return Err(Diagnostic::new(message, Some(property.span)));
            }
            if parent_property.set_visibility == parent_property.visibility
                && !parent_property.has_hooks
                && property.set_visibility != property.visibility
                && !(parent_property.is_readonly && property.is_readonly)
            {
                return Err(Diagnostic::new(
                    format!(
                        "Set access level of {}::${} must be omitted (as in class {})",
                        class.name, property.name, parent.name
                    ),
                    Some(property.span),
                ));
            }
            if parent_property.has_hooks
                && parent_property.set_visibility == parent_property.visibility
                && property.set_visibility != property.visibility
            {
                continue;
            }
            if visibility_rank(property.set_visibility)
                <= visibility_rank(parent_property.set_visibility)
            {
                continue;
            }
            return Err(Diagnostic::new(
                format!(
                    "Set access level of {}::${} must be {}(set) (as in class {}) or weaker",
                    class.name,
                    property.name,
                    property_visibility_name(parent_property.set_visibility),
                    parent.name
                ),
                Some(property.span),
            ));
        }
    }
    Ok(())
}

fn validate_class_constant_overrides(classes: &[ClassDecl]) -> Result<()> {
    let runtime_class_aliases = HashMap::new();
    for class in classes {
        validate_inherited_class_constant_ambiguity(class, classes)?;

        for constant in &class.constants {
            if constant.is_final && constant.visibility == PropertyVisibility::Private {
                return Err(Diagnostic::new(
                    format!(
                        "Private constant {}::{} cannot be final as it is not visible to other classes",
                        class.name, constant.name
                    ),
                    Some(constant.span),
                ));
            }

            if let Some((interface, interface_constant)) =
                find_final_interface_constant_for_class(class, &constant.name, classes)
            {
                return Err(Diagnostic::new(
                    format!(
                        "{}::{} cannot override final constant {}::{}",
                        class.name, constant.name, interface.name, interface_constant.name
                    ),
                    Some(constant.span),
                ));
            }

            let mut parent_name = class.parent_name.as_deref();
            while let Some(name) = parent_name {
                let Some(parent) = classes
                    .iter()
                    .find(|candidate| candidate.name.eq_ignore_ascii_case(name))
                else {
                    break;
                };
                let Some(parent_constant) = parent
                    .constants
                    .iter()
                    .find(|candidate| candidate.name == constant.name)
                else {
                    parent_name = parent.parent_name.as_deref();
                    continue;
                };
                if parent_constant.visibility == PropertyVisibility::Private {
                    parent_name = parent.parent_name.as_deref();
                    continue;
                }
                if parent_constant.is_final {
                    return Err(Diagnostic::new(
                        format!(
                            "{}::{} cannot override final constant {}::{}",
                            class.name, constant.name, parent.name, parent_constant.name
                        ),
                        Some(class.span),
                    ));
                }
                if visibility_rank(constant.visibility)
                    > visibility_rank(parent_constant.visibility)
                {
                    let suffix = if parent_constant.visibility == PropertyVisibility::Public {
                        ""
                    } else {
                        " or weaker"
                    };
                    return Err(Diagnostic::new(
                        format!(
                            "Access level to {}::{} must be {} (as in class {}){}",
                            class.name,
                            constant.name,
                            property_visibility_name(parent_constant.visibility),
                            parent.name,
                            suffix
                        ),
                        Some(class.span),
                    ));
                }
                validate_class_constant_type_compatibility(
                    class,
                    constant,
                    parent,
                    parent_constant,
                    classes,
                    &runtime_class_aliases,
                )?;
                break;
            }

            let mut interface_constants = Vec::new();
            collect_class_hierarchy_interface_constants(class, classes, &mut interface_constants);
            for interface_constant in interface_constants {
                if interface_constant.constant.name != constant.name {
                    continue;
                }
                if constant.visibility != interface_constant.constant.visibility {
                    return Err(Diagnostic::new(
                        format!(
                            "Access level to {}::{} must be {} (as in interface {})",
                            class.name,
                            constant.name,
                            property_visibility_name(interface_constant.constant.visibility),
                            interface_constant.class.name
                        ),
                        Some(class.span),
                    ));
                }
                validate_class_constant_type_compatibility(
                    class,
                    constant,
                    interface_constant.class,
                    interface_constant.constant,
                    classes,
                    &runtime_class_aliases,
                )?;
            }
        }
    }
    Ok(())
}

fn validate_class_constant_type_compatibility(
    class: &ClassDecl,
    constant: &ClassConstantDecl,
    inherited_class: &ClassDecl,
    inherited_constant: &ClassConstantDecl,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> Result<()> {
    let Some(inherited_type) = inherited_constant.type_hint.as_ref() else {
        return Ok(());
    };
    let Some(type_hint) = constant.type_hint.as_ref() else {
        return Err(class_constant_type_compatibility_error(
            class,
            constant,
            inherited_class,
            inherited_constant,
            inherited_type,
        ));
    };
    if type_hint_is_subtype(type_hint, inherited_type, classes, runtime_class_aliases) {
        return Ok(());
    }
    Err(class_constant_type_compatibility_error(
        class,
        constant,
        inherited_class,
        inherited_constant,
        inherited_type,
    ))
}

fn class_constant_type_compatibility_error(
    class: &ClassDecl,
    constant: &ClassConstantDecl,
    inherited_class: &ClassDecl,
    inherited_constant: &ClassConstantDecl,
    inherited_type: &TypeHint,
) -> Diagnostic {
    Diagnostic::new(
        format!(
            "Type of {}::{} must be compatible with {}::{} of type {}",
            class.name,
            constant.name,
            inherited_class.name,
            inherited_constant.name,
            type_hint_display(inherited_type)
        ),
        Some(constant.span),
    )
}

#[derive(Clone, Copy)]
struct InheritedClassConstant<'a> {
    class: &'a ClassDecl,
    constant: &'a ClassConstantDecl,
}

fn validate_inherited_class_constant_ambiguity(
    class: &ClassDecl,
    classes: &[ClassDecl],
) -> Result<()> {
    let mut inherited = Vec::new();
    collect_visible_parent_class_constants(class, classes, &mut inherited);

    let mut seen_interfaces = HashSet::new();
    for interface_name in &class.interfaces {
        collect_interface_constants(
            interface_name,
            classes,
            &mut seen_interfaces,
            &mut inherited,
        );
    }

    let mut seen_constants: Vec<InheritedClassConstant<'_>> = Vec::new();
    for candidate in inherited {
        if class
            .constants
            .iter()
            .any(|constant| constant.name == candidate.constant.name)
        {
            continue;
        }
        if let Some(first) = seen_constants
            .iter()
            .find(|first| first.constant.name == candidate.constant.name)
        {
            if first.class.name.eq_ignore_ascii_case(&candidate.class.name) {
                continue;
            }
            return Err(Diagnostic::new(
                format!(
                    "{} {} inherits both {}::{} and {}::{}, which is ambiguous",
                    class_constant_owner_kind(class),
                    class.name,
                    first.class.name,
                    first.constant.name,
                    candidate.class.name,
                    candidate.constant.name
                ),
                Some(class.span),
            ));
        }
        seen_constants.push(candidate);
    }

    Ok(())
}

fn class_constant_owner_kind(class: &ClassDecl) -> &'static str {
    if class.is_enum {
        "Enum"
    } else if class.is_interface {
        "Interface"
    } else {
        "Class"
    }
}

fn collect_visible_parent_class_constants<'a>(
    class: &'a ClassDecl,
    classes: &'a [ClassDecl],
    constants: &mut Vec<InheritedClassConstant<'a>>,
) {
    let mut seen_names = HashSet::new();
    let mut parent_name = class.parent_name.as_deref();
    while let Some(name) = parent_name {
        let Some(parent) = find_class(classes, name) else {
            break;
        };
        for constant in &parent.constants {
            if seen_names.contains(&constant.name) {
                continue;
            }
            if constant.visibility != PropertyVisibility::Private {
                constants.push(InheritedClassConstant {
                    class: parent,
                    constant,
                });
                seen_names.insert(constant.name.clone());
            }
        }
        parent_name = parent.parent_name.as_deref();
    }
}

fn collect_interface_constants<'a>(
    interface_name: &str,
    classes: &'a [ClassDecl],
    seen_interfaces: &mut HashSet<String>,
    constants: &mut Vec<InheritedClassConstant<'a>>,
) {
    let lookup_name = interface_name.trim_start_matches('\\').to_ascii_lowercase();
    if !seen_interfaces.insert(lookup_name) {
        return;
    }
    let Some(interface) = find_class(classes, interface_name) else {
        return;
    };
    if !interface.is_interface {
        return;
    }
    for constant in &interface.constants {
        if constants.iter().any(|existing| {
            existing.class.name.eq_ignore_ascii_case(&interface.name)
                && existing.constant.name == constant.name
        }) {
            continue;
        }
        constants.push(InheritedClassConstant {
            class: interface,
            constant,
        });
    }
    for parent_interface in &interface.interfaces {
        collect_interface_constants(parent_interface, classes, seen_interfaces, constants);
    }
}

fn collect_class_hierarchy_interface_constants<'a>(
    class: &'a ClassDecl,
    classes: &'a [ClassDecl],
    constants: &mut Vec<InheritedClassConstant<'a>>,
) {
    let mut seen_classes = HashSet::new();
    let mut seen_interfaces = HashSet::new();
    let mut current = Some(class);
    while let Some(candidate) = current {
        if !seen_classes.insert(candidate.name.to_ascii_lowercase()) {
            break;
        }
        for interface_name in &candidate.interfaces {
            collect_interface_constants(interface_name, classes, &mut seen_interfaces, constants);
        }
        current = candidate
            .parent_name
            .as_deref()
            .and_then(|name| find_class(classes, name));
    }
}

fn find_final_interface_constant_for_class<'a>(
    class: &ClassDecl,
    constant_name: &str,
    classes: &'a [ClassDecl],
) -> Option<(&'a ClassDecl, &'a ClassConstantDecl)> {
    let mut current = Some(class);
    let mut seen_classes = HashSet::new();
    while let Some(candidate) = current {
        if !seen_classes.insert(candidate.name.to_ascii_lowercase()) {
            break;
        }
        let mut seen_interfaces = HashSet::new();
        for interface_name in &candidate.interfaces {
            if let Some(final_constant) = find_final_interface_constant(
                interface_name,
                constant_name,
                classes,
                &mut seen_interfaces,
            ) {
                return Some(final_constant);
            }
        }
        current = candidate
            .parent_name
            .as_deref()
            .and_then(|name| find_class(classes, name));
    }
    None
}

fn find_final_interface_constant<'a>(
    interface_name: &str,
    constant_name: &str,
    classes: &'a [ClassDecl],
    seen: &mut HashSet<String>,
) -> Option<(&'a ClassDecl, &'a ClassConstantDecl)> {
    let lookup_name = interface_name.trim_start_matches('\\').to_ascii_lowercase();
    if !seen.insert(lookup_name) {
        return None;
    }
    let interface = find_class(classes, interface_name)?;
    if !interface.is_interface {
        return None;
    }
    if let Some(constant) = interface
        .constants
        .iter()
        .find(|constant| constant.name == constant_name && constant.is_final)
    {
        return Some((interface, constant));
    }
    for parent_interface in &interface.interfaces {
        if let Some(final_constant) =
            find_final_interface_constant(parent_interface, constant_name, classes, seen)
        {
            return Some(final_constant);
        }
    }
    None
}

fn validate_property_type_invariance(
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> Result<()> {
    for class in classes {
        for property in &class.properties {
            let Some((parent_class, parent_property)) =
                find_visible_parent_property(class, &property.name, classes)
            else {
                continue;
            };
            validate_instance_property_type_pair(
                class,
                property,
                parent_class,
                parent_property,
                classes,
                &runtime_class_aliases,
            )?;
        }
        for property in &class.static_properties {
            let Some((parent_class, parent_property)) =
                find_visible_parent_static_property(class, &property.name, classes)
            else {
                continue;
            };
            validate_property_type_pair(
                class,
                &property.name,
                property.type_hint.as_ref(),
                class.span,
                parent_class,
                parent_property.type_hint.as_ref(),
                classes,
                &runtime_class_aliases,
            )?;
        }
    }
    Ok(())
}

fn validate_instance_property_type_pair(
    class: &ClassDecl,
    property: &PropertyDecl,
    parent_class: &ClassDecl,
    parent_property: &PropertyDecl,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> Result<()> {
    if !parent_property_uses_one_sided_virtual_hook_variance(parent_property) {
        return validate_property_type_pair(
            class,
            &property.name,
            property.type_hint.as_ref(),
            class.span,
            parent_class,
            parent_property.type_hint.as_ref(),
            classes,
            runtime_class_aliases,
        );
    }

    if parent_property.hook_has_get {
        let child_return_type = property_effective_get_type(property);
        let parent_return_type = property_effective_get_type(parent_property);
        if !type_hint_is_subtype(
            &child_return_type,
            &parent_return_type,
            classes,
            runtime_class_aliases,
        ) {
            return Err(Diagnostic::new(
                format!(
                    "Declaration of {}::{}::get(): {} must be compatible with {}::{}::get(): {}",
                    class.name,
                    property_hook_display_name(&property.name),
                    type_hint_display_canonical(&child_return_type),
                    parent_class.name,
                    property_hook_display_name(&parent_property.name),
                    type_hint_display_canonical(&parent_return_type)
                ),
                property.hook_get_span.or(Some(property.span)),
            ));
        }
    }

    if parent_property.hook_has_set {
        let child_parameter_type = property_effective_set_parameter_type(property);
        let parent_parameter_type = property_effective_set_parameter_type(parent_property);
        if !type_hint_is_subtype(
            &parent_parameter_type,
            &child_parameter_type,
            classes,
            runtime_class_aliases,
        ) {
            let child_parameter_name = property
                .hook_set_parameter_name
                .as_deref()
                .unwrap_or("value");
            let parent_parameter_name = parent_property
                .hook_set_parameter_name
                .as_deref()
                .unwrap_or("value");
            return Err(Diagnostic::new(
                format!(
                    "Declaration of {}::{}::set({} ${}): void must be compatible with {}::{}::set({} ${}): void",
                    class.name,
                    property_hook_display_name(&property.name),
                    type_hint_display_canonical(&child_parameter_type),
                    child_parameter_name,
                    parent_class.name,
                    property_hook_display_name(&parent_property.name),
                    type_hint_display_canonical(&parent_parameter_type),
                    parent_parameter_name
                ),
                property.hook_set_span.or(Some(property.span)),
            ));
        }
    }

    Ok(())
}

fn parent_property_uses_one_sided_virtual_hook_variance(property: &PropertyDecl) -> bool {
    property.has_hooks && property.is_virtual && (property.hook_has_get ^ property.hook_has_set)
}

fn property_effective_get_type(property: &PropertyDecl) -> TypeHint {
    property
        .type_hint
        .as_ref()
        .and_then(|type_hint| type_hint.semantic_type.clone())
        .unwrap_or(TypeHint::Mixed)
}

fn property_effective_set_parameter_type(property: &PropertyDecl) -> TypeHint {
    property
        .hook_set_parameter_type
        .clone()
        .or_else(|| {
            property
                .type_hint
                .as_ref()
                .and_then(|type_hint| type_hint.semantic_type.clone())
        })
        .unwrap_or(TypeHint::Mixed)
}

fn validate_property_type_pair(
    class: &ClassDecl,
    property_name: &str,
    type_hint: Option<&PropertyTypeHint>,
    span: SourceSpan,
    parent_class: &ClassDecl,
    parent_type_hint: Option<&PropertyTypeHint>,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> Result<()> {
    match (type_hint, parent_type_hint) {
        (None, None) => Ok(()),
        (Some(type_hint), Some(parent_type_hint))
            if property_type_hints_are_invariant(
                type_hint,
                parent_type_hint,
                classes,
                runtime_class_aliases,
            ) =>
        {
            Ok(())
        }
        (_, Some(parent_type_hint)) => Err(Diagnostic::new(
            format!(
                "Type of {}::${} must be {} (as in class {})",
                class.name,
                property_name,
                property_type_hint_display(parent_type_hint),
                parent_class.name
            ),
            Some(span),
        )),
        (Some(_), None) => Err(Diagnostic::new(
            format!(
                "Type of {}::${} must be omitted to match the parent definition in class {}",
                class.name, property_name, parent_class.name
            ),
            Some(span),
        )),
    }
}

fn find_visible_parent_property<'a>(
    class: &ClassDecl,
    property_name: &str,
    classes: &'a [ClassDecl],
) -> Option<(&'a ClassDecl, &'a PropertyDecl)> {
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let parent = find_class(classes, name)?;
        if let Some(property) = parent
            .properties
            .iter()
            .find(|candidate| candidate.name == property_name)
        {
            if property.visibility != PropertyVisibility::Private {
                return Some((parent, property));
            }
        }
        parent_name = parent.parent_name.as_deref();
    }
    None
}

fn find_visible_parent_static_property<'a>(
    class: &ClassDecl,
    property_name: &str,
    classes: &'a [ClassDecl],
) -> Option<(&'a ClassDecl, &'a StaticPropertyDecl)> {
    let mut parent_name = class.parent_name.as_deref();
    let mut seen = HashSet::new();
    while let Some(name) = parent_name {
        if !seen.insert(name.to_ascii_lowercase()) {
            break;
        }
        let parent = find_class(classes, name)?;
        if let Some(property) = parent
            .static_properties
            .iter()
            .find(|candidate| candidate.name == property_name)
        {
            if property.visibility != PropertyVisibility::Private {
                return Some((parent, property));
            }
        }
        parent_name = parent.parent_name.as_deref();
    }
    None
}

fn property_type_hints_are_invariant(
    left: &PropertyTypeHint,
    right: &PropertyTypeHint,
    classes: &[ClassDecl],
    runtime_class_aliases: &HashMap<String, String>,
) -> bool {
    if let (Some(left), Some(right)) = (&left.semantic_type, &right.semantic_type) {
        return type_hint_is_subtype(left, right, classes, runtime_class_aliases)
            && type_hint_is_subtype(right, left, classes, runtime_class_aliases);
    }
    property_type_hint_key(left) == property_type_hint_key(right)
}

fn property_type_hint_key(type_hint: &PropertyTypeHint) -> String {
    match &type_hint.kind {
        PropertyTypeKind::Null => "null".to_string(),
        PropertyTypeKind::Array => nullable_property_type_key("array", type_hint.allows_null),
        PropertyTypeKind::Int => nullable_property_type_key("int", type_hint.allows_null),
        PropertyTypeKind::Float => nullable_property_type_key("float", type_hint.allows_null),
        PropertyTypeKind::String => nullable_property_type_key("string", type_hint.allows_null),
        PropertyTypeKind::Bool => nullable_property_type_key("bool", type_hint.allows_null),
        PropertyTypeKind::Mixed => "mixed".to_string(),
        PropertyTypeKind::Object => nullable_property_type_key("object", type_hint.allows_null),
        PropertyTypeKind::Class(name) => nullable_property_type_key(
            &format!(
                "class:{}",
                name.trim_start_matches('\\').to_ascii_lowercase()
            ),
            type_hint.allows_null,
        ),
        PropertyTypeKind::Unsupported => property_type_text_key(&type_hint.text),
    }
}

fn nullable_property_type_key(base: &str, allows_null: bool) -> String {
    if allows_null {
        let mut members = vec![base.to_string(), "null".to_string()];
        members.sort();
        return format!("union:{}", members.join("|"));
    }
    base.to_string()
}

fn property_type_text_key(text: &str) -> String {
    let text = text.trim();
    if let Some(inner) = text.strip_prefix('?') {
        let mut members = vec![property_type_text_key(inner), "null".to_string()];
        members.sort();
        return format!("union:{}", members.join("|"));
    }
    if text.contains('|') {
        let mut members = text
            .split('|')
            .map(property_type_text_key)
            .collect::<Vec<_>>();
        members.sort();
        return format!("union:{}", members.join("|"));
    }
    if text.contains('&') {
        let mut members = text
            .split('&')
            .map(property_type_text_key)
            .collect::<Vec<_>>();
        members.sort();
        return format!("intersection:{}", members.join("&"));
    }
    property_type_atom_key(text)
}

fn property_type_atom_key(text: &str) -> String {
    match text
        .trim()
        .trim_start_matches('\\')
        .to_ascii_lowercase()
        .as_str()
    {
        "integer" => "int".to_string(),
        "double" => "float".to_string(),
        "boolean" => "bool".to_string(),
        "binary" => "string".to_string(),
        "null" | "array" | "int" | "float" | "string" | "bool" | "mixed" | "object"
        | "callable" | "false" | "true" | "iterable" | "never" | "static" | "void" => {
            text.trim().trim_start_matches('\\').to_ascii_lowercase()
        }
        class_name => format!("class:{class_name}"),
    }
}

fn property_type_hint_display(type_hint: &PropertyTypeHint) -> String {
    match &type_hint.kind {
        PropertyTypeKind::Null => "null".to_string(),
        PropertyTypeKind::Array => nullable_property_type_display("array", type_hint.allows_null),
        PropertyTypeKind::Int => nullable_property_type_display("int", type_hint.allows_null),
        PropertyTypeKind::Float => nullable_property_type_display("float", type_hint.allows_null),
        PropertyTypeKind::String => nullable_property_type_display("string", type_hint.allows_null),
        PropertyTypeKind::Bool => nullable_property_type_display("bool", type_hint.allows_null),
        PropertyTypeKind::Mixed => "mixed".to_string(),
        PropertyTypeKind::Object => nullable_property_type_display("object", type_hint.allows_null),
        PropertyTypeKind::Class(name) => {
            nullable_property_type_display(name, type_hint.allows_null)
        }
        PropertyTypeKind::Unsupported => property_type_text_display(&type_hint.text),
    }
}

fn nullable_property_type_display(base: &str, allows_null: bool) -> String {
    if allows_null {
        format!("?{base}")
    } else {
        base.to_string()
    }
}

fn property_type_text_display(text: &str) -> String {
    let text = text.trim();
    if let Some(inner) = text.strip_prefix('?') {
        return format!("?{}", property_type_text_display(inner));
    }
    if text.contains('|') {
        let mut members = text
            .split('|')
            .map(property_type_text_display)
            .collect::<Vec<_>>();
        if members
            .iter()
            .all(|member| property_union_builtin_display_rank(member).is_some())
        {
            members.sort_by_key(|member| property_union_builtin_display_rank(member).unwrap());
        }
        return members.join("|");
    }
    if text.contains('&') {
        return text
            .split('&')
            .map(property_type_text_display)
            .collect::<Vec<_>>()
            .join("&");
    }
    property_type_atom_display(text)
}

fn property_type_atom_display(text: &str) -> String {
    match text.trim().to_ascii_lowercase().as_str() {
        "integer" => "int".to_string(),
        "double" => "float".to_string(),
        "boolean" => "bool".to_string(),
        "binary" => "string".to_string(),
        "null" | "array" | "int" | "float" | "string" | "bool" | "mixed" | "object"
        | "callable" | "false" | "true" | "iterable" | "never" | "static" | "void" => {
            text.trim().to_ascii_lowercase()
        }
        _ => text.trim().to_string(),
    }
}

fn property_union_builtin_display_rank(member: &str) -> Option<usize> {
    match member {
        "object" => Some(0),
        "array" => Some(1),
        "string" => Some(2),
        "int" => Some(3),
        "float" => Some(4),
        "bool" => Some(5),
        "false" => Some(6),
        "true" => Some(7),
        "null" => Some(8),
        _ => None,
    }
}

fn validate_method_names(class: &ClassDecl) -> Result<()> {
    let mut names = HashSet::new();
    for method in &class.methods {
        let lookup_name = method.name.to_ascii_lowercase();
        if method.is_static && lookup_name == "__invoke" {
            return Err(Diagnostic::new(
                format!("Method {}::__invoke() cannot be static", class.name),
                Some(method.span),
            ));
        }
        if !names.insert(lookup_name.clone()) {
            return Err(Diagnostic::new(
                format!("Cannot redeclare {}::{}()", class.name, lookup_name),
                Some(method.span),
            ));
        }
    }
    Ok(())
}

fn validate_property_names(class: &ClassDecl) -> Result<()> {
    let mut names = HashSet::new();
    for property in &class.properties {
        if !names.insert(property.name.clone()) {
            return Err(Diagnostic::new(
                format!("Cannot redeclare {}::${}", class.name, property.name),
                Some(property.span),
            ));
        }
    }
    for property in &class.static_properties {
        if !names.insert(property.name.clone()) {
            return Err(Diagnostic::new(
                format!("Cannot redeclare {}::${}", class.name, property.name),
                Some(property.span),
            ));
        }
    }
    Ok(())
}

fn validate_class_constant_names(class: &ClassDecl) -> Result<()> {
    let mut names = HashSet::new();
    for constant in &class.constants {
        if !names.insert(constant.name.clone()) {
            return Err(Diagnostic::new(
                format!(
                    "Cannot redefine class constant {}::{}",
                    class.name, constant.name
                ),
                Some(constant.span),
            ));
        }
    }
    Ok(())
}

fn validate_trait_magic_method_declarations(traits: &[TraitDecl]) -> Result<()> {
    for trait_decl in traits {
        for method in &trait_decl.methods {
            if let Some(message) = trait_magic_declaration_fatal_message(trait_decl, method) {
                return Err(Diagnostic::new(message, Some(method.span)));
            }
        }
    }
    Ok(())
}

fn trait_magic_declaration_fatal_message(
    trait_decl: &TraitDecl,
    method: &MethodDecl,
) -> Option<String> {
    let method_key = method.name.to_ascii_lowercase();
    let expected_arity = match method_key.as_str() {
        "__get" | "__isset" | "__unset" | "__set_state" => Some(1),
        "__set" | "__call" | "__callstatic" => Some(2),
        "__tostring" | "__debuginfo" => Some(0),
        _ => None,
    };
    if let Some(expected) = expected_arity {
        let actual = method.parameters.len();
        if actual != expected {
            if expected == 0 {
                return Some(format!(
                    "Method {}::{}() cannot take arguments",
                    trait_decl.name, method.name
                ));
            }
            let suffix = if expected == 1 { "" } else { "s" };
            return Some(format!(
                "Method {}::{}() must take exactly {expected} argument{suffix}",
                trait_decl.name, method.name
            ));
        }
    }

    match method_key.as_str() {
        "__callstatic" | "__set_state" if !method.is_static => {
            return Some(format!(
                "Method {}::{}() must be static",
                trait_decl.name, method.name
            ));
        }
        "__call" | "__get" | "__set" | "__isset" | "__unset" | "__tostring" | "__debuginfo"
            if method.is_static =>
        {
            return Some(format!(
                "Method {}::{}() cannot be static",
                trait_decl.name, method.name
            ));
        }
        _ => {}
    }

    if matches!(
        method_key.as_str(),
        "__call" | "__callstatic" | "__get" | "__set" | "__isset" | "__unset"
    ) && method.parameters.iter().any(|parameter| parameter.by_ref)
    {
        return Some(format!(
            "Method {}::{}() cannot take arguments by reference",
            trait_decl.name, method.name
        ));
    }

    if matches!(method_key.as_str(), "__construct" | "__destruct") && method.return_type.is_some() {
        return Some(format!(
            "Method {}::{}() cannot declare a return type",
            trait_decl.name, method.name
        ));
    }

    if let Some(return_type) = method.return_type.as_ref() {
        let expected_label = match method_key.as_str() {
            "__clone" | "__set" | "__unset"
                if !trait_magic_return_type_is_void_compatible(return_type) =>
            {
                Some("void")
            }
            "__isset"
                if !trait_magic_return_type_is_exact_or_never(return_type, &TypeHint::Bool) =>
            {
                Some("bool")
            }
            "__tostring"
                if !trait_magic_return_type_is_exact_or_never(return_type, &TypeHint::String) =>
            {
                Some("string")
            }
            "__debuginfo" if !trait_magic_return_type_is_debug_info_compatible(return_type) => {
                Some("?array")
            }
            "__set_state" if !trait_magic_return_type_is_object_compatible(return_type) => {
                Some("object")
            }
            _ => None,
        };
        if let Some(expected_label) = expected_label {
            return Some(format!(
                "{}::{}(): Return type must be {} when declared",
                trait_decl.name, method.name, expected_label
            ));
        }
    }

    match method_key.as_str() {
        "__get" | "__set" | "__isset" | "__unset" | "__call" | "__callstatic" => {
            if let Some(message) =
                trait_magic_parameter_type_fatal(trait_decl, method, 0, TypeHint::String, "string")
            {
                return Some(message);
            }
        }
        _ => {}
    }
    match method_key.as_str() {
        "__call" | "__callstatic" => {
            trait_magic_parameter_type_fatal(trait_decl, method, 1, TypeHint::Array, "array")
        }
        "__set_state" => {
            trait_magic_parameter_type_fatal(trait_decl, method, 0, TypeHint::Array, "array")
        }
        _ => None,
    }
}

fn trait_magic_return_type_is_exact_or_never(return_type: &TypeHint, expected: &TypeHint) -> bool {
    return_type == expected || matches!(return_type, TypeHint::Never)
}

fn trait_magic_return_type_is_void_compatible(return_type: &TypeHint) -> bool {
    matches!(return_type, TypeHint::Void | TypeHint::Never)
}

fn trait_magic_return_type_is_debug_info_compatible(return_type: &TypeHint) -> bool {
    match return_type {
        TypeHint::Array | TypeHint::Never => true,
        TypeHint::Nullable(inner) => matches!(inner.as_ref(), TypeHint::Array),
        TypeHint::Union(types) => {
            types.len() == 2
                && types
                    .iter()
                    .any(|type_hint| matches!(type_hint, TypeHint::Array))
                && types
                    .iter()
                    .any(|type_hint| matches!(type_hint, TypeHint::Null))
        }
        _ => false,
    }
}

fn trait_magic_return_type_is_object_compatible(return_type: &TypeHint) -> bool {
    match return_type {
        TypeHint::Object | TypeHint::Static | TypeHint::Class(_) | TypeHint::Never => true,
        TypeHint::Union(types) | TypeHint::Intersection(types) => {
            !types.is_empty()
                && types
                    .iter()
                    .all(trait_magic_return_type_is_object_compatible)
        }
        _ => false,
    }
}

fn trait_magic_parameter_type_fatal(
    trait_decl: &TraitDecl,
    method: &MethodDecl,
    parameter_index: usize,
    expected_type: TypeHint,
    expected_label: &str,
) -> Option<String> {
    let parameter = method.parameters.get(parameter_index)?;
    let declared_type = parameter.type_hint.as_ref()?;
    if trait_magic_parameter_type_accepts_required(declared_type, &expected_type) {
        return None;
    }
    Some(format!(
        "{}::{}(): Parameter #{} (${}) must be of type {} when declared",
        trait_decl.name,
        method.name,
        parameter_index + 1,
        parameter.name,
        expected_label
    ))
}

fn trait_magic_parameter_type_accepts_required(
    declared_type: &TypeHint,
    required_type: &TypeHint,
) -> bool {
    if declared_type == required_type {
        return true;
    }
    match declared_type {
        TypeHint::Mixed => true,
        TypeHint::Nullable(inner) => {
            matches!(required_type, TypeHint::Null)
                || trait_magic_parameter_type_accepts_required(inner, required_type)
        }
        TypeHint::Union(types) => types
            .iter()
            .any(|member| trait_magic_parameter_type_accepts_required(member, required_type)),
        TypeHint::Iterable if matches!(required_type, TypeHint::Array) => true,
        _ => false,
    }
}

#[derive(Debug, Clone)]
struct LabelInfo {
    control_path: Vec<usize>,
    finally_path: Vec<usize>,
}

fn validate_goto_labels(statements: &[Statement]) -> Result<()> {
    let mut labels = HashMap::new();
    let mut control_path = Vec::new();
    let mut finally_path = Vec::new();
    collect_labels(
        statements,
        &mut labels,
        &mut control_path,
        &mut finally_path,
    )?;
    validate_gotos(statements, &labels, &mut control_path, &mut finally_path)
}

#[derive(Debug, Clone, Copy)]
enum ControlTransfer {
    Break,
    Continue,
}

impl ControlTransfer {
    fn keyword(self) -> &'static str {
        match self {
            Self::Break => "break",
            Self::Continue => "continue",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ContinueTargetKind {
    Loop,
    Switch,
}

fn collect_continue_targeting_switch_warnings(
    statements: &[Statement],
    compile_warnings: &mut Vec<CompileWarning>,
) {
    collect_continue_targeting_switch_warnings_inner(statements, &mut Vec::new(), compile_warnings);
}

fn collect_continue_targeting_switch_warnings_inner(
    statements: &[Statement],
    contexts: &mut Vec<ContinueTargetKind>,
    compile_warnings: &mut Vec<CompileWarning>,
) {
    for statement in statements {
        match statement {
            Statement::Block { statements, .. } => {
                collect_continue_targeting_switch_warnings_inner(
                    statements,
                    contexts,
                    compile_warnings,
                );
            }
            Statement::If {
                then_body,
                else_body,
                ..
            } => {
                collect_continue_targeting_switch_warnings_inner(
                    then_body,
                    contexts,
                    compile_warnings,
                );
                collect_continue_targeting_switch_warnings_inner(
                    else_body,
                    contexts,
                    compile_warnings,
                );
            }
            Statement::While { body, .. } | Statement::DoWhile { body, .. } => {
                contexts.push(ContinueTargetKind::Loop);
                collect_continue_targeting_switch_warnings_inner(body, contexts, compile_warnings);
                contexts.pop();
            }
            Statement::For {
                initializers,
                updates,
                body,
                ..
            } => {
                collect_continue_targeting_switch_warnings_inner(
                    initializers,
                    contexts,
                    compile_warnings,
                );
                contexts.push(ContinueTargetKind::Loop);
                collect_continue_targeting_switch_warnings_inner(body, contexts, compile_warnings);
                contexts.pop();
                collect_continue_targeting_switch_warnings_inner(
                    updates,
                    contexts,
                    compile_warnings,
                );
            }
            Statement::Foreach { body, .. } => {
                contexts.push(ContinueTargetKind::Loop);
                collect_continue_targeting_switch_warnings_inner(body, contexts, compile_warnings);
                contexts.pop();
            }
            Statement::Switch { cases, .. } => {
                contexts.push(ContinueTargetKind::Switch);
                for case in cases {
                    collect_continue_targeting_switch_warnings_inner(
                        &case.body,
                        contexts,
                        compile_warnings,
                    );
                }
                contexts.pop();
            }
            Statement::Continue { level, span } if *level > 0 && *level <= contexts.len() => {
                let target_index = contexts.len() - *level;
                if contexts[target_index] == ContinueTargetKind::Switch {
                    compile_warnings.push(CompileWarning {
                        message: continue_targeting_switch_warning(*level, contexts, target_index),
                        span: *span,
                        kind: CompileWarningKind::Warning,
                    });
                }
            }
            Statement::Try {
                body,
                catches,
                finally_body,
                ..
            } => {
                collect_continue_targeting_switch_warnings_inner(body, contexts, compile_warnings);
                for catch in catches {
                    collect_continue_targeting_switch_warnings_inner(
                        &catch.body,
                        contexts,
                        compile_warnings,
                    );
                }
                collect_continue_targeting_switch_warnings_inner(
                    finally_body,
                    contexts,
                    compile_warnings,
                );
            }
            _ => {}
        }
    }
}

fn continue_targeting_switch_warning(
    level: usize,
    contexts: &[ContinueTargetKind],
    target_index: usize,
) -> String {
    let mut message = format!(
        "{} targeting switch is equivalent to {}",
        quoted_control_operator("continue", level),
        quoted_control_operator("break", level)
    );
    if let Some(suggested_level) = nearest_outer_loop_level(contexts, target_index) {
        message.push_str(". Did you mean to use ");
        message.push_str(&quoted_control_operator("continue", suggested_level));
        message.push('?');
    }
    message
}

fn nearest_outer_loop_level(contexts: &[ContinueTargetKind], target_index: usize) -> Option<usize> {
    (0..target_index)
        .rev()
        .find(|index| contexts[*index] == ContinueTargetKind::Loop)
        .map(|index| contexts.len() - index)
}

fn quoted_control_operator(operator: &str, level: usize) -> String {
    if level == 1 {
        format!("\"{operator}\"")
    } else {
        format!("\"{operator} {level}\"")
    }
}

fn validate_control_transfers_in_statements(
    statements: &[Statement],
    control_depth: usize,
) -> Result<()> {
    validate_control_transfers_in_statements_inner(statements, control_depth, &mut Vec::new())
}

fn validate_control_transfers_in_statements_inner(
    statements: &[Statement],
    control_depth: usize,
    finally_control_depths: &mut Vec<usize>,
) -> Result<()> {
    for statement in statements {
        match statement {
            Statement::Assign { value, .. }
            | Statement::AssignRef { source: value, .. }
            | Statement::Print {
                expression: value, ..
            }
            | Statement::Expression {
                expression: value, ..
            }
            | Statement::Return {
                value: Some(value), ..
            }
            | Statement::Exit {
                value: Some(value), ..
            }
            | Statement::Throw { value, .. } => {
                validate_control_transfers_in_expr(value)?;
            }
            Statement::ArrayAssign { target, value, .. } => {
                validate_control_transfers_in_array_dim_target(target)?;
                validate_control_transfers_in_expr(value)?;
            }
            Statement::ArrayAssignRef { target, source, .. } => {
                validate_control_transfers_in_array_dim_target(target)?;
                validate_control_transfers_in_expr(source)?;
            }
            Statement::Call { arguments, .. }
            | Statement::Echo {
                expressions: arguments,
                ..
            } => {
                validate_control_transfers_in_exprs(arguments)?;
            }
            Statement::Const { declarations, .. } => {
                for declaration in declarations {
                    validate_control_transfers_in_expr(&declaration.value)?;
                }
            }
            Statement::Static { declarations, .. } => {
                for declaration in declarations {
                    if let Some(value) = &declaration.value {
                        validate_control_transfers_in_expr(value)?;
                    }
                }
            }
            Statement::Block { statements, .. } => {
                validate_control_transfers_in_statements_inner(
                    statements,
                    control_depth,
                    finally_control_depths,
                )?;
            }
            Statement::If {
                condition,
                then_body,
                else_body,
                ..
            } => {
                validate_control_transfers_in_expr(condition)?;
                validate_control_transfers_in_statements_inner(
                    then_body,
                    control_depth,
                    finally_control_depths,
                )?;
                validate_control_transfers_in_statements_inner(
                    else_body,
                    control_depth,
                    finally_control_depths,
                )?;
            }
            Statement::While {
                condition, body, ..
            } => {
                validate_control_transfers_in_expr(condition)?;
                validate_control_transfers_in_statements_inner(
                    body,
                    control_depth + 1,
                    finally_control_depths,
                )?;
            }
            Statement::DoWhile {
                body, condition, ..
            } => {
                validate_control_transfers_in_statements_inner(
                    body,
                    control_depth + 1,
                    finally_control_depths,
                )?;
                validate_control_transfers_in_expr(condition)?;
            }
            Statement::For {
                initializers,
                conditions,
                updates,
                body,
                ..
            } => {
                validate_control_transfers_in_statements_inner(
                    initializers,
                    control_depth,
                    finally_control_depths,
                )?;
                for condition in conditions {
                    validate_control_transfers_in_expr(condition)?;
                }
                validate_control_transfers_in_statements_inner(
                    updates,
                    control_depth,
                    finally_control_depths,
                )?;
                validate_control_transfers_in_statements_inner(
                    body,
                    control_depth + 1,
                    finally_control_depths,
                )?;
            }
            Statement::Foreach {
                iterable,
                key,
                value,
                body,
                ..
            } => {
                validate_control_transfers_in_expr(iterable)?;
                if let Some(key) = key {
                    validate_control_transfers_in_assignment_target(key)?;
                }
                validate_control_transfers_in_assignment_target(value)?;
                validate_control_transfers_in_statements_inner(
                    body,
                    control_depth + 1,
                    finally_control_depths,
                )?;
            }
            Statement::Switch {
                expression, cases, ..
            } => {
                validate_control_transfers_in_expr(expression)?;
                for case in cases {
                    if let Some(condition) = &case.condition {
                        validate_control_transfers_in_expr(condition)?;
                    }
                    validate_control_transfers_in_statements_inner(
                        &case.body,
                        control_depth + 1,
                        finally_control_depths,
                    )?;
                }
            }
            Statement::Break { level, span } => validate_control_transfer_target(
                ControlTransfer::Break,
                *level,
                *span,
                control_depth,
                finally_control_depths,
            )?,
            Statement::Continue { level, span } => validate_control_transfer_target(
                ControlTransfer::Continue,
                *level,
                *span,
                control_depth,
                finally_control_depths,
            )?,
            Statement::Try {
                body,
                catches,
                finally_body,
                ..
            } => {
                validate_control_transfers_in_statements_inner(
                    body,
                    control_depth,
                    finally_control_depths,
                )?;
                for catch in catches {
                    validate_control_transfers_in_statements_inner(
                        &catch.body,
                        control_depth,
                        finally_control_depths,
                    )?;
                }
                finally_control_depths.push(control_depth);
                let result = validate_control_transfers_in_statements_inner(
                    finally_body,
                    control_depth,
                    finally_control_depths,
                );
                finally_control_depths.pop();
                result?;
            }
            Statement::Increment { target, .. } => {
                validate_control_transfers_in_inc_dec_target(target)?;
            }
            Statement::Unset { targets, .. } => {
                for target in targets {
                    validate_control_transfers_in_unset_target(target)?;
                }
            }
            Statement::Return { value: None, .. }
            | Statement::Exit { value: None, .. }
            | Statement::Empty { .. }
            | Statement::ClassDeclaration { .. }
            | Statement::TraitDeclaration { .. }
            | Statement::FunctionDeclaration { .. }
            | Statement::Global { .. }
            | Statement::Label { .. }
            | Statement::Goto { .. }
            | Statement::InlineHtml { .. } => {}
        }
    }
    Ok(())
}

fn validate_control_transfer_target(
    transfer: ControlTransfer,
    level: usize,
    span: SourceSpan,
    control_depth: usize,
    finally_control_depths: &[usize],
) -> Result<()> {
    let keyword = transfer.keyword();
    if level == 0 {
        return Err(Diagnostic::new(
            format!("'{keyword}' operator accepts only positive integers"),
            Some(span),
        ));
    }
    if control_depth == 0 {
        return Err(Diagnostic::new(
            format!("'{keyword}' not in the 'loop' or 'switch' context"),
            Some(span),
        ));
    }
    if level > control_depth {
        let suffix = if level == 1 { "level" } else { "levels" };
        return Err(Diagnostic::new(
            format!("Cannot '{keyword}' {level} {suffix}"),
            Some(span),
        ));
    }
    let target_depth = control_depth - level;
    if finally_control_depths
        .iter()
        .any(|finally_control_depth| target_depth < *finally_control_depth)
    {
        return Err(Diagnostic::new(
            "jump out of a finally block is disallowed",
            Some(span),
        ));
    }
    Ok(())
}

fn validate_control_transfers_in_exprs(expressions: &[Expr]) -> Result<()> {
    for expression in expressions {
        validate_control_transfers_in_expr(expression)?;
    }
    Ok(())
}

fn validate_control_transfers_in_expr(expr: &Expr) -> Result<()> {
    match expr {
        Expr::AnonymousFunction(function) => {
            validate_control_transfers_in_statements(&function.body, 0)?;
        }
        Expr::DynamicVariable { name, .. } => validate_control_transfers_in_expr(name)?,
        Expr::IncDec { target, .. } => validate_control_transfers_in_inc_dec_target(target)?,
        Expr::Assign { target, value, .. } => {
            validate_control_transfers_in_assignment_target(target)?;
            validate_control_transfers_in_expr(value)?;
        }
        Expr::AssignRef { target, source, .. } => {
            validate_control_transfers_in_assignment_target(target)?;
            validate_control_transfers_in_expr(source)?;
        }
        Expr::Call { arguments, .. }
        | Expr::ParentPropertyHookCall { arguments, .. }
        | Expr::NewObject { arguments, .. } => {
            validate_control_transfers_in_exprs(arguments)?;
        }
        Expr::FirstClassCallable { callable, .. } => {
            validate_control_transfers_in_expr(callable)?;
        }
        Expr::DynamicCall {
            callee, arguments, ..
        } => {
            validate_control_transfers_in_expr(callee)?;
            validate_control_transfers_in_exprs(arguments)?;
        }
        Expr::MethodCall {
            receiver,
            arguments,
            ..
        } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_exprs(arguments)?;
        }
        Expr::DynamicMethodCall {
            receiver,
            name,
            arguments,
            ..
        } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_expr(name)?;
            validate_control_transfers_in_exprs(arguments)?;
        }
        Expr::DynamicNewObject {
            class_name,
            arguments,
            ..
        } => {
            validate_control_transfers_in_expr(class_name)?;
            validate_control_transfers_in_exprs(arguments)?;
        }
        Expr::InstanceOf { expr, target, .. } => {
            validate_control_transfers_in_expr(expr)?;
            if let InstanceOfTarget::Expr(target) = target {
                validate_control_transfers_in_expr(target)?;
            }
        }
        Expr::Clone {
            expr,
            with_properties,
            ..
        } => {
            validate_control_transfers_in_expr(expr)?;
            if let Some(with_properties) = with_properties {
                validate_control_transfers_in_expr(with_properties)?;
            }
        }
        Expr::PropertyFetch { receiver: expr, .. }
        | Expr::NullsafePropertyFetch { receiver: expr, .. }
        | Expr::DynamicStaticPropertyFetch { receiver: expr, .. }
        | Expr::DynamicClassNameFetch { receiver: expr, .. }
        | Expr::Empty { target: expr, .. }
        | Expr::Print {
            expression: expr, ..
        }
        | Expr::Include { path: expr, .. }
        | Expr::Throw { value: expr, .. }
        | Expr::Unary { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Grouped { expr, .. }
        | Expr::PipeValue { expr, .. } => validate_control_transfers_in_expr(expr)?,
        Expr::Exit { value, .. } => {
            if let Some(value) = value {
                validate_control_transfers_in_expr(value)?;
            }
        }
        Expr::DynamicClassConstantFetch { receiver, name, .. } => {
            if let Some(receiver) = receiver {
                validate_control_transfers_in_expr(receiver)?;
            }
            validate_control_transfers_in_expr(name)?;
        }
        Expr::YieldFrom { expr, .. } => validate_control_transfers_in_expr(expr)?,
        Expr::Yield { key, value, .. } => {
            if let Some(key) = key {
                validate_control_transfers_in_expr(key)?;
            }
            if let Some(value) = value {
                validate_control_transfers_in_expr(value)?;
            }
        }
        Expr::DynamicPropertyFetch { receiver, name, .. } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_expr(name)?;
        }
        Expr::DynamicStaticPropertyNameFetch { name, .. } => {
            validate_control_transfers_in_expr(name)?;
        }
        Expr::Array { elements, .. } => {
            for element in elements {
                if let Some(key) = &element.key {
                    validate_control_transfers_in_expr(key)?;
                }
                match &element.value {
                    ArrayElementValue::Hole(_) => {}
                    ArrayElementValue::Value(value) | ArrayElementValue::Unpack(value) => {
                        validate_control_transfers_in_expr(value)?;
                    }
                    ArrayElementValue::Reference(target) => {
                        validate_control_transfers_in_reference_target(target)?;
                    }
                }
            }
        }
        Expr::List(list) => validate_control_transfers_in_list_expr(list)?,
        Expr::ArrayAccess { array, index, .. } => {
            validate_control_transfers_in_expr(array)?;
            if let Some(index) = index {
                validate_control_transfers_in_expr(index)?;
            }
        }
        Expr::Isset { targets, .. } => validate_control_transfers_in_exprs(targets)?,
        Expr::Binary { left, right, .. } => {
            validate_control_transfers_in_expr(left)?;
            validate_control_transfers_in_expr(right)?;
        }
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => {
            validate_control_transfers_in_expr(condition)?;
            if let Some(if_true) = if_true {
                validate_control_transfers_in_expr(if_true)?;
            }
            validate_control_transfers_in_expr(if_false)?;
        }
        Expr::Match { subject, arms, .. } => {
            validate_control_transfers_in_expr(subject)?;
            for arm in arms {
                validate_control_transfers_in_exprs(&arm.conditions)?;
                validate_control_transfers_in_expr(&arm.value)?;
            }
        }
        Expr::String(_, _)
        | Expr::InterpolatedString(_, _)
        | Expr::ShellExec { .. }
        | Expr::Int(_, _)
        | Expr::Float(_, _)
        | Expr::Bool(_, _)
        | Expr::Null(_)
        | Expr::Variable(_, _)
        | Expr::Constant(_, _)
        | Expr::MagicConstant(_, _)
        | Expr::StaticPropertyFetch { .. }
        | Expr::ClassConstantFetch { .. } => {}
    }
    Ok(())
}

fn validate_control_transfers_in_assignment_target(target: &AssignmentTarget) -> Result<()> {
    match target {
        AssignmentTarget::Variable { .. } | AssignmentTarget::StaticProperty { .. } => {}
        AssignmentTarget::DynamicStaticProperty { receiver, .. } => {
            validate_control_transfers_in_expr(receiver)?;
        }
        AssignmentTarget::DynamicStaticPropertyName { name, .. } => {
            validate_control_transfers_in_expr(name)?;
        }
        AssignmentTarget::DynamicVariable { name, .. } => {
            validate_control_transfers_in_expr(name)?;
        }
        AssignmentTarget::DynamicArrayDim {
            name, dimensions, ..
        } => {
            validate_control_transfers_in_expr(name)?;
            validate_control_transfers_in_optional_exprs(dimensions)?;
        }
        AssignmentTarget::ArrayDim(target) => {
            validate_control_transfers_in_array_dim_target(target)?;
        }
        AssignmentTarget::PropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_optional_exprs(dimensions)?;
        }
        AssignmentTarget::DynamicPropertyArrayDim {
            receiver,
            name,
            dimensions,
            ..
        } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_expr(name)?;
            validate_control_transfers_in_optional_exprs(dimensions)?;
        }
        AssignmentTarget::StaticPropertyArrayDim { dimensions, .. } => {
            validate_control_transfers_in_optional_exprs(dimensions)?;
        }
        AssignmentTarget::DynamicStaticPropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_optional_exprs(dimensions)?;
        }
        AssignmentTarget::ValueArrayDim {
            array, dimensions, ..
        } => {
            validate_control_transfers_in_expr(array)?;
            validate_control_transfers_in_optional_exprs(dimensions)?;
        }
        AssignmentTarget::Property { receiver, .. } => {
            validate_control_transfers_in_expr(receiver)?;
        }
        AssignmentTarget::DynamicProperty { receiver, name, .. } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_expr(name)?;
        }
        AssignmentTarget::List(list) => {
            validate_control_transfers_in_list_assignment_target(list)?;
        }
    }
    Ok(())
}

fn validate_control_transfers_in_list_assignment_target(
    target: &ListAssignmentTarget,
) -> Result<()> {
    for element in &target.elements {
        if let Some(key) = &element.key {
            validate_control_transfers_in_expr(key)?;
        }
        match &element.target {
            ListAssignmentElementTarget::Value(target) => {
                validate_control_transfers_in_assignment_target(target)?;
            }
            ListAssignmentElementTarget::Reference(target) => {
                validate_control_transfers_in_reference_target(target)?;
            }
        }
    }
    Ok(())
}

fn validate_control_transfers_in_list_expr(list: &ListExpr) -> Result<()> {
    for element in &list.elements {
        if let Some(key) = &element.key {
            validate_control_transfers_in_expr(key)?;
        }
        match &element.target {
            Some(ListExprElementTarget::Value(value)) => {
                validate_control_transfers_in_expr(value)?;
            }
            Some(ListExprElementTarget::Reference(target)) => {
                validate_control_transfers_in_reference_target(target)?;
            }
            None => {}
        }
    }
    Ok(())
}

fn validate_control_transfers_in_reference_target(target: &ReferenceTarget) -> Result<()> {
    match target {
        ReferenceTarget::Variable { .. } => {}
        ReferenceTarget::DynamicVariable { name, .. } => {
            validate_control_transfers_in_expr(name)?;
        }
        ReferenceTarget::ArrayDim(target) => {
            validate_control_transfers_in_array_dim_target(target)?;
        }
        ReferenceTarget::PropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_optional_exprs(dimensions)?;
        }
        ReferenceTarget::Property { receiver, .. } => {
            validate_control_transfers_in_expr(receiver)?;
        }
        ReferenceTarget::DynamicProperty { receiver, name, .. } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_expr(name)?;
        }
    }
    Ok(())
}

fn validate_control_transfers_in_array_dim_target(target: &ArrayDimTarget) -> Result<()> {
    validate_control_transfers_in_optional_exprs(&target.dimensions)
}

fn validate_control_transfers_in_inc_dec_target(target: &IncDecTarget) -> Result<()> {
    match target {
        IncDecTarget::Variable { .. } | IncDecTarget::StaticProperty { .. } => {}
        IncDecTarget::DynamicVariable { name, .. } => {
            validate_control_transfers_in_expr(name)?;
        }
        IncDecTarget::DynamicArrayDim {
            name, dimensions, ..
        } => {
            validate_control_transfers_in_expr(name)?;
            validate_control_transfers_in_optional_exprs(dimensions)?;
        }
        IncDecTarget::ArrayDim(target) => {
            validate_control_transfers_in_array_dim_target(target)?;
        }
        IncDecTarget::ValueArrayDim {
            array, dimensions, ..
        } => {
            validate_control_transfers_in_expr(array)?;
            validate_control_transfers_in_optional_exprs(dimensions)?;
        }
        IncDecTarget::PropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_optional_exprs(dimensions)?;
        }
        IncDecTarget::StaticPropertyArrayDim { dimensions, .. } => {
            validate_control_transfers_in_optional_exprs(dimensions)?;
        }
        IncDecTarget::Property { receiver, .. } => {
            validate_control_transfers_in_expr(receiver)?;
        }
        IncDecTarget::DynamicProperty { receiver, name, .. } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_expr(name)?;
        }
        IncDecTarget::DynamicStaticPropertyName { name, .. } => {
            validate_control_transfers_in_expr(name)?;
        }
    }
    Ok(())
}

fn validate_control_transfers_in_unset_target(target: &UnsetTarget) -> Result<()> {
    match target {
        UnsetTarget::Variable { .. } => {}
        UnsetTarget::DynamicVariable { name, .. } => {
            validate_control_transfers_in_expr(name)?;
        }
        UnsetTarget::DynamicArrayDim {
            name, dimensions, ..
        } => {
            validate_control_transfers_in_expr(name)?;
            validate_control_transfers_in_exprs(dimensions)?;
        }
        UnsetTarget::ValueArrayDim {
            array, dimensions, ..
        } => {
            validate_control_transfers_in_expr(array)?;
            validate_control_transfers_in_exprs(dimensions)?;
        }
        UnsetTarget::PropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_exprs(dimensions)?;
        }
        UnsetTarget::StaticPropertyArrayDim { dimensions, .. } => {
            validate_control_transfers_in_exprs(dimensions)?;
        }
        UnsetTarget::DynamicStaticPropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_exprs(dimensions)?;
        }
        UnsetTarget::Property { receiver, .. } => {
            validate_control_transfers_in_expr(receiver)?;
        }
        UnsetTarget::DynamicProperty { receiver, name, .. } => {
            validate_control_transfers_in_expr(receiver)?;
            validate_control_transfers_in_expr(name)?;
        }
        UnsetTarget::DynamicStaticPropertyName { name, .. } => {
            validate_control_transfers_in_expr(name)?;
        }
        UnsetTarget::StaticProperty { .. } => {}
        UnsetTarget::ArrayDim(target) => {
            validate_control_transfers_in_array_dim_target(target)?;
        }
    }
    Ok(())
}

fn validate_control_transfers_in_optional_exprs(expressions: &[Option<Expr>]) -> Result<()> {
    for expression in expressions.iter().flatten() {
        validate_control_transfers_in_expr(expression)?;
    }
    Ok(())
}

fn reference_source_is_variable(source: &Expr, variable: &str) -> bool {
    match source {
        Expr::Variable(name, _) => name == variable,
        Expr::Grouped { expr, .. } => reference_source_is_variable(expr, variable),
        _ => false,
    }
}

fn validate_recursive_reference_assignment_value(
    target: &AssignmentTarget,
    value: &Expr,
) -> Result<()> {
    let variable = match target {
        AssignmentTarget::Variable { name, .. } => name,
        AssignmentTarget::DynamicVariable { .. } => return Ok(()),
        AssignmentTarget::DynamicArrayDim { .. } => return Ok(()),
        AssignmentTarget::ArrayDim(target) => &target.array,
        AssignmentTarget::PropertyArrayDim { .. } => return Ok(()),
        AssignmentTarget::DynamicPropertyArrayDim { .. } => return Ok(()),
        AssignmentTarget::StaticPropertyArrayDim { .. } => return Ok(()),
        AssignmentTarget::DynamicStaticPropertyArrayDim { .. } => return Ok(()),
        AssignmentTarget::ValueArrayDim { .. } => return Ok(()),
        AssignmentTarget::Property { .. } => return Ok(()),
        AssignmentTarget::DynamicProperty { .. } => return Ok(()),
        AssignmentTarget::StaticProperty { .. } => return Ok(()),
        AssignmentTarget::DynamicStaticProperty { .. } => return Ok(()),
        AssignmentTarget::DynamicStaticPropertyName { .. } => return Ok(()),
        AssignmentTarget::List(_) => return Ok(()),
    };
    if let Some(diagnostic) = expr_array_literal_reference_to_variable(value, variable) {
        if matches!(target, AssignmentTarget::Variable { .. })
            && matches!(diagnostic, RecursiveReferenceDiagnostic::RecursiveArray(_))
        {
            return Ok(());
        }
        return Err(diagnostic.into_diagnostic());
    }
    Ok(())
}

enum RecursiveReferenceDiagnostic {
    RecursiveArray(SourceSpan),
    SameArrayElement(SourceSpan),
}

impl RecursiveReferenceDiagnostic {
    fn into_diagnostic(self) -> Diagnostic {
        match self {
            RecursiveReferenceDiagnostic::RecursiveArray(span) => {
                Diagnostic::new("recursive array references are unsupported", Some(span))
            }
            RecursiveReferenceDiagnostic::SameArrayElement(span) => {
                Diagnostic::new("same-array element references are unsupported", Some(span))
            }
        }
    }
}

fn expr_array_literal_reference_to_variable(
    expr: &Expr,
    variable: &str,
) -> Option<RecursiveReferenceDiagnostic> {
    match expr {
        Expr::Array { elements, .. } => elements
            .iter()
            .find_map(|element| array_element_reference_to_variable(element, variable)),
        Expr::List(list) => list.elements.iter().find_map(|element| {
            element
                .key
                .as_ref()
                .and_then(|key| expr_array_literal_reference_to_variable(key, variable))
                .or_else(|| match &element.target {
                    Some(ListExprElementTarget::Value(value)) => {
                        expr_array_literal_reference_to_variable(value, variable)
                    }
                    Some(ListExprElementTarget::Reference(target)) => {
                        reference_target_reference_to_variable(target, variable)
                    }
                    None => None,
                })
        }),
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => expr_array_literal_reference_to_variable(condition, variable)
            .or_else(|| {
                if_true
                    .as_deref()
                    .and_then(|if_true| expr_array_literal_reference_to_variable(if_true, variable))
            })
            .or_else(|| expr_array_literal_reference_to_variable(if_false, variable)),
        Expr::Match { subject, arms, .. } => {
            expr_array_literal_reference_to_variable(subject, variable).or_else(|| {
                arms.iter().find_map(|arm| {
                    arm.conditions
                        .iter()
                        .find_map(|condition| {
                            expr_array_literal_reference_to_variable(condition, variable)
                        })
                        .or_else(|| expr_array_literal_reference_to_variable(&arm.value, variable))
                })
            })
        }
        Expr::Assign { value, .. }
        | Expr::AssignRef { source: value, .. }
        | Expr::Print {
            expression: value, ..
        }
        | Expr::Include { path: value, .. }
        | Expr::Throw { value, .. }
        | Expr::FirstClassCallable {
            callable: value, ..
        }
        | Expr::Grouped { expr: value, .. }
        | Expr::PipeValue { expr: value, .. } => {
            expr_array_literal_reference_to_variable(value, variable)
        }
        Expr::Clone {
            expr,
            with_properties,
            ..
        } => expr_array_literal_reference_to_variable(expr, variable).or_else(|| {
            with_properties
                .as_deref()
                .and_then(|value| expr_array_literal_reference_to_variable(value, variable))
        }),
        Expr::Exit { value, .. } => value
            .as_deref()
            .and_then(|value| expr_array_literal_reference_to_variable(value, variable)),
        Expr::YieldFrom { expr, .. } => expr_array_literal_reference_to_variable(expr, variable),
        Expr::Yield { key, value, .. } => key
            .as_deref()
            .and_then(|key| expr_array_literal_reference_to_variable(key, variable))
            .or_else(|| {
                value
                    .as_deref()
                    .and_then(|value| expr_array_literal_reference_to_variable(value, variable))
            }),
        Expr::DynamicVariable { name, .. } => {
            expr_array_literal_reference_to_variable(name, variable)
        }
        Expr::DynamicStaticPropertyNameFetch { name, .. } => {
            expr_array_literal_reference_to_variable(name, variable)
        }
        Expr::String(_, _)
        | Expr::InterpolatedString(_, _)
        | Expr::ShellExec { .. }
        | Expr::Int(_, _)
        | Expr::Float(_, _)
        | Expr::Bool(_, _)
        | Expr::Null(_)
        | Expr::Variable(_, _)
        | Expr::AnonymousFunction(_)
        | Expr::IncDec { .. }
        | Expr::Constant(_, _)
        | Expr::MagicConstant(_, _)
        | Expr::Call { .. }
        | Expr::DynamicCall { .. }
        | Expr::MethodCall { .. }
        | Expr::DynamicMethodCall { .. }
        | Expr::ParentPropertyHookCall { .. }
        | Expr::NewObject { .. }
        | Expr::DynamicNewObject { .. }
        | Expr::PropertyFetch { .. }
        | Expr::NullsafePropertyFetch { .. }
        | Expr::DynamicPropertyFetch { .. }
        | Expr::StaticPropertyFetch { .. }
        | Expr::DynamicStaticPropertyFetch { .. }
        | Expr::ClassConstantFetch { .. }
        | Expr::DynamicClassConstantFetch { .. }
        | Expr::DynamicClassNameFetch { .. }
        | Expr::InstanceOf { .. }
        | Expr::ArrayAccess { .. }
        | Expr::Isset { .. }
        | Expr::Empty { .. }
        | Expr::Unary { .. }
        | Expr::Cast { .. }
        | Expr::Binary { .. } => None,
    }
}

fn array_element_reference_to_variable(
    element: &ArrayElement,
    variable: &str,
) -> Option<RecursiveReferenceDiagnostic> {
    element
        .key
        .as_ref()
        .and_then(|key| expr_array_literal_reference_to_variable(key, variable))
        .or_else(|| match &element.value {
            ArrayElementValue::Hole(_) => None,
            ArrayElementValue::Reference(target) => {
                reference_target_reference_to_variable(target, variable)
            }
            ArrayElementValue::Value(value) => {
                expr_array_literal_reference_to_variable(value, variable)
            }
            ArrayElementValue::Unpack(value) => {
                expr_array_literal_reference_to_variable(value, variable)
            }
        })
}

fn reference_target_reference_to_variable(
    target: &ReferenceTarget,
    variable: &str,
) -> Option<RecursiveReferenceDiagnostic> {
    match target {
        ReferenceTarget::Variable { name, span } if name == variable => {
            Some(RecursiveReferenceDiagnostic::RecursiveArray(*span))
        }
        ReferenceTarget::DynamicVariable { name, .. } => {
            expr_array_literal_reference_to_variable(name, variable)
        }
        ReferenceTarget::ArrayDim(target) if target.array == variable => {
            Some(RecursiveReferenceDiagnostic::SameArrayElement(target.span))
        }
        ReferenceTarget::PropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => expr_array_literal_reference_to_variable(receiver, variable).or_else(|| {
            dimensions
                .iter()
                .flatten()
                .find_map(|dimension| expr_array_literal_reference_to_variable(dimension, variable))
        }),
        ReferenceTarget::DynamicProperty { receiver, name, .. } => {
            expr_array_literal_reference_to_variable(receiver, variable)
                .or_else(|| expr_array_literal_reference_to_variable(name, variable))
        }
        _ => None,
    }
}

fn validate_function_names(functions: &[FunctionDecl]) -> Result<()> {
    let mut names: HashMap<String, SourceSpan> = HashMap::new();
    for function in functions {
        let lookup_name = function.name.to_ascii_lowercase();
        if is_modeled_internal_function_name(&lookup_name) {
            return Err(Diagnostic::new(
                format!("Cannot redeclare function {lookup_name}()"),
                Some(function.span),
            ));
        }
        if let Some(previous_span) = names.get(&lookup_name) {
            return Err(Diagnostic::new(
                format!(
                    "Cannot redeclare function {lookup_name}() (previously declared in Unknown:{})",
                    previous_span.line
                ),
                Some(function.span),
            ));
        }
        names.insert(lookup_name, function.span);
    }
    Ok(())
}

fn validate_reference_source_expr(source: &Expr) -> Result<()> {
    if expr_is_nullsafe_chain(source) {
        return Err(nullsafe_reference_diagnostic(source.span()));
    }

    match source {
        Expr::Variable(_, _)
        | Expr::DynamicVariable { .. }
        | Expr::DynamicCall { .. }
        | Expr::MethodCall { .. }
        | Expr::DynamicMethodCall { .. }
        | Expr::ParentPropertyHookCall { .. }
        | Expr::PropertyFetch { .. }
        | Expr::DynamicPropertyFetch { .. }
        | Expr::StaticPropertyFetch { .. } => Ok(()),
        Expr::Call { name, span, .. }
            if is_modeled_internal_function_name(name)
                && !modeled_internal_has_by_ref_parameter(name) =>
        {
            Err(Diagnostic::new(
                "Cannot use result of built-in function in write context",
                Some(*span),
            ))
        }
        Expr::Call { .. } => Ok(()),
        Expr::Grouped { expr, .. } => validate_reference_source_expr(expr),
        Expr::ArrayAccess { .. } => validate_array_reference_lvalue_expr(
            source,
            "temporary array offset references are unsupported",
        ),
        Expr::ClassConstantFetch { span, .. } | Expr::DynamicClassConstantFetch { span, .. } => {
            Err(Diagnostic::parse_error(
                "Cannot use temporary expression in write context",
                Some(*span),
            ))
        }
        _ => Err(Diagnostic::new(
            "unsupported by-reference assignment target",
            Some(source.span()),
        )),
    }
}

fn validate_array_reference_lvalue_expr(expr: &Expr, temporary_message: &str) -> Result<()> {
    match expr {
        Expr::Variable(_, _) | Expr::PropertyFetch { .. } | Expr::DynamicPropertyFetch { .. } => {
            Ok(())
        }
        Expr::Grouped { expr, .. } => validate_array_reference_lvalue_expr(expr, temporary_message),
        Expr::ArrayAccess { array, index, span } => {
            if let Some(index) = index {
                reject_append_array_read(index)?;
            }
            match array.as_ref() {
                Expr::Variable(_, _)
                | Expr::PropertyFetch { .. }
                | Expr::DynamicPropertyFetch { .. }
                | Expr::Call { .. }
                | Expr::DynamicCall { .. }
                | Expr::MethodCall { .. }
                | Expr::DynamicMethodCall { .. }
                | Expr::ParentPropertyHookCall { .. } => Ok(()),
                Expr::Grouped { expr, .. } => match expr.as_ref() {
                    Expr::Variable(_, _)
                    | Expr::PropertyFetch { .. }
                    | Expr::DynamicPropertyFetch { .. }
                    | Expr::Call { .. }
                    | Expr::DynamicCall { .. }
                    | Expr::MethodCall { .. }
                    | Expr::DynamicMethodCall { .. }
                    | Expr::ParentPropertyHookCall { .. } => Ok(()),
                    Expr::ArrayAccess { .. } => {
                        validate_array_reference_lvalue_expr(expr.as_ref(), temporary_message)
                    }
                    _ => Err(Diagnostic::new(temporary_message, Some(*span))),
                },
                Expr::ArrayAccess { .. } => {
                    validate_array_reference_lvalue_expr(array.as_ref(), temporary_message)
                }
                _ => Err(Diagnostic::new(temporary_message, Some(*span))),
            }
        }
        _ => Err(Diagnostic::new(temporary_message, Some(expr.span()))),
    }
}

fn validate_by_reference_returns(functions: &[FunctionDecl]) -> Result<()> {
    for function in functions {
        if function.return_by_ref {
            validate_by_reference_returns_in_statements(&function.body, &function.name)?;
        }
    }
    Ok(())
}

fn validate_void_returns(functions: &[FunctionDecl]) -> Result<()> {
    for function in functions {
        if matches!(&function.return_type, Some(TypeHint::Void)) {
            validate_void_returns_in_statements(&function.body, FunctionLikeKind::Function)?;
        }
    }
    Ok(())
}

fn validate_never_returns(functions: &[FunctionDecl]) -> Result<()> {
    for function in functions {
        if matches!(&function.return_type, Some(TypeHint::Never)) {
            validate_never_returns_in_statements(&function.body, FunctionLikeKind::Function)?;
        }
    }
    Ok(())
}

fn validate_typed_returns_have_values(functions: &[FunctionDecl]) -> Result<()> {
    for function in functions {
        if let Some(return_type) = &function.return_type {
            validate_generator_return_type(&function.body, return_type, function.span)?;
            validate_typed_returns_have_values_in_statements(
                &function.body,
                return_type,
                FunctionLikeKind::Function,
            )?;
        }
    }
    Ok(())
}

fn validate_void_returns_in_statements(
    statements: &[Statement],
    kind: FunctionLikeKind,
) -> Result<()> {
    for statement in statements {
        match statement {
            Statement::Return { value, span } => {
                if let Some(value) = value {
                    let message = if value_is_null_literal(value) {
                        format!(
                            "A void {} must not return a value (did you mean \"return;\" instead of \"return null;\"?)",
                            kind.label()
                        )
                    } else {
                        format!("A void {} must not return a value", kind.label())
                    };
                    return Err(Diagnostic::new(message, Some(*span)));
                }
            }
            Statement::If {
                then_body,
                else_body,
                ..
            } => {
                validate_void_returns_in_statements(then_body, kind)?;
                validate_void_returns_in_statements(else_body, kind)?;
            }
            Statement::Block { statements, .. } => {
                validate_void_returns_in_statements(statements, kind)?;
            }
            Statement::While { body, .. }
            | Statement::DoWhile { body, .. }
            | Statement::Foreach { body, .. } => {
                validate_void_returns_in_statements(body, kind)?;
            }
            Statement::For {
                initializers,
                updates,
                body,
                ..
            } => {
                validate_void_returns_in_statements(initializers, kind)?;
                validate_void_returns_in_statements(updates, kind)?;
                validate_void_returns_in_statements(body, kind)?;
            }
            Statement::Try {
                body,
                catches,
                finally_body,
                ..
            } => {
                validate_void_returns_in_statements(body, kind)?;
                for catch in catches {
                    validate_void_returns_in_statements(&catch.body, kind)?;
                }
                validate_void_returns_in_statements(finally_body, kind)?;
            }
            Statement::Switch { cases, .. } => {
                for case in cases {
                    validate_void_returns_in_statements(&case.body, kind)?;
                }
            }
            _ => {}
        }
    }
    Ok(())
}

fn validate_typed_returns_have_values_in_statements(
    statements: &[Statement],
    return_type: &TypeHint,
    kind: FunctionLikeKind,
) -> Result<()> {
    if matches!(return_type, TypeHint::Void | TypeHint::Never)
        || statements_contain_yield(statements)
    {
        return Ok(());
    }
    for statement in statements {
        match statement {
            Statement::Return { value: None, span } => {
                let mut message =
                    format!("A {} with return type must return a value", kind.label());
                if type_hint_accepts_null_default(return_type) {
                    message.push_str(" (did you mean \"return null;\" instead of \"return;\"?)");
                }
                return Err(Diagnostic::new(message, Some(*span)));
            }
            Statement::If {
                then_body,
                else_body,
                ..
            } => {
                validate_typed_returns_have_values_in_statements(then_body, return_type, kind)?;
                validate_typed_returns_have_values_in_statements(else_body, return_type, kind)?;
            }
            Statement::Block { statements, .. } => {
                validate_typed_returns_have_values_in_statements(statements, return_type, kind)?;
            }
            Statement::While { body, .. }
            | Statement::DoWhile { body, .. }
            | Statement::Foreach { body, .. } => {
                validate_typed_returns_have_values_in_statements(body, return_type, kind)?;
            }
            Statement::For {
                initializers,
                updates,
                body,
                ..
            } => {
                validate_typed_returns_have_values_in_statements(initializers, return_type, kind)?;
                validate_typed_returns_have_values_in_statements(updates, return_type, kind)?;
                validate_typed_returns_have_values_in_statements(body, return_type, kind)?;
            }
            Statement::Try {
                body,
                catches,
                finally_body,
                ..
            } => {
                validate_typed_returns_have_values_in_statements(body, return_type, kind)?;
                for catch in catches {
                    validate_typed_returns_have_values_in_statements(
                        &catch.body,
                        return_type,
                        kind,
                    )?;
                }
                validate_typed_returns_have_values_in_statements(finally_body, return_type, kind)?;
            }
            Statement::Switch { cases, .. } => {
                for case in cases {
                    validate_typed_returns_have_values_in_statements(
                        &case.body,
                        return_type,
                        kind,
                    )?;
                }
            }
            _ => {}
        }
    }
    Ok(())
}

fn validate_never_returns_in_statements(
    statements: &[Statement],
    kind: FunctionLikeKind,
) -> Result<()> {
    for statement in statements {
        match statement {
            Statement::Return { span, .. } => {
                return Err(Diagnostic::new(
                    format!("A never-returning {} must not return", kind.label()),
                    Some(*span),
                ));
            }
            Statement::If {
                then_body,
                else_body,
                ..
            } => {
                validate_never_returns_in_statements(then_body, kind)?;
                validate_never_returns_in_statements(else_body, kind)?;
            }
            Statement::Block { statements, .. } => {
                validate_never_returns_in_statements(statements, kind)?;
            }
            Statement::While { body, .. }
            | Statement::DoWhile { body, .. }
            | Statement::Foreach { body, .. } => {
                validate_never_returns_in_statements(body, kind)?;
            }
            Statement::For {
                initializers,
                updates,
                body,
                ..
            } => {
                validate_never_returns_in_statements(initializers, kind)?;
                validate_never_returns_in_statements(updates, kind)?;
                validate_never_returns_in_statements(body, kind)?;
            }
            Statement::Try {
                body,
                catches,
                finally_body,
                ..
            } => {
                validate_never_returns_in_statements(body, kind)?;
                for catch in catches {
                    validate_never_returns_in_statements(&catch.body, kind)?;
                }
                validate_never_returns_in_statements(finally_body, kind)?;
            }
            Statement::Switch { cases, .. } => {
                for case in cases {
                    validate_never_returns_in_statements(&case.body, kind)?;
                }
            }
            _ => {}
        }
    }
    Ok(())
}

fn validate_generator_return_type(
    statements: &[Statement],
    return_type: &TypeHint,
    span: SourceSpan,
) -> Result<()> {
    if statements_contain_yield(statements) && !type_hint_accepts_generator_return(return_type) {
        return Err(Diagnostic::new(
            format!(
                "Generator return type must be a supertype of Generator, {} given",
                type_hint_display(return_type)
            ),
            Some(span),
        ));
    }
    Ok(())
}

fn type_hint_accepts_generator_return(type_hint: &TypeHint) -> bool {
    match type_hint {
        TypeHint::Mixed | TypeHint::Object | TypeHint::Iterable => true,
        TypeHint::Class(name) => matches!(
            name.rsplit('\\')
                .next()
                .unwrap_or(name)
                .to_ascii_lowercase()
                .as_str(),
            "generator" | "iterator" | "traversable"
        ),
        TypeHint::Nullable(inner) => type_hint_accepts_generator_return(inner),
        TypeHint::Union(types) => types.iter().any(type_hint_accepts_generator_return),
        _ => false,
    }
}

fn value_is_null_literal(value: &Expr) -> bool {
    match value {
        Expr::Null(_) => true,
        Expr::Grouped { expr, .. } => value_is_null_literal(expr),
        _ => false,
    }
}

fn statements_contain_yield(statements: &[Statement]) -> bool {
    statements.iter().any(statement_contains_yield)
}

fn statement_contains_yield(statement: &Statement) -> bool {
    match statement {
        Statement::Assign { value, .. } | Statement::ArrayAssign { value, .. } => {
            expr_contains_yield(value)
        }
        Statement::AssignRef { source, .. } | Statement::ArrayAssignRef { source, .. } => {
            expr_contains_yield(source)
        }
        Statement::Increment { target, .. } => inc_dec_target_contains_yield(target),
        Statement::Unset { targets, .. } => targets.iter().any(unset_target_contains_yield),
        Statement::Static { declarations, .. } => declarations
            .iter()
            .any(|declaration| declaration.value.as_ref().is_some_and(expr_contains_yield)),
        Statement::Call { arguments, .. }
        | Statement::Echo {
            expressions: arguments,
            ..
        } => arguments.iter().any(expr_contains_yield),
        Statement::Print { expression, .. } | Statement::Expression { expression, .. } => {
            expr_contains_yield(expression)
        }
        Statement::Const { declarations, .. } => declarations
            .iter()
            .any(|declaration| expr_contains_yield(&declaration.value)),
        Statement::Block { statements, .. } => statements_contain_yield(statements),
        Statement::If {
            condition,
            then_body,
            else_body,
            ..
        } => {
            expr_contains_yield(condition)
                || statements_contain_yield(then_body)
                || statements_contain_yield(else_body)
        }
        Statement::While {
            condition, body, ..
        } => expr_contains_yield(condition) || statements_contain_yield(body),
        Statement::DoWhile {
            body, condition, ..
        } => statements_contain_yield(body) || expr_contains_yield(condition),
        Statement::For {
            initializers,
            conditions,
            updates,
            body,
            ..
        } => {
            statements_contain_yield(initializers)
                || conditions.iter().any(expr_contains_yield)
                || statements_contain_yield(updates)
                || statements_contain_yield(body)
        }
        Statement::Foreach {
            iterable,
            key,
            value,
            body,
            ..
        } => {
            expr_contains_yield(iterable)
                || key.as_ref().is_some_and(assignment_target_contains_yield)
                || assignment_target_contains_yield(value)
                || statements_contain_yield(body)
        }
        Statement::Switch {
            expression, cases, ..
        } => {
            expr_contains_yield(expression)
                || cases.iter().any(|case| {
                    case.condition.as_ref().is_some_and(expr_contains_yield)
                        || statements_contain_yield(&case.body)
                })
        }
        Statement::Return {
            value: Some(value), ..
        }
        | Statement::Exit {
            value: Some(value), ..
        }
        | Statement::Throw { value, .. } => expr_contains_yield(value),
        Statement::Try {
            body,
            catches,
            finally_body,
            ..
        } => {
            statements_contain_yield(body)
                || catches
                    .iter()
                    .any(|catch| statements_contain_yield(&catch.body))
                || statements_contain_yield(finally_body)
        }
        Statement::Empty { .. }
        | Statement::ClassDeclaration { .. }
        | Statement::TraitDeclaration { .. }
        | Statement::FunctionDeclaration { .. }
        | Statement::Global { .. }
        | Statement::Break { .. }
        | Statement::Continue { .. }
        | Statement::Return { value: None, .. }
        | Statement::Exit { value: None, .. }
        | Statement::Label { .. }
        | Statement::Goto { .. }
        | Statement::InlineHtml { .. } => false,
    }
}

fn expr_contains_yield(expr: &Expr) -> bool {
    match expr {
        Expr::Yield { .. } | Expr::YieldFrom { .. } => true,
        Expr::AnonymousFunction(_) => false,
        Expr::DynamicVariable { name, .. }
        | Expr::DynamicStaticPropertyNameFetch { name, .. }
        | Expr::FirstClassCallable { callable: name, .. }
        | Expr::DynamicClassNameFetch { receiver: name, .. }
        | Expr::Print {
            expression: name, ..
        }
        | Expr::Include { path: name, .. }
        | Expr::Throw { value: name, .. }
        | Expr::Unary { expr: name, .. }
        | Expr::Cast { expr: name, .. }
        | Expr::Grouped { expr: name, .. }
        | Expr::PipeValue { expr: name, .. } => expr_contains_yield(name),
        Expr::Clone {
            expr,
            with_properties,
            ..
        } => {
            expr_contains_yield(expr)
                || with_properties
                    .as_ref()
                    .is_some_and(|value| expr_contains_yield(value))
        }
        Expr::Exit { value, .. } => value
            .as_ref()
            .is_some_and(|value| expr_contains_yield(value)),
        Expr::IncDec { target, .. } => inc_dec_target_contains_yield(target),
        Expr::Assign { target, value, .. } => {
            assignment_target_contains_yield(target) || expr_contains_yield(value)
        }
        Expr::AssignRef { target, source, .. } => {
            assignment_target_contains_yield(target) || expr_contains_yield(source)
        }
        Expr::Call { arguments, .. } | Expr::NewObject { arguments, .. } => {
            arguments.iter().any(expr_contains_yield)
        }
        Expr::ParentPropertyHookCall { arguments, .. } => arguments.iter().any(expr_contains_yield),
        Expr::DynamicCall {
            callee, arguments, ..
        } => expr_contains_yield(callee) || arguments.iter().any(expr_contains_yield),
        Expr::MethodCall {
            receiver,
            arguments,
            ..
        } => expr_contains_yield(receiver) || arguments.iter().any(expr_contains_yield),
        Expr::DynamicMethodCall {
            receiver,
            name,
            arguments,
            ..
        } => {
            expr_contains_yield(receiver)
                || expr_contains_yield(name)
                || arguments.iter().any(expr_contains_yield)
        }
        Expr::DynamicNewObject {
            class_name,
            arguments,
            ..
        } => expr_contains_yield(class_name) || arguments.iter().any(expr_contains_yield),
        Expr::PropertyFetch { receiver, .. }
        | Expr::NullsafePropertyFetch { receiver, .. }
        | Expr::DynamicStaticPropertyFetch { receiver, .. } => expr_contains_yield(receiver),
        Expr::DynamicClassConstantFetch { receiver, name, .. } => {
            receiver
                .as_ref()
                .is_some_and(|receiver| expr_contains_yield(receiver))
                || expr_contains_yield(name)
        }
        Expr::DynamicPropertyFetch { receiver, name, .. } => {
            expr_contains_yield(receiver) || expr_contains_yield(name)
        }
        Expr::InstanceOf { expr, target, .. } => {
            expr_contains_yield(expr)
                || matches!(target, InstanceOfTarget::Expr(target) if expr_contains_yield(target))
        }
        Expr::Match { subject, arms, .. } => {
            expr_contains_yield(subject)
                || arms.iter().any(|arm| {
                    arm.conditions.iter().any(expr_contains_yield)
                        || expr_contains_yield(&arm.value)
                })
        }
        Expr::Array { elements, .. } => elements.iter().any(array_element_contains_yield),
        Expr::List(list) => list.elements.iter().any(list_expr_element_contains_yield),
        Expr::ArrayAccess { array, index, .. } => {
            expr_contains_yield(array)
                || index
                    .as_ref()
                    .is_some_and(|index| expr_contains_yield(index))
        }
        Expr::Isset { targets, .. } => targets.iter().any(expr_contains_yield),
        Expr::Empty { target, .. } => expr_contains_yield(target),
        Expr::Binary { left, right, .. } => expr_contains_yield(left) || expr_contains_yield(right),
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => {
            expr_contains_yield(condition)
                || if_true
                    .as_ref()
                    .is_some_and(|if_true| expr_contains_yield(if_true))
                || expr_contains_yield(if_false)
        }
        Expr::String(_, _)
        | Expr::InterpolatedString(_, _)
        | Expr::ShellExec { .. }
        | Expr::Int(_, _)
        | Expr::Float(_, _)
        | Expr::Bool(_, _)
        | Expr::Null(_)
        | Expr::Variable(_, _)
        | Expr::Constant(_, _)
        | Expr::MagicConstant(_, _)
        | Expr::StaticPropertyFetch { .. }
        | Expr::ClassConstantFetch { .. } => false,
    }
}

fn array_element_contains_yield(element: &ArrayElement) -> bool {
    element.key.as_ref().is_some_and(expr_contains_yield)
        || match &element.value {
            ArrayElementValue::Hole(_) => false,
            ArrayElementValue::Value(value) | ArrayElementValue::Unpack(value) => {
                expr_contains_yield(value)
            }
            ArrayElementValue::Reference(target) => reference_target_contains_yield(target),
        }
}

fn list_expr_element_contains_yield(element: &ListExprElement) -> bool {
    element.key.as_ref().is_some_and(expr_contains_yield)
        || element.target.as_ref().is_some_and(|target| match target {
            ListExprElementTarget::Value(value) => expr_contains_yield(value),
            ListExprElementTarget::Reference(target) => reference_target_contains_yield(target),
        })
}

fn assignment_target_contains_yield(target: &AssignmentTarget) -> bool {
    match target {
        AssignmentTarget::DynamicVariable { name, .. } => expr_contains_yield(name),
        AssignmentTarget::DynamicArrayDim {
            name, dimensions, ..
        } => expr_contains_yield(name) || dimensions.iter().flatten().any(expr_contains_yield),
        AssignmentTarget::ArrayDim(target) => {
            target.dimensions.iter().flatten().any(expr_contains_yield)
        }
        AssignmentTarget::PropertyArrayDim {
            receiver,
            dimensions,
            ..
        }
        | AssignmentTarget::ValueArrayDim {
            array: receiver,
            dimensions,
            ..
        }
        | AssignmentTarget::DynamicStaticPropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => expr_contains_yield(receiver) || dimensions.iter().flatten().any(expr_contains_yield),
        AssignmentTarget::Property { receiver, .. }
        | AssignmentTarget::DynamicStaticProperty { receiver, .. } => expr_contains_yield(receiver),
        AssignmentTarget::DynamicProperty { receiver, name, .. } => {
            expr_contains_yield(receiver) || expr_contains_yield(name)
        }
        AssignmentTarget::DynamicPropertyArrayDim {
            receiver,
            name,
            dimensions,
            ..
        } => {
            expr_contains_yield(receiver)
                || expr_contains_yield(name)
                || dimensions.iter().flatten().any(expr_contains_yield)
        }
        AssignmentTarget::DynamicStaticPropertyName { name, .. } => expr_contains_yield(name),
        AssignmentTarget::List(list) => list_assignment_target_contains_yield(list),
        AssignmentTarget::Variable { .. }
        | AssignmentTarget::StaticPropertyArrayDim { .. }
        | AssignmentTarget::StaticProperty { .. } => false,
    }
}

fn list_assignment_target_contains_yield(target: &ListAssignmentTarget) -> bool {
    target.elements.iter().any(|element| {
        element.key.as_ref().is_some_and(expr_contains_yield)
            || match &element.target {
                ListAssignmentElementTarget::Value(target) => {
                    assignment_target_contains_yield(target)
                }
                ListAssignmentElementTarget::Reference(target) => {
                    reference_target_contains_yield(target)
                }
            }
    })
}

fn reference_target_contains_yield(target: &ReferenceTarget) -> bool {
    match target {
        ReferenceTarget::DynamicVariable { name, .. } => expr_contains_yield(name),
        ReferenceTarget::ArrayDim(target) => {
            target.dimensions.iter().flatten().any(expr_contains_yield)
        }
        ReferenceTarget::PropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => expr_contains_yield(receiver) || dimensions.iter().flatten().any(expr_contains_yield),
        ReferenceTarget::Property { receiver, .. } => expr_contains_yield(receiver),
        ReferenceTarget::DynamicProperty { receiver, name, .. } => {
            expr_contains_yield(receiver) || expr_contains_yield(name)
        }
        ReferenceTarget::Variable { .. } => false,
    }
}

fn inc_dec_target_contains_yield(target: &IncDecTarget) -> bool {
    match target {
        IncDecTarget::DynamicVariable { name, .. } => expr_contains_yield(name),
        IncDecTarget::DynamicArrayDim {
            name, dimensions, ..
        } => expr_contains_yield(name) || dimensions.iter().flatten().any(expr_contains_yield),
        IncDecTarget::ArrayDim(target) => {
            target.dimensions.iter().flatten().any(expr_contains_yield)
        }
        IncDecTarget::ValueArrayDim {
            array, dimensions, ..
        } => expr_contains_yield(array) || dimensions.iter().flatten().any(expr_contains_yield),
        IncDecTarget::PropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => expr_contains_yield(receiver) || dimensions.iter().flatten().any(expr_contains_yield),
        IncDecTarget::StaticPropertyArrayDim { dimensions, .. } => {
            dimensions.iter().flatten().any(expr_contains_yield)
        }
        IncDecTarget::Property { receiver, .. } => expr_contains_yield(receiver),
        IncDecTarget::DynamicProperty { receiver, name, .. } => {
            expr_contains_yield(receiver) || expr_contains_yield(name)
        }
        IncDecTarget::DynamicStaticPropertyName { name, .. } => expr_contains_yield(name),
        IncDecTarget::Variable { .. } | IncDecTarget::StaticProperty { .. } => false,
    }
}

fn unset_target_contains_yield(target: &UnsetTarget) -> bool {
    match target {
        UnsetTarget::DynamicVariable { name, .. } => expr_contains_yield(name),
        UnsetTarget::DynamicArrayDim {
            name, dimensions, ..
        } => expr_contains_yield(name) || dimensions.iter().any(expr_contains_yield),
        UnsetTarget::ValueArrayDim {
            array, dimensions, ..
        } => expr_contains_yield(array) || dimensions.iter().any(expr_contains_yield),
        UnsetTarget::PropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => expr_contains_yield(receiver) || dimensions.iter().any(expr_contains_yield),
        UnsetTarget::StaticPropertyArrayDim { dimensions, .. } => {
            dimensions.iter().any(expr_contains_yield)
        }
        UnsetTarget::DynamicStaticPropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => expr_contains_yield(receiver) || dimensions.iter().any(expr_contains_yield),
        UnsetTarget::Property { receiver, .. } => expr_contains_yield(receiver),
        UnsetTarget::DynamicProperty { receiver, name, .. } => {
            expr_contains_yield(receiver) || expr_contains_yield(name)
        }
        UnsetTarget::DynamicStaticPropertyName { name, .. } => expr_contains_yield(name),
        UnsetTarget::ArrayDim(target) => {
            target.dimensions.iter().flatten().any(expr_contains_yield)
        }
        UnsetTarget::Variable { .. } | UnsetTarget::StaticProperty { .. } => false,
    }
}

fn validate_anonymous_functions_in_statements(
    statements: &[Statement],
    functions: &[FunctionDecl],
) -> Result<()> {
    for statement in statements {
        match statement {
            Statement::Assign { value, .. }
            | Statement::AssignRef { source: value, .. }
            | Statement::ArrayAssign { value, .. }
            | Statement::ArrayAssignRef { source: value, .. }
            | Statement::Print {
                expression: value, ..
            }
            | Statement::Expression {
                expression: value, ..
            }
            | Statement::Return {
                value: Some(value), ..
            }
            | Statement::Exit {
                value: Some(value), ..
            }
            | Statement::Throw { value, .. } => {
                validate_anonymous_functions_in_expr(value, functions)?;
            }
            Statement::Call { arguments, .. }
            | Statement::Echo {
                expressions: arguments,
                ..
            } => {
                for argument in arguments {
                    validate_anonymous_functions_in_expr(argument, functions)?;
                }
            }
            Statement::Const { declarations, .. } => {
                for declaration in declarations {
                    validate_anonymous_functions_in_expr(&declaration.value, functions)?;
                }
            }
            Statement::Static { declarations, .. } => {
                for declaration in declarations {
                    if let Some(value) = &declaration.value {
                        validate_anonymous_functions_in_expr(value, functions)?;
                    }
                }
            }
            Statement::If {
                condition,
                then_body,
                else_body,
                ..
            } => {
                validate_anonymous_functions_in_expr(condition, functions)?;
                validate_anonymous_functions_in_statements(then_body, functions)?;
                validate_anonymous_functions_in_statements(else_body, functions)?;
            }
            Statement::Block { statements, .. } => {
                validate_anonymous_functions_in_statements(statements, functions)?;
            }
            Statement::While {
                condition, body, ..
            }
            | Statement::DoWhile {
                condition, body, ..
            } => {
                validate_anonymous_functions_in_expr(condition, functions)?;
                validate_anonymous_functions_in_statements(body, functions)?;
            }
            Statement::For {
                initializers,
                conditions,
                updates,
                body,
                ..
            } => {
                validate_anonymous_functions_in_statements(initializers, functions)?;
                for condition in conditions {
                    validate_anonymous_functions_in_expr(condition, functions)?;
                }
                validate_anonymous_functions_in_statements(updates, functions)?;
                validate_anonymous_functions_in_statements(body, functions)?;
            }
            Statement::Foreach { iterable, body, .. } => {
                validate_anonymous_functions_in_expr(iterable, functions)?;
                validate_anonymous_functions_in_statements(body, functions)?;
            }
            Statement::Switch {
                expression, cases, ..
            } => {
                validate_anonymous_functions_in_expr(expression, functions)?;
                for case in cases {
                    if let Some(condition) = &case.condition {
                        validate_anonymous_functions_in_expr(condition, functions)?;
                    }
                    validate_anonymous_functions_in_statements(&case.body, functions)?;
                }
            }
            Statement::Try {
                body,
                catches,
                finally_body,
                ..
            } => {
                validate_anonymous_functions_in_statements(body, functions)?;
                for catch in catches {
                    validate_anonymous_functions_in_statements(&catch.body, functions)?;
                }
                validate_anonymous_functions_in_statements(finally_body, functions)?;
            }
            Statement::Return { value: None, .. }
            | Statement::Exit { value: None, .. }
            | Statement::Empty { .. }
            | Statement::ClassDeclaration { .. }
            | Statement::TraitDeclaration { .. }
            | Statement::FunctionDeclaration { .. }
            | Statement::Unset { .. }
            | Statement::Global { .. }
            | Statement::Break { .. }
            | Statement::Continue { .. }
            | Statement::Label { .. }
            | Statement::Goto { .. }
            | Statement::InlineHtml { .. } => {}
            Statement::Increment { target, .. } => {
                validate_anonymous_functions_in_inc_dec_target(target, functions)?;
            }
        }
    }
    Ok(())
}

fn validate_anonymous_functions_in_inc_dec_target(
    target: &IncDecTarget,
    functions: &[FunctionDecl],
) -> Result<()> {
    match target {
        IncDecTarget::Variable { .. } => Ok(()),
        IncDecTarget::DynamicVariable { name, .. } => {
            validate_anonymous_functions_in_expr(name, functions)
        }
        IncDecTarget::DynamicArrayDim {
            name, dimensions, ..
        } => {
            validate_anonymous_functions_in_expr(name, functions)?;
            for dimension in dimensions {
                if let Some(dimension) = dimension {
                    validate_anonymous_functions_in_expr(dimension, functions)?;
                }
            }
            Ok(())
        }
        IncDecTarget::ArrayDim(target) => {
            for dimension in &target.dimensions {
                if let Some(dimension) = dimension {
                    validate_anonymous_functions_in_expr(dimension, functions)?;
                }
            }
            Ok(())
        }
        IncDecTarget::ValueArrayDim {
            array, dimensions, ..
        } => {
            validate_anonymous_functions_in_expr(array, functions)?;
            for dimension in dimensions {
                if let Some(dimension) = dimension {
                    validate_anonymous_functions_in_expr(dimension, functions)?;
                }
            }
            Ok(())
        }
        IncDecTarget::PropertyArrayDim {
            receiver,
            dimensions,
            ..
        } => {
            validate_anonymous_functions_in_expr(receiver, functions)?;
            for dimension in dimensions {
                if let Some(dimension) = dimension {
                    validate_anonymous_functions_in_expr(dimension, functions)?;
                }
            }
            Ok(())
        }
        IncDecTarget::StaticPropertyArrayDim { dimensions, .. } => {
            for dimension in dimensions {
                if let Some(dimension) = dimension {
                    validate_anonymous_functions_in_expr(dimension, functions)?;
                }
            }
            Ok(())
        }
        IncDecTarget::Property { receiver, .. } => {
            validate_anonymous_functions_in_expr(receiver, functions)
        }
        IncDecTarget::DynamicProperty { receiver, name, .. } => {
            validate_anonymous_functions_in_expr(receiver, functions)?;
            validate_anonymous_functions_in_expr(name, functions)
        }
        IncDecTarget::StaticProperty { .. } => Ok(()),
        IncDecTarget::DynamicStaticPropertyName { name, .. } => {
            validate_anonymous_functions_in_expr(name, functions)
        }
    }
}

fn validate_anonymous_functions_in_expr(expr: &Expr, functions: &[FunctionDecl]) -> Result<()> {
    match expr {
        Expr::AnonymousFunction(function) => {
            if function.return_by_ref {
                validate_by_reference_returns_in_statements(&function.body, "{closure}")?;
            }
            if matches!(&function.return_type, Some(TypeHint::Void)) {
                validate_void_returns_in_statements(&function.body, FunctionLikeKind::Function)?;
            }
            if !function.is_arrow && matches!(&function.return_type, Some(TypeHint::Never)) {
                validate_never_returns_in_statements(&function.body, FunctionLikeKind::Function)?;
            }
            if !function.is_arrow {
                if let Some(return_type) = &function.return_type {
                    validate_generator_return_type(&function.body, return_type, function.span)?;
                    validate_typed_returns_have_values_in_statements(
                        &function.body,
                        return_type,
                        FunctionLikeKind::Function,
                    )?;
                }
            }
            validate_anonymous_functions_in_statements(&function.body, functions)?;
            validate_reference_assignment_sources(&function.body, functions)?;
            validate_goto_labels(&function.body)?;
        }
        Expr::IncDec { target, .. } => {
            validate_anonymous_functions_in_inc_dec_target(target, functions)?;
        }
        Expr::Assign { value, .. } => {
            validate_anonymous_functions_in_expr(value, functions)?;
        }
        Expr::AssignRef { source, .. } => {
            validate_anonymous_functions_in_expr(source, functions)?;
        }
        Expr::Call { arguments, .. }
        | Expr::DynamicCall { arguments, .. }
        | Expr::MethodCall { arguments, .. }
        | Expr::DynamicMethodCall { arguments, .. }
        | Expr::ParentPropertyHookCall { arguments, .. }
        | Expr::NewObject { arguments, .. } => {
            for argument in arguments {
                validate_anonymous_functions_in_expr(argument, functions)?;
            }
            if let Expr::DynamicCall { callee, .. } = expr {
                validate_anonymous_functions_in_expr(callee, functions)?;
            }
            if let Expr::MethodCall { receiver, .. } = expr {
                validate_anonymous_functions_in_expr(receiver, functions)?;
            }
            if let Expr::DynamicMethodCall { receiver, name, .. } = expr {
                validate_anonymous_functions_in_expr(receiver, functions)?;
                validate_anonymous_functions_in_expr(name, functions)?;
            }
        }
        Expr::DynamicNewObject {
            class_name,
            arguments,
            ..
        } => {
            validate_anonymous_functions_in_expr(class_name, functions)?;
            for argument in arguments {
                validate_anonymous_functions_in_expr(argument, functions)?;
            }
        }
        Expr::FirstClassCallable { callable, .. } => {
            validate_anonymous_functions_in_expr(callable, functions)?;
        }
        Expr::PropertyFetch { receiver, .. } | Expr::NullsafePropertyFetch { receiver, .. } => {
            validate_anonymous_functions_in_expr(receiver, functions)?;
        }
        Expr::DynamicPropertyFetch { receiver, name, .. } => {
            validate_anonymous_functions_in_expr(receiver, functions)?;
            validate_anonymous_functions_in_expr(name, functions)?;
        }
        Expr::DynamicStaticPropertyNameFetch { name, .. } => {
            validate_anonymous_functions_in_expr(name, functions)?;
        }
        Expr::DynamicStaticPropertyFetch { receiver, .. } => {
            validate_anonymous_functions_in_expr(receiver, functions)?;
        }
        Expr::DynamicClassNameFetch { receiver, .. } => {
            validate_anonymous_functions_in_expr(receiver, functions)?;
        }
        Expr::DynamicClassConstantFetch { receiver, name, .. } => {
            if let Some(receiver) = receiver {
                validate_anonymous_functions_in_expr(receiver, functions)?;
            }
            validate_anonymous_functions_in_expr(name, functions)?;
        }
        Expr::InstanceOf { expr, target, .. } => {
            validate_anonymous_functions_in_expr(expr, functions)?;
            if let InstanceOfTarget::Expr(target) = target {
                validate_anonymous_functions_in_expr(target, functions)?;
            }
        }
        Expr::Clone {
            expr,
            with_properties,
            ..
        } => {
            validate_anonymous_functions_in_expr(expr, functions)?;
            if let Some(with_properties) = with_properties {
                validate_anonymous_functions_in_expr(with_properties, functions)?;
            }
        }
        Expr::StaticPropertyFetch { .. } | Expr::ClassConstantFetch { .. } => {}
        Expr::Array { elements, .. } => {
            for element in elements {
                if let Some(key) = &element.key {
                    validate_anonymous_functions_in_expr(key, functions)?;
                }
                match &element.value {
                    ArrayElementValue::Hole(_) => {}
                    ArrayElementValue::Value(value) | ArrayElementValue::Unpack(value) => {
                        validate_anonymous_functions_in_expr(value, functions)?;
                    }
                    ArrayElementValue::Reference(_) => {}
                }
            }
        }
        Expr::List(list) => {
            for element in &list.elements {
                if let Some(key) = &element.key {
                    validate_anonymous_functions_in_expr(key, functions)?;
                }
                if let Some(ListExprElementTarget::Value(value)) = &element.target {
                    validate_anonymous_functions_in_expr(value, functions)?;
                }
            }
        }
        Expr::ArrayAccess { array, index, .. } => {
            validate_anonymous_functions_in_expr(array, functions)?;
            if let Some(index) = index {
                validate_anonymous_functions_in_expr(index, functions)?;
            }
        }
        Expr::Isset { targets, .. } => {
            for target in targets {
                validate_anonymous_functions_in_expr(target, functions)?;
            }
        }
        Expr::Empty { target, .. } => {
            validate_anonymous_functions_in_expr(target, functions)?;
        }
        Expr::Print {
            expression: expr, ..
        }
        | Expr::DynamicVariable { name: expr, .. }
        | Expr::Include { path: expr, .. }
        | Expr::Throw { value: expr, .. }
        | Expr::Unary { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Grouped { expr, .. }
        | Expr::PipeValue { expr, .. } => validate_anonymous_functions_in_expr(expr, functions)?,
        Expr::Exit { value, .. } => {
            if let Some(value) = value {
                validate_anonymous_functions_in_expr(value, functions)?;
            }
        }
        Expr::YieldFrom { expr, .. } => validate_anonymous_functions_in_expr(expr, functions)?,
        Expr::Yield { key, value, .. } => {
            if let Some(key) = key {
                validate_anonymous_functions_in_expr(key, functions)?;
            }
            if let Some(value) = value {
                validate_anonymous_functions_in_expr(value, functions)?;
            }
        }
        Expr::Binary { left, right, .. } => {
            validate_anonymous_functions_in_expr(left, functions)?;
            validate_anonymous_functions_in_expr(right, functions)?;
        }
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => {
            validate_anonymous_functions_in_expr(condition, functions)?;
            if let Some(if_true) = if_true {
                validate_anonymous_functions_in_expr(if_true, functions)?;
            }
            validate_anonymous_functions_in_expr(if_false, functions)?;
        }
        Expr::Match { subject, arms, .. } => {
            validate_anonymous_functions_in_expr(subject, functions)?;
            for arm in arms {
                for condition in &arm.conditions {
                    validate_anonymous_functions_in_expr(condition, functions)?;
                }
                validate_anonymous_functions_in_expr(&arm.value, functions)?;
            }
        }
        Expr::String(_, _)
        | Expr::InterpolatedString(_, _)
        | Expr::ShellExec { .. }
        | Expr::Int(_, _)
        | Expr::Float(_, _)
        | Expr::Bool(_, _)
        | Expr::Null(_)
        | Expr::Variable(_, _)
        | Expr::Constant(_, _)
        | Expr::MagicConstant(_, _) => {}
    }
    Ok(())
}

fn validate_by_reference_returns_in_statements(
    statements: &[Statement],
    function_name: &str,
) -> Result<()> {
    for statement in statements {
        match statement {
            Statement::Return { value, .. } => {
                if let Some(value) = value {
                    validate_by_reference_return_value(value, function_name)?;
                }
            }
            Statement::If {
                then_body,
                else_body,
                ..
            } => {
                validate_by_reference_returns_in_statements(then_body, function_name)?;
                validate_by_reference_returns_in_statements(else_body, function_name)?;
            }
            Statement::Block { statements, .. } => {
                validate_by_reference_returns_in_statements(statements, function_name)?;
            }
            Statement::While { body, .. }
            | Statement::DoWhile { body, .. }
            | Statement::Foreach { body, .. } => {
                validate_by_reference_returns_in_statements(body, function_name)?;
            }
            Statement::For {
                initializers,
                updates,
                body,
                ..
            } => {
                validate_by_reference_returns_in_statements(initializers, function_name)?;
                validate_by_reference_returns_in_statements(updates, function_name)?;
                validate_by_reference_returns_in_statements(body, function_name)?;
            }
            Statement::Try {
                body,
                catches,
                finally_body,
                ..
            } => {
                validate_by_reference_returns_in_statements(body, function_name)?;
                for catch in catches {
                    validate_by_reference_returns_in_statements(&catch.body, function_name)?;
                }
                validate_by_reference_returns_in_statements(finally_body, function_name)?;
            }
            Statement::Switch { cases, .. } => {
                for case in cases {
                    validate_by_reference_returns_in_statements(&case.body, function_name)?;
                }
            }
            _ => {}
        }
    }
    Ok(())
}

fn validate_reference_assignment_sources(
    statements: &[Statement],
    functions: &[FunctionDecl],
) -> Result<()> {
    for statement in statements {
        match statement {
            Statement::AssignRef { source, .. } | Statement::ArrayAssignRef { source, .. } => {
                validate_reference_assignment_source_expr(source, functions)?;
            }
            Statement::If {
                then_body,
                else_body,
                ..
            } => {
                validate_reference_assignment_sources(then_body, functions)?;
                validate_reference_assignment_sources(else_body, functions)?;
            }
            Statement::Block { statements, .. } => {
                validate_reference_assignment_sources(statements, functions)?;
            }
            Statement::While { body, .. }
            | Statement::DoWhile { body, .. }
            | Statement::Foreach { body, .. } => {
                validate_reference_assignment_sources(body, functions)?;
            }
            Statement::For {
                initializers,
                updates,
                body,
                ..
            } => {
                validate_reference_assignment_sources(initializers, functions)?;
                validate_reference_assignment_sources(updates, functions)?;
                validate_reference_assignment_sources(body, functions)?;
            }
            Statement::Try {
                body,
                catches,
                finally_body,
                ..
            } => {
                validate_reference_assignment_sources(body, functions)?;
                for catch in catches {
                    validate_reference_assignment_sources(&catch.body, functions)?;
                }
                validate_reference_assignment_sources(finally_body, functions)?;
            }
            Statement::Switch { cases, .. } => {
                for case in cases {
                    validate_reference_assignment_sources(&case.body, functions)?;
                }
            }
            _ => {}
        }
    }
    Ok(())
}

fn validate_reference_assignment_source_expr(
    source: &Expr,
    functions: &[FunctionDecl],
) -> Result<()> {
    match source {
        Expr::Grouped { expr, .. } => validate_reference_assignment_source_expr(expr, functions),
        Expr::Print { expression, .. } => {
            validate_reference_assignment_source_expr(expression, functions)
        }
        Expr::Ternary {
            condition,
            if_true,
            if_false,
            ..
        } => {
            validate_reference_assignment_source_expr(condition, functions)?;
            if let Some(if_true) = if_true {
                validate_reference_assignment_source_expr(if_true, functions)?;
            }
            validate_reference_assignment_source_expr(if_false, functions)
        }
        Expr::Call { .. } => Ok(()),
        _ => Ok(()),
    }
}

fn validate_by_reference_return_value(value: &Expr, function_name: &str) -> Result<()> {
    if expr_is_nullsafe_chain(value) {
        return Err(nullsafe_reference_diagnostic(value.span()));
    }

    match value {
        Expr::Grouped { expr, .. } => validate_by_reference_return_value(expr, function_name),
        Expr::Call { name, span, .. } if name.eq_ignore_ascii_case(function_name) => {
            Err(Diagnostic::new(
                "recursive by-reference returns are unsupported",
                Some(*span),
            ))
        }
        _ => Ok(()),
    }
}

